﻿import React, { useState, useEffect, lazy, Suspense } from 'react';
import { AnimatePresence } from 'framer-motion';
import { Toaster } from 'react-hot-toast';
import { DataProvider, useFleet, useOperations } from './context/DataContext';
import { authService } from './services/api/authService';
import { useUserProfile } from './hooks/useUserProfile';
import { can, ROLES } from './lib/permissions';
const LandingPage            = lazy(() => import('./components/LandingPage'));
const VesselMap               = lazy(() => import('./components/VesselMap'));
const HistoricalMapWidget   = lazy(() => import('./components/HistoricalMapWidget'));
const TelemetryStatusIndicator = lazy(() => import('./components/TelemetryStatusIndicator'));
const WeatherStatusIndicator  = lazy(() => import('./components/WeatherStatusIndicator'));
import TabLoadingSkeleton from './components/TabLoadingSkeleton';



const VesselActivityTab = lazy(() => import('./components/VesselActivityTab'));
const ProductionTargetTab = lazy(() => import('./components/ProductionTargetTab'));
const DBManager = lazy(() => import('./components/DBManager'));
const LogbookWriterTab = lazy(() => import('./components/LogbookWriterTab'));
const StandbySchedule = lazy(() => import('./components/StandbySchedule'));
const RTFTTab = lazy(() => import('./components/RTFTTab'));
const ProfileModal = lazy(() => import('./components/ProfileModal'));
const WeatherAnalyticsTab = lazy(() => import('./components/WeatherAnalyticsTab'));
const DigitalTwinCopilotTab = lazy(() => import('./components/DigitalTwinCopilotTab'));

const MobileDashboard = lazy(() => import('./components/MobileDashboard'));
const MobileCrewActivity = lazy(() => import('./components/MobileCrewActivity'));
const MobileOperatorChat = lazy(() => import('./components/MobileOperatorChat'));
const MobileCrewProfile = lazy(() => import('./components/MobileCrewProfile'));
const MobileCrewNews = lazy(() => import('./components/MobileCrewNews'));
const YardForecastsTab = lazy(() => import('./components/YardForecastsTab'));

import TelemetryAlertBanner from './components/TelemetryAlertBanner';


import { Play, Calendar as CalendarIcon, Download, AlertCircle, ArrowLeft, ArrowRight, History, Clock, Database, Map as MapIcon, Anchor, Info, LogOut, CheckCircle2, ChevronRight, Menu, X, Shield, Settings, ShieldCheck, Mail, Phone, BookOpen, Target, Activity, Send, Cloud, Smartphone, TableProperties } from 'lucide-react';
import './index.css';

function ActivityDashboard({ onSignOut }) {
  const { companyVesselIds, crewVesselId, vesselPositions, geofences } = useFleet();
  const { activities, schedules } = useOperations();
  const { profile, updateProfile } = useUserProfile();
  const [activeTab, setActiveTab] = useState('activity');
  const [mobileTab, setMobileTab] = useState('fleet');
  const [showProfile, setShowProfile] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);

  const [vesselFilter, setVesselFilter] = useState('All');

  useEffect(() => {
    if (profile?.role === 'crew') {
      setMobileTab('activity');
    } else {
      setMobileTab('fleet');
    }
  }, [profile?.role]);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const perms = profile?.permissions || can(profile?.role);

  const { aisTotal, aisSubmitted } = React.useMemo(() => {
    if (!activities) return { aisTotal: 0, aisSubmitted: 0 };
    const filtered = activities.filter(a => {
        const d = new Date(a.startTime);
        const matchesTime = d.getMonth() === new Date().getMonth() && d.getFullYear() === new Date().getFullYear();
        if (!matchesTime) return false;
        if (perms.seeCompanyVessels && companyVesselIds && !companyVesselIds.includes(a.vesselId)) return false;
        if (perms.seeOwnVesselOnly && crewVesselId && a.vesselId !== crewVesselId) return false;
        if (vesselFilter !== 'All' && a.vessel !== vesselFilter) return false;
        return true;
    });
    const submitted = filtered.filter(a => ['submitted', 'approved'].includes(a.logbookStatus)).length;
    return { aisTotal: filtered.length, aisSubmitted: submitted };
  }, [activities, perms, companyVesselIds, crewVesselId, vesselFilter]);

  const offHireVessels = React.useMemo(() => {
      if (!schedules) return {};
      const todayStr = new Date().toISOString().split('T')[0];
      const offHires = {};
      schedules.forEach(s => {
          // Check if schedule is today and it's off hire (handle spaces, dashes, and underscores)
          const name = s.standby_reasons?.name?.toLowerCase() || '';
          const code = s.standby_reasons?.code?.toLowerCase() || '';
          
          if (s.standby_date === todayStr && (name.includes('off hire') || name.includes('off-hire') || code.includes('off_hire'))) {
              offHires[s.vessel_id] = true;
          }
      });
      return offHires;
  }, [schedules]);

  const renderTabContent = () => {
    const commonProps = { vesselFilter, setVesselFilter };
    return (
      <AnimatePresence mode="wait">
        <motion.div key={activeTab} initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} transition={{ duration: 0.3 }} className="w-full">
          <Suspense fallback={<TabLoadingSkeleton />}>
            {(() => {
              switch(activeTab) {
                case 'activity': return <VesselActivityTab view="to-submit" {...commonProps} />;
                case 'logbook-entry': return <VesselActivityTab view="submitted" {...commonProps} />;
                case 'schedule': return <StandbySchedule />;
                case 'rtft': return <RTFTTab />;
                case 'production': return <ProductionTargetTab />;
                case 'dbmanager': return <DBManager />;

                case 'weather-analytics': return <WeatherAnalyticsTab />;
                case 'yard-forecasts': return <YardForecastsTab />;
                case 'copilot': return <DigitalTwinCopilotTab />;
                default: return <VesselActivityTab {...commonProps} />;
              }
            })()}
          </Suspense>
        </motion.div>
      </AnimatePresence>
    );
  };

  const showMobile = (profile?.role === ROLES.CREW || [ROLES.OPERATION, ROLES.OPERATION_ADMIN].includes(profile?.role)) && isMobile;

  const mobileNavItems = [
    { id: 'activity', label: 'Activity', icon: Activity },
    { id: 'logbook-entry', label: 'Logbook', icon: Edit3, permission: perms.submitLogbook },
    { id: 'fleet', label: 'Fleet', icon: MapIcon },
    { id: 'chat', label: 'Chat', icon: MessageSquare },
    { id: 'profile', label: 'Profile', icon: User },
  ].filter(item => item.permission !== false);

  if (showMobile) {
    return (
      <Suspense fallback={<div className="min-h-screen bg-slate-50 flex items-center justify-center"><Anchor size={48} className="animate-spin text-primary opacity-20" /></div>}>
        <MobileDashboard 
          onSignOut={onSignOut} 
          activeTab={mobileTab} 
          setActiveTab={setMobileTab} 
          aisTotal={aisTotal} 
          aisSubmitted={aisSubmitted}
          navItems={mobileNavItems}
        >
          {mobileTab === 'activity' && <MobileCrewActivity tab="all" />}
          {mobileTab === 'logbook-entry' && <MobileCrewActivity tab="submitted" />}
          {mobileTab === 'schedule' && <StandbySchedule />}
          {mobileTab === 'fleet' && <div className="h-[60vh] rounded-xl overflow-hidden shadow-lg border border-surface-low/50"><HistoricalMapWidget height="100%" /></div>}
          {mobileTab === 'chat' && <MobileOperatorChat profile={profile} />}
          {mobileTab === 'profile' && <MobileCrewProfile />}
        </MobileDashboard>
      </Suspense>
    );
  }

  return (
    <div className="min-h-screen bg-[#f7f9fb] font-manrope text-on-surface selection:bg-primary/20">
      
      <header className="fixed top-0 left-0 right-0 z-50 bg-white/90 backdrop-blur-xl border-b border-surface-low/30 h-16 sm:h-20 lg:h-24 px-6 sm:px-10 lg:px-16 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-4 lg:gap-6">
          <div className="w-10 h-10 lg:w-14 lg:h-14 rounded-2xl bg-primary flex items-center justify-center shadow-lg shadow-primary/30 border border-white/20"><Anchor className="text-white w-6 h-6 lg:w-8 lg:h-8" /></div>
          <div className="flex flex-col">
            <h1 className="font-manrope font-extrabold text-xl lg:text-2xl text-on-surface tracking-tight leading-none mb-1">GeoKanban <span className="text-[10px] font-bold text-primary/40 align-top ml-1">v3.25</span></h1>
            <p className="text-[10px] lg:text-xs font-black text-primary uppercase tracking-[0.2em] opacity-80 leading-none">Breakwater Fleet Tracker â€” Genova</p>
          </div>
        </div>
        <div className="flex items-center gap-4 lg:gap-6">
          {profile && (
            <div className="hidden sm:flex flex-col items-end">
              <span className="text-sm font-extrabold text-on-surface leading-none mb-1">{profile.displayName}</span>
              <span className="text-[9px] font-black text-on-surface/40 uppercase tracking-widest leading-none">{profile.role?.replace('_', ' ')}</span>
            </div>
          )}
          <div className="flex items-center gap-3">
            <Suspense fallback={null}><TelemetryStatusIndicator /></Suspense>
            <Suspense fallback={null}><WeatherStatusIndicator /></Suspense>
          </div>
          <button onClick={() => setShowProfile(true)} className="w-10 h-10 lg:w-12 lg:h-12 rounded-full bg-gradient-to-br from-surface-low to-surface-lowest flex items-center justify-center border border-white shadow-sm active:scale-90 transition-transform"><div className="w-8 h-8 lg:w-10 lg:h-10 rounded-full bg-primary/10 flex items-center justify-center font-bold text-primary lg:text-lg">{(profile?.displayName || 'G')[0]}</div></button>
        </div>
      </header>

      <main className="pt-20 sm:pt-24 lg:pt-28 px-6 sm:px-10 lg:px-16 max-w-[2100px] mx-auto pb-12">
        <TelemetryAlertBanner />
        {activeTab === 'activity' && (
          <div className="mb-8 bg-white/50 backdrop-blur-md rounded-[2.5rem] p-4 border border-white shadow-sm">
            <div className="flex items-center gap-2 mb-4 px-4 py-2 bg-sky-50 rounded-full w-fit border border-sky-200 shadow-sm">
              <div className="w-2 h-2 bg-sky-500 rounded-full" />
              <span className="text-[10px] font-black text-sky-700 uppercase tracking-widest leading-none">T+1 Certified Historical Tracker</span>
            </div>
            <div className="rounded-[1.5rem] overflow-hidden border border-surface-low/20">
              <Suspense fallback={<div className="h-[350px] rounded-[1.5rem] bg-slate-100 animate-pulse" />}>
                <HistoricalMapWidget height="350px" />
              </Suspense>
            </div>
          </div>
        )}

        <nav className="bg-white/50 backdrop-blur-md rounded-[2.5rem] p-2 mb-8 sm:mb-12 border border-white flex flex-wrap items-center gap-1 shadow-sm overflow-x-auto scrollbar-hide relative z-[100]">
          {[
            { id: 'activity', label: 'Vessel Activities', icon: Activity, subLabel: aisTotal > 0 ? `${aisTotal}` : null },
            { id: 'logbook-entry', label: 'Submitted Logbooks', icon: Edit3, subLabel: aisTotal > 0 ? `${aisSubmitted}/${aisTotal}` : null, permission: perms.seeSubmittedLogbooks },
            { id: 'yard-forecasts', label: 'Yard Forecasts', icon: Cloud, permission: perms.seeWeatherAnalytics },
            { id: 'copilot', label: 'Copilot AI', icon: Bot, permission: perms.seeCopilot },
            { 
              id: 'schedule', 
              label: 'Schedule', 
              icon: Calendar, 
              permission: perms.seeSchedule,
              hasNotification: !perms.seeOwnVesselOnly && (schedules || []).some(s => s.is_approved === false || s.is_approved === null)
            },
            { id: 'rtft', label: 'RTFT', icon: MapIcon, permission: perms.seeRewindMap },
            { id: 'production', label: 'Production Targets', icon: perms.seeProductionTargets ? Target : null, permission: perms.seeProductionTargets },
            { id: 'weather-analytics', label: 'Weather Analytics', icon: Cloud, permission: perms.seeWeatherAnalytics },

            { id: 'dbmanager', label: 'DB Manager', icon: Database, permission: perms.accessDBManager },
          ].filter(item => item.permission !== false).map((item) => (
            <button key={item.id} onClick={() => setActiveTab(item.id)} className={`flex flex-col items-center justify-center min-w-[120px] lg:min-w-[160px] px-4 lg:px-6 py-3 lg:py-4 rounded-[2rem] tracking-tight transition-all duration-300 relative ${activeTab === item.id ? 'bg-primary text-white shadow-lg' : 'text-on-surface/50 hover:text-on-surface'}`}>
              <div className="flex items-center gap-2 lg:gap-3">
                <item.icon size={16} />
                <span className="text-xs lg:text-sm font-extrabold">{item.label}</span>
                {item.hasNotification && (
                  <div className="absolute -top-1 -right-1 w-4 h-4 bg-red-600 rounded-full border-2 border-white shadow-sm flex items-center justify-center animate-pulse">
                    <div className="w-1.5 h-1.5 bg-white rounded-full" />
                  </div>
                )}
              </div>
              {item.subLabel && <span className={`text-[10px] font-black mt-1 opacity-60 ${activeTab === item.id ? 'text-white' : 'text-primary'}`}>{item.subLabel}</span>}
            </button>
          ))}
        </nav>

        <div className="tab-content-container">{renderTabContent()}</div>
      </main>

      {showProfile && <Suspense fallback={null}><ProfileModal profile={profile} onClose={() => setShowProfile(false)} onSignOut={onSignOut} updateProfile={updateProfile} /></Suspense>}
    </div>
  );
}

export default function App() {
  const [user, setUser] = useState(null);
  const [checkingAuth, setCheckingAuth] = useState(true);

  useEffect(() => {
    const handleSession = async (session) => {
      if (!session?.user) {
        setUser(null);
        setCheckingAuth(false);
        return;
      }

      const { data: profile } = await authService.getProfile(session.user.id);
      const role = profile?.role || 'crew';

      setUser({ id: session.user.id, email: session.user.email, role: role });
      setCheckingAuth(false);
    };

    authService.getSession().then(({ data: { session } }) => handleSession(session));
    const { data: { subscription } } = authService.onAuthStateChange((_event, session) => {
      if (!session?.user || _event === 'SIGNED_OUT') setUser(null);
    });
    return () => subscription.unsubscribe();
  }, []);

  if (checkingAuth) return <div className="loading-screen"><Anchor size={48} className="spin" /><p>Loading...</p></div>;
  if (!user) return <Suspense fallback={null}><LandingPage onLogin={setUser} /></Suspense>;
  return <DataProvider><Toaster position="bottom-right" /><ActivityDashboard onSignOut={() => authService.signOut()} /></DataProvider>;
}

import React, { useState, useEffect, useRef } from 'react';
import { messagesService } from '../services/api/messagesService';
import { X, Send, MessageSquare } from 'lucide-react';
import '../logbook-writer.css';

export default function ActivityChatModal({ activity, profile, onClose, readOnly = false }) {
    const [messages, setMessages] = useState([]);
    const [newMessage, setNewMessage] = useState('');
    const [loading, setLoading] = useState(true);
    const messagesEndRef = useRef(null);

    const fetchMessages = async () => {
        if (!activity?.id) return;
        setLoading(true);
        try {
            const data = await messagesService.fetchMessagesForActivity(activity.id);
            setMessages(data);

            if (profile?.role && !readOnly) {
                messagesService.markAsRead(activity.id, profile.role);
            }
        } catch (error) {
            console.error('❌ Errore durante il caricamento dei messaggi:', error.message || error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (!activity?.id) return;

        fetchMessages();

        // Subscribe to new messages for this activity
        const channel = messagesService.subscribeToActivity(activity.id, () => {
            fetchMessages(); // Reload to get sender info
        });

        return () => {
            messagesService.unsubscribe(channel);
        };
    }, [activity?.id]);

    useEffect(() => {
        if (!readOnly) {
            messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
        }
    }, [messages, readOnly]);

    const handleSend = async (e) => {
        e.preventDefault();
        if (!newMessage.trim() || !profile || readOnly) return;

        try {
            await messagesService.sendMessage({
                activityId: activity.id,
                senderId: profile.id,
                senderRole: profile.role || 'crew',
                messageText: newMessage.trim(),
            });
            setNewMessage('');
            fetchMessages(); // Aggiorna istantaneamente la lista
        } catch (err) {
            console.error('Error sending message:', err);
        }
    };

    return (
        <div className="lem-overlay" onClick={onClose}>
            <div className={`chat-modal ${readOnly ? 'readonly-mode' : ''}`} onClick={e => e.stopPropagation()}>
                <div className="chat-header">
                    <div className="lem-title-row">
                        <MessageSquare size={18} />
                        <h2>{readOnly ? 'Activity History & Notes' : `Chat: ${activity?.activity}`}</h2>
                        <span className="lem-badge" style={{ background: '#3b82f6' }}>{activity?.vessel}</span>
                    </div>
                    <button className="lem-close" onClick={onClose}><X size={18} /></button>
                </div>

                <div className="chat-body">
                    {loading ? (
                        <div style={{ textAlign: 'center', padding: 20 }}>Loading notes...</div>
                    ) : messages.length === 0 ? (
                        <div className="chat-empty">No notes or messages for this activity.</div>
                    ) : (
                        <div className={readOnly ? 'notes-container' : 'bubbles-container'}>
                            {messages.map(m => {
                                const isMine = m.sender_id === profile?.id;
                                const d = new Date(m.created_at);
                                const timeStr = d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                                
                                if (readOnly) {
                                    return (
                                        <div key={m.id} className="note-item">
                                            <span className="note-timestamp">[{timeStr}]</span>
                                            <span className="note-sender">{m.user_profiles?.display_name || 'System'}:</span>
                                            <span className="note-text">{m.message_text}</span>
                                        </div>
                                    );
                                }

                                return (
                                    <div key={m.id} className={`chat-bubble ${isMine ? 'mine' : 'theirs'}`}>
                                        <div className="chat-meta">
                                            <span className="chat-sender">{m.user_profiles?.display_name || 'Admin'}</span>
                                            <span className="chat-time">{timeStr}</span>
                                        </div>
                                        <div className="chat-text">{m.message_text}</div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                    <div ref={messagesEndRef} />
                </div>

                {!readOnly && (
                    <form className="chat-footer" onSubmit={handleSend}>
                        <input
                            className="chat-input"
                            placeholder="Type a message..."
                            value={newMessage}
                            onChange={e => setNewMessage(e.target.value)}
                            autoFocus
                        />
                        <button type="submit" className="chat-send" disabled={!newMessage.trim()}>
                            <Send size={16} />
                        </button>
                    </form>
                )}
                {readOnly && (
                    <div className="chat-footer-readonly">
                        <span>Communication closed for this flow. Read-only access.</span>
                    </div>
                )}
            </div>
        </div>
    );
}

﻿import React, { useState } from 'react';
import { X, UserPlus, Mail, User, Shield, Anchor, Map as MapIcon, BookOpen, Layers, Globe, CheckCircle2, AlertCircle, Eye, EyeOff, RefreshCw, Calendar, Rewind, Target, Cloud, Box, Database, Unlock, Edit2 } from 'lucide-react';
import { userService } from '../services/api/userService';

export default function AddUserModal({ onClose, onUserAdded, companies, vessels = [] }) {
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState(false);

    // Form State
    const [form, setForm] = useState({
        email: '',
        displayName: '',
        role: 'crew',
        companyId: '',
        vesselId: '',
        mmsi: '',
        password: Math.random().toString(36).slice(-8) // Password random iniziale
    });

    // Custom Permissions (Ibridi)
    const [perms, setPerms] = useState({
        show_map: false,
        access_logbook: true,
        see_all_vessels: false,
        admin_dashboard: false,
        see_logbook_submitted: true,
        see_schedule: true,
        edit_schedule: true,
        see_rewind: false,
        see_production: false,
        see_weather: true,
        see_3d: true,
        see_dbmanager: false
    });

    const [showPassword, setShowPassword] = useState(false);

    const togglePerm = (k) => setPerms(p => ({ ...p, [k]: !p[k] }));

    const handleInvite = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        try {
            // STEP 1: Creazione utente tramite RPC (Richiede funzione DB specifica 'invite_user_v3')
            // Se la RPC non esiste ancora, usiamo l'inserimento diretto nel profilo come simulazione (o gestiamo l'invito vero)
            const { data, error: inviteError } = await userService.createUser({
                email: form.email,
                password: form.password,
                displayName: form.displayName,
                role: form.role,
                companyId: form.companyId,
                vesselId: form.vesselId,
                mmsi: form.mmsi,
                customOverrides: perms
            });

            setSuccess(true);
            setTimeout(() => {
                onUserAdded();
                onClose();
            }, 2000);

        } catch (err) {
            setError(err.message || 'Errore durante la creazione utente. Assicurati che l\'email sia univoca.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-on-surface/20 backdrop-blur-sm" onClick={onClose} />
            
            <div className="relative bg-white rounded-[3rem] w-full max-w-2xl shadow-2xl overflow-hidden animate-in zoom-in duration-300">
                {/* Header */}
                <div className="bg-primary p-8 text-white relative">
                    <button onClick={onClose} className="absolute top-6 right-6 w-10 h-10 rounded-full bg-white/10 flex items-center justify-center hover:bg-white/20 transition-all">
                        <X size={20} />
                    </button>
                    <div className="w-16 h-16 rounded-3xl bg-white/10 flex items-center justify-center mb-4">
                        <UserPlus size={32} />
                    </div>
                    <h2 className="text-3xl font-manrope font-extrabold tracking-tight">Add New User</h2>
                    <p className="text-white/60 text-sm font-bold uppercase tracking-widest mt-1">Configura credenziali e permessi ibridi</p>
                </div>

                <form onSubmit={handleInvite} className="p-8 lg:p-12 space-y-8 max-h-[70vh] overflow-y-auto scrollbar-hide">
                    {success ? (
                        <div className="flex flex-col items-center justify-center py-20 text-center animate-in fade-in zoom-in">
                            <div className="w-20 h-20 rounded-full bg-green-500 text-white flex items-center justify-center mb-6 shadow-xl shadow-green-200">
                                <CheckCircle2 size={40} />
                            </div>
                            <h3 className="text-2xl font-manrope font-extrabold text-on-surface">User Created!</h3>
                            <p className="text-on-surface/40 font-bold mt-2">Le credenziali sono state salvate con successo.</p>
                        </div>
                    ) : (
                        <>
                            {/* Section: Anagrafica */}
                            <div className="space-y-4">
                                <div className="text-[10px] font-black text-on-surface/20 uppercase tracking-[0.2em] mb-4">Account Information</div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div className="space-y-1.5">
                                        <label className="text-[10px] font-black text-on-surface/40 uppercase tracking-widest ml-4">Full Name</label>
                                        <div className="flex items-center gap-3 px-6 py-4 bg-surface-low/30 rounded-full border border-surface-low/50">
                                            <User size={18} className="text-on-surface/20" />
                                            <input required type="text" placeholder="Giacomo Rossi" className="bg-transparent border-none outline-none w-full font-bold text-sm" value={form.displayName} onChange={e => setForm({...form, displayName: e.target.value})} />
                                        </div>
                                    </div>
                                    <div className="space-y-1.5">
                                        <label className="text-[10px] font-black text-on-surface/40 uppercase tracking-widest ml-4">Email Address</label>
                                        <div className="flex items-center gap-3 px-6 py-4 bg-surface-low/30 rounded-full border border-surface-low/50">
                                            <Mail size={18} className="text-on-surface/20" />
                                            <input required type="email" placeholder="user@gmail.com" className="bg-transparent border-none outline-none w-full font-bold text-sm" value={form.email} onChange={e => setForm({...form, email: e.target.value})} />
                                        </div>
                                    </div>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div className="space-y-1.5">
                                        <label className="text-[10px] font-black text-on-surface/40 uppercase tracking-widest ml-4">Initial Password</label>
                                        <div className="relative flex items-center gap-3 px-6 py-4 bg-surface-low/30 rounded-full border border-surface-low/50">
                                            <Shield size={18} className="text-on-surface/20" />
                                            <input 
                                                required 
                                                type={showPassword ? "text" : "password"} 
                                                placeholder="Password" 
                                                className="bg-transparent border-none outline-none w-full font-black text-sm text-primary pr-10" 
                                                value={form.password} 
                                                onChange={e => setForm({...form, password: e.target.value})} 
                                            />
                                            <button 
                                                type="button"
                                                onClick={() => setShowPassword(!showPassword)}
                                                className="absolute right-6 text-primary/30 hover:text-primary transition-colors"
                                            >
                                                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                                            </button>
                                        </div>
                                    </div>
                                    <div className="space-y-1.5">
                                        <label className="text-[10px] font-black text-on-surface/40 uppercase tracking-widest ml-4">Primary Role</label>
                                        <div className="flex items-center gap-3 px-6 py-4 bg-surface-low/30 rounded-full border border-surface-low/50">
                                            <Globe size={18} className="text-on-surface/20" />
                                            <select className="bg-transparent border-none outline-none w-full font-bold text-sm" value={form.role} onChange={e => setForm({...form, role: e.target.value})}>
                                                <option value="crew">Crew Member</option>
                                                <option value="crew_admin">Crew Admin (Fleet)</option>
                                                <option value="operation">Operations Member</option>
                                                <option value="operation_admin">Operations Admin</option>
                                            </select>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Section: Hybrid Permissions */}
                            <div className="space-y-4">
                                <div className="text-[10px] font-black text-on-surface/20 uppercase tracking-[0.2em] mb-4">Hybrid Permissions (Overlays)</div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                    {[
                                        { id: 'show_map', label: 'View Live Map', desc: 'Sblocca mappa flotta live', icon: MapIcon },
                                        { id: 'access_logbook', label: 'Certified Logbook', desc: 'Invio ed edit per sottomissione', icon: BookOpen },
                                        { id: 'see_all_vessels', label: 'Global Fleet View', desc: 'Vede tutte le navi', icon: Globe },
                                        { id: 'admin_dashboard', label: 'Admin Dashboard', desc: 'Accesso a Dashboard Admin', icon: Shield },
                                        { id: 'see_logbook_submitted', label: 'Submitted Logbooks Tab', desc: 'VisibilitÃ  logbooks sottomessi', icon: Edit2 },
                                        { id: 'see_schedule', label: 'Schedule Tab', desc: 'VisibilitÃ  tab pianificazione', icon: Calendar },
                                        { id: 'edit_schedule', label: 'Edit Schedule', desc: 'Abilita modifiche a calendario', icon: Unlock },
                                        { id: 'see_rewind', label: 'Rewind Tab', desc: 'VisibilitÃ  tab Mission Rewind', icon: Rewind },
                                        { id: 'see_production', label: 'Production Tab', desc: 'VisibilitÃ  tab Production Targets', icon: Target },
                                        { id: 'see_weather', label: 'Weather Tab', desc: 'VisibilitÃ  tab Weather Analytics', icon: Cloud },
                                        { id: 'see_3d', label: '3D Tab', desc: 'VisibilitÃ  tab 3D Viewer', icon: Box },
                                        { id: 'see_dbmanager', label: 'DB Manager Tab', desc: 'VisibilitÃ  tab DB Manager', icon: Database }
                                    ].map(p => (
                                        <button 
                                            key={p.id}
                                            type="button"
                                            onClick={() => togglePerm(p.id)}
                                            className={`flex items-center gap-4 p-4 rounded-3xl border transition-all text-left ${perms[p.id] ? 'bg-primary/5 border-primary/20 shadow-sm' : 'bg-white border-surface-low/30 opacity-60'}`}
                                        >
                                            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${perms[p.id] ? 'bg-primary text-white' : 'bg-surface-low text-on-surface/20'}`}>
                                                <p.icon size={20} />
                                            </div>
                                            <div className="flex-1">
                                                <div className={`text-xs font-black uppercase tracking-tight ${perms[p.id] ? 'text-primary' : 'text-on-surface/40'}`}>{p.label}</div>
                                                <div className="text-[10px] font-bold text-on-surface/30 leading-none mt-0.5">{p.desc}</div>
                                            </div>
                                            <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all ${perms[p.id] ? 'bg-primary border-primary text-white' : 'border-surface-low'}`}>
                                                {perms[p.id] && <CheckCircle2 size={12} />}
                                            </div>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Nav / MMSI Optional */}
                            {form.role === 'crew' && (
                                <div className="bg-green-600 rounded-3xl p-6 flex gap-4 border border-green-700 shadow-xl shadow-green-600/20 text-white text-xs font-bold animate-in slide-in-from-top duration-500">
                                    <div className="w-12 h-12 rounded-2xl bg-white/20 flex items-center justify-center flex-shrink-0 backdrop-blur-sm border border-white/30"><Anchor size={24} className="text-white" /></div>
                                    <div className="w-full">
                                        <span className="text-green-50 tracking-wide">Associando un MMSI, l'utente sarÃ  automaticamente vincolato a quella nave nelle notifiche e nei filtri di default.</span>
                                        <select 
                                            className="mt-3 block w-full bg-white border-2 border-white rounded-full px-5 py-3 text-sm outline-none text-green-900 font-black shadow-inner cursor-pointer hover:bg-green-50 transition-colors"
                                            value={form.vesselId}
                                            onChange={e => {
                                                const vId = e.target.value;
                                                const v = vessels.find(x => x.id === vId);
                                                setForm({...form, vesselId: vId, mmsi: v?.mmsi || ''});
                                            }}
                                        >
                                            <option value="">Nessuna Nave Associata</option>
                                            {vessels.map(v => (
                                                <option key={v.id} value={v.id}>{v.name} ({v.mmsi})</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>
                            )}

                            {error && (
                                <div className="bg-red-50 border border-red-100 rounded-3xl p-4 flex items-center gap-3 text-red-600">
                                    <AlertCircle size={18} />
                                    <span className="text-xs font-extrabold uppercase tracking-tight">{error}</span>
                                </div>
                            )}

                            {/* Submit */}
                            <button 
                                disabled={loading}
                                className="w-full bg-primary hover:bg-primary-dark text-white p-6 rounded-[2rem] font-manrope font-extrabold text-lg uppercase tracking-widest shadow-xl shadow-primary/20 transition-all flex items-center justify-center gap-3"
                            >
                                {loading ? <RefreshCw size={24} className="animate-spin" /> : <><UserPlus size={24} /> Create User Account</>}
                            </button>
                        </>
                    )}
                </form>
            </div>
        </div>
    );
}

﻿import React, { useState, useMemo, useEffect } from 'react';
import { X, Ship, Clock, MapPin, Activity, Check, AlertCircle } from 'lucide-react';
import { useFleet, useConfig } from '../context/DataContext';
import { activityService } from '../services/api/activityService';
import { formatTime } from '../utils/timeFormatters';
import { HOURS, MINUTES } from '../constants/timeConstants';

const ACTIVITY_TYPES = [
    'Loading', 'Unloading', 'Navigation', 'Stand-by', 'Port Operations', 'Mooring'
];

export default function EditActivityModal({ activityToEdit, onClose, onSaved }) {
    const { vessels, geofences } = useFleet();
    const { profile } = useConfig();

    // Must be operation_admin
    const isOperationAdmin = profile?.role === 'operation_admin';

    const getLocalParts = (dStr) => {
        if (!dStr) return { date: '', hour: '00', minute: '00' };
        const d = new Date(dStr);
        if (isNaN(d.getTime())) return { date: '', hour: '00', minute: '00' };
        const yyyy = d.getFullYear();
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        const hh = String(d.getHours()).padStart(2, '0');
        const min = String(d.getMinutes()).padStart(2, '0');
        return {
            date: `${yyyy}-${mm}-${dd}`,
            hour: hh,
            minute: min
        };
    };

    const [vesselId, setVesselId] = useState('');
    const [activityType, setActivityType] = useState('Loading');
    const [geofenceId, setGeofenceId] = useState('');
    const [geofenceFromId, setGeofenceFromId] = useState('');
    const [geofenceToId, setGeofenceToId] = useState('');

    const [ataDate, setAtaDate] = useState('');
    const [ataHour, setAtaHour] = useState('00');
    const [ataMinute, setAtaMinute] = useState('00');

    const [atdDate, setAtdDate] = useState('');
    const [atdHour, setAtdHour] = useState('00');
    const [atdMinute, setAtdMinute] = useState('00');
    const [hasAtd, setHasAtd] = useState(false);

    const [submitting, setSubmitting] = useState(false);
    const [error, setError] = useState(null);

    // Initialize state from activityToEdit
    useEffect(() => {
        if (activityToEdit) {
            setVesselId(activityToEdit.vessel_id || activityToEdit.vesselId || '');
            setActivityType(activityToEdit.activity_type || activityToEdit.activity || 'Loading');
            setGeofenceId(activityToEdit.geofence_id || activityToEdit.geofenceId || '');
            setGeofenceFromId(activityToEdit.geofence_from_id || activityToEdit.geofenceFromId || '');
            setGeofenceToId(activityToEdit.geofence_to_id || activityToEdit.geofenceToId || '');

            const startParts = getLocalParts(activityToEdit.start_time || activityToEdit.startTime);
            setAtaDate(startParts.date);
            setAtaHour(startParts.hour);
            setAtaMinute(startParts.minute);

            const endStr = activityToEdit.end_time || activityToEdit.endTime;
            if (endStr) {
                setHasAtd(true);
                const endParts = getLocalParts(endStr);
                setAtdDate(endParts.date);
                setAtdHour(endParts.hour);
                setAtdMinute(endParts.minute);
            } else {
                setHasAtd(false);
                const endParts = getLocalParts(); // now
                setAtdDate(endParts.date);
                setAtdHour(endParts.hour);
                setAtdMinute(endParts.minute);
            }
        }
    }, [activityToEdit]);

    // Build ISO timestamps
    const startTimeISO = useMemo(() => {
        if (!ataDate || !ataHour || !ataMinute) return null;
        try {
            const dateObj = new Date(`${ataDate}T${ataHour}:${ataMinute}:00`);
            return isNaN(dateObj.getTime()) ? null : dateObj.toISOString();
        } catch {
            return null;
        }
    }, [ataDate, ataHour, ataMinute]);

    const endTimeISO = useMemo(() => {
        if (!hasAtd || !atdDate || !atdHour || !atdMinute) return null;
        try {
            const dateObj = new Date(`${atdDate}T${atdHour}:${atdMinute}:00`);
            return isNaN(dateObj.getTime()) ? null : dateObj.toISOString();
        } catch {
            return null;
        }
    }, [hasAtd, atdDate, atdHour, atdMinute]);

    // Calculate real-time duration
    const durationText = useMemo(() => {
        if (!startTimeISO) return 'â€”';
        if (!hasAtd) return 'In Progress (Active)';
        if (!endTimeISO) return 'â€”';
        const start = new Date(startTimeISO);
        const end = new Date(endTimeISO);
        const diffMs = end - start;
        if (diffMs < 0) return 'Invalid Range';
        const diffMins = Math.floor(diffMs / 60000);
        const hrs = Math.floor(diffMins / 60);
        const mins = diffMins % 60;
        return `${hrs}h ${mins}m`;
    }, [startTimeISO, endTimeISO, hasAtd]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!isOperationAdmin) return setError('Permission denied.');
        if (!vesselId) return setError('Please select a vessel.');
        if (!activityType) return setError('Please select an activity.');

        if (activityType === 'Navigation') {
            if (!geofenceFromId) return setError('Please select departure geofence (Geofence From).');
            if (!geofenceToId) return setError('Please select arrival geofence (Geofence To).');
        } else {
            if (!geofenceId) return setError('Please select the location / geofence hub.');
        }

        if (!startTimeISO) return setError('Please select a valid arrival time (ATA).');
        if (hasAtd && !endTimeISO) return setError('Please select a valid departure time (ATD).');

        if (hasAtd && startTimeISO && endTimeISO && new Date(startTimeISO) >= new Date(endTimeISO)) {
            return setError('Arrival time (ATA) must be before Departure time (ATD).');
        }

        setSubmitting(true);
        setError(null);

        try {
            const updates = {
                vessel_id: vesselId,
                activity_type: activityType,
                geofence_id: activityType === 'Navigation' ? null : (geofenceId || null),
                geofence_from_id: activityType === 'Navigation' ? (geofenceFromId || null) : (geofenceId || null),
                geofence_to_id: activityType === 'Navigation' ? (geofenceToId || null) : (geofenceId || null),
                start_time: startTimeISO,
                end_time: hasAtd ? endTimeISO : null,
                status: hasAtd ? 'completed' : 'active'
            };

            await activityService.updateActivity(activityToEdit.id, updates);

            onSaved();
            onClose();
        } catch (err) {
            console.error('Error editing activity:', err);
            setError(err.message || 'An error occurred while editing the activity.');
        } finally {
            setSubmitting(false);
        }
    };

    if (!isOperationAdmin) return null;

    return (
        <div className="lem-overlay animate-in fade-in duration-200" onClick={onClose}>
            <div className="lem-modal max-w-md w-full glassmorphic rounded-[1.5rem] border border-white/20 shadow-2xl p-4 md:p-5 animate-in zoom-in-95 duration-200" style={{ maxHeight: '85vh', overflowY: 'auto' }} onClick={e => e.stopPropagation()}>
                
                {/* Header */}
                <div className="flex items-center justify-between pb-3 border-b border-surface-low/10 mb-4">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-blue-500/10 flex items-center justify-center text-blue-600">
                            <Activity size={20} />
                        </div>
                        <div>
                            <h2 className="text-lg font-manrope font-black text-on-surface uppercase tracking-tight">Edit Activity</h2>
                            <p className="text-[10px] text-on-surface/40 uppercase tracking-widest font-black">Admin Override</p>
                        </div>
                    </div>
                    <button className="w-8 h-8 rounded-full bg-surface-low/10 flex items-center justify-center text-on-surface/40 hover:text-on-surface hover:bg-surface-low/20 transition-all" onClick={onClose}>
                        <X size={16} />
                    </button>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="space-y-3">
                    {error && (
                        <div className="flex items-center gap-2 bg-red-50 text-red-600 p-3 rounded-xl text-xs font-semibold border border-red-100 animate-in shake duration-300">
                            <AlertCircle size={14} className="flex-shrink-0" />
                            <span>{error}</span>
                        </div>
                    )}

                    {/* Vessel Dropdown */}
                    <div className="flex flex-col gap-1">
                        <label className="text-[10px] font-black uppercase text-on-surface/40 tracking-wider flex items-center gap-1">
                            <Ship size={12} /> Vessel / Ship Name
                        </label>
                        <select 
                            value={vesselId} 
                            onChange={e => setVesselId(e.target.value)}
                            className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-500 outline-none focus:border-blue-500 transition-all cursor-pointer" style={{ color: '#64748b' }}
                            required
                        >
                            <option value="">Select vessel</option>
                            {(vessels || []).map(v => (
                                <option key={v.id} value={v.id}>{v.name}</option>
                            ))}
                        </select>
                    </div>

                    {/* Activity Type Dropdown */}
                    <div className="flex flex-col gap-1">
                        <label className="text-[10px] font-black uppercase text-on-surface/40 tracking-wider flex items-center gap-1">
                            <Activity size={12} /> Activity Type
                        </label>
                        <select 
                            value={activityType} 
                            onChange={e => setActivityType(e.target.value)}
                            className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-500 outline-none focus:border-blue-500 transition-all cursor-pointer" style={{ color: '#64748b' }}
                            required
                        >
                            {ACTIVITY_TYPES.map(type => (
                                <option key={type} value={type}>{type}</option>
                            ))}
                        </select>
                    </div>

                    {/* Geofence Selector(s) */}
                    {activityType === 'Navigation' ? (
                        <div className="grid grid-cols-2 gap-2">
                            <div className="flex flex-col gap-1">
                                <label className="text-[10px] font-black uppercase text-on-surface/40 tracking-wider flex items-center gap-1">
                                    <MapPin size={12} /> Geofence From
                                </label>
                                <select 
                                    value={geofenceFromId} 
                                    onChange={e => setGeofenceFromId(e.target.value)}
                                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-500 outline-none focus:border-blue-500 transition-all cursor-pointer" style={{ color: '#64748b' }}
                                    required
                                >
                                    <option value="">Select departure</option>
                                    {(geofences || []).map(g => (
                                        <option key={g.id} value={g.id}>{g.name} ({g.nature})</option>
                                    ))}
                                </select>
                            </div>
                            <div className="flex flex-col gap-1">
                                <label className="text-[10px] font-black uppercase text-on-surface/40 tracking-wider flex items-center gap-1">
                                    <MapPin size={12} /> Geofence To
                                </label>
                                <select 
                                    value={geofenceToId} 
                                    onChange={e => setGeofenceToId(e.target.value)}
                                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-500 outline-none focus:border-blue-500 transition-all cursor-pointer" style={{ color: '#64748b' }}
                                    required
                                >
                                    <option value="">Select arrival</option>
                                    {(geofences || []).map(g => (
                                        <option key={g.id} value={g.id}>{g.name} ({g.nature})</option>
                                    ))}
                                </select>
                            </div>
                        </div>
                    ) : (
                        <div className="flex flex-col gap-1">
                            <label className="text-[10px] font-black uppercase text-on-surface/40 tracking-wider flex items-center gap-1">
                                <MapPin size={12} /> Location / Geofence Hub
                            </label>
                            <select 
                                value={geofenceId} 
                                onChange={e => setGeofenceId(e.target.value)}
                                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-500 outline-none focus:border-blue-500 transition-all cursor-pointer" style={{ color: '#64748b' }}
                                required
                            >
                                <option value="">Select geofence</option>
                                {(geofences || []).map(g => (
                                    <option key={g.id} value={g.id}>{g.name} ({g.nature})</option>
                                ))}
                            </select>
                        </div>
                    )}

                    {/* Arrival ATA */}
                    <div className="flex flex-col gap-1">
                        <label className="text-[10px] font-black uppercase text-on-surface/40 tracking-wider flex items-center gap-1">
                            <Clock size={12} /> Start Time (ATA)
                        </label>
                        <div className="grid grid-cols-12 gap-2">
                            <div className="col-span-6">
                                <input 
                                    type="date" 
                                    value={ataDate} 
                                    onChange={e => setAtaDate(e.target.value)}
                                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-500 outline-none focus:border-blue-500 transition-all cursor-pointer" style={{ color: '#64748b' }}
                                    required
                                />
                            </div>
                            <div className="col-span-3">
                                <select 
                                    value={ataHour} 
                                    onChange={e => setAtaHour(e.target.value)}
                                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-500 outline-none focus:border-blue-500 transition-all cursor-pointer" style={{ color: '#64748b' }}
                                    required
                                >
                                    {HOURS.map(h => <option key={h} value={h}>{h}</option>)}
                                </select>
                            </div>
                            <div className="col-span-3">
                                <select 
                                    value={ataMinute} 
                                    onChange={e => setAtaMinute(e.target.value)}
                                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-500 outline-none focus:border-blue-500 transition-all cursor-pointer" style={{ color: '#64748b' }}
                                    required
                                >
                                    {MINUTES.map(m => <option key={m} value={m}>{m}</option>)}
                                </select>
                            </div>
                        </div>
                    </div>

                    {/* Activity Status Toggle */}
                    <div className="flex items-center justify-between bg-slate-100 border border-slate-200 p-3 rounded-xl mt-4 mb-2 shadow-sm">
                        <span className="text-[10px] font-black uppercase text-slate-500 tracking-wider flex items-center gap-2">
                            <Activity size={14} className="text-blue-500" /> Activity Status
                        </span>
                        <label className="flex items-center gap-2 cursor-pointer bg-white px-3 py-1.5 rounded-lg shadow-sm border border-slate-200 hover:bg-slate-50 transition-colors">
                            <input 
                                type="checkbox" 
                                checked={!hasAtd} 
                                onChange={e => setHasAtd(!e.target.checked)} 
                                className="w-4 h-4 text-blue-500 rounded border-slate-300 focus:ring-blue-500 cursor-pointer" 
                            />
                            <span className={`text-[11px] font-black uppercase tracking-wide ${!hasAtd ? 'text-blue-600' : 'text-slate-400'}`}>
                                SET TO "IN PROGRESS"
                            </span>
                        </label>
                    </div>

                    {/* Departure ATD Fields */}
                    {hasAtd && (
                        <div className="flex flex-col gap-1 mt-2">
                            <label className="text-[10px] font-black uppercase text-on-surface/40 tracking-wider flex items-center gap-1">
                                <Clock size={12} /> End Time (ATD)
                            </label>
                            <div className="grid grid-cols-12 gap-2">
                                <div className="col-span-6">
                                    <input 
                                        type="date" 
                                        value={atdDate} 
                                        onChange={e => setAtdDate(e.target.value)}
                                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-500 outline-none focus:border-blue-500 transition-all cursor-pointer" style={{ color: '#64748b' }}
                                        required
                                    />
                                </div>
                                <div className="col-span-3">
                                    <select 
                                        value={atdHour} 
                                        onChange={e => setAtdHour(e.target.value)}
                                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-xs font-bold text-slate-500 outline-none focus:border-blue-500 transition-all cursor-pointer" style={{ color: '#64748b' }}
                                        required
                                    >
                                        {HOURS.map(h => <option key={h} value={h}>{h}</option>)}
                                    </select>
                                </div>
                                <div className="col-span-3">
                                    <select 
                                        value={atdMinute} 
                                        onChange={e => setAtdMinute(e.target.value)}
