                        );
                    })
                )}
            </div>

            {/* Logbook Entry Modal */}
            {editActivity && (
                <LogbookEntryModal
                    activity={editActivity}
                    profile={profile}
                    entryMeta={servicesMap[editActivity.id]}
                    onClose={() => setEditActivity(null)}
                    onSaved={() => {
                        fetchActivities();
                        setEditActivity(null);
                    }}
                />
            )}

            {/* Manual Activity Creator Modal */}
            {showManualModal && (
                <ManualActivityModal
                    onClose={() => setShowManualModal(false)}
                    onSaved={() => {
                        fetchActivities();
                        setShowManualModal(false);
                    }}
                />
            )}

            {chatActivity && (
                <ActivityChatModal
                    activity={chatActivity}
                    onClose={() => setChatActivity(null)}
                />
            )}
        </div>
    );
}

﻿import React, { useState } from 'react';
import { authService } from '../services/api/authService';
import { Anchor, Lock, AlertCircle, User, Eye, EyeOff } from 'lucide-react';
import MFAVerifyStep from './MFAVerifyStep';
import MFAEnrollModal from './MFAEnrollModal';

/**
 * Login V2 â€” Supporta MFA TOTP a due passaggi.
 *
 * Flusso:
 *  1. Utente inserisce email + password â†’ signInWithPassword
 *  2a. Se l'utente NON ha MFA â†’ onLogin() direttamente (Assurance Level 1)
 *  2b. Se l'utente HA MFA â†’ mostra MFAVerifyStep (richiede codice TOTP)
 *  2c. Se l'utente HA MFA ma non Ã¨ iscritto â†’ mostra MFAEnrollModal (prima volta)
 */
export default function Login({ onLogin }) {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    // step: 'credentials' | 'mfa-verify' | 'mfa-enroll'
    const [step, setStep] = useState('credentials');

    const handleLogin = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            const { data, error: authError } = await authService.signIn({ email, password });

            if (authError) {
                setError(authError.message);
                setLoading(false);
                return;
            }

            if (!data?.user) {
                setError('Login failed. Please try again.');
                setLoading(false);
                return;
            }

            // 1. Controlla se l'utente Ã¨ bloccato
            const { data: profile } = await supabase
                .from('user_profiles')
                .select('is_blocked, role')
                .eq('id', data.user.id)
                .single();

            if (profile?.is_blocked) {
                await authService.signOut();
                setError('Account sospeso. Contatta l\'amministratore.');
                setLoading(false);
                return;
            }

            // 2. Controlla se l'utente ha giÃ  fattori MFA iscritti
            const { data: factorsData } = await authService.mfa.listFactors();
            const hasTotp = factorsData?.totp?.length > 0;

            if (hasTotp) {
                // Utente con MFA attivo â†’ richiedi codice TOTP
                setStep('mfa-verify');
            } else {
                // Imponi la configurazione MFA a chi ha ruoli "amministrativi" o con molti permessi
                // TEMPORANEAMENTE DISABILITATO (Richiesto dall'utente)
                /*
                if (profile?.role === 'operation' || profile?.role === 'operation_admin' || profile?.role === 'crew_admin') {
                    setStep('mfa-enroll');
                } else {
                    // I "crew" (le navi) non sono obbligati a fare MFA, login molto piÃ¹ semplice!
                    completeLogin(data.user);
                }
                */
                completeLogin(data.user);
            }
        } catch (err) {
            setError('Connection error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    const completeLogin = (user) => {
        if (!user) return;
        onLogin({
            id: user.id,
            email: user.email,
            name: user.user_metadata?.name || user.email.split('@')[0],
            role: user.user_metadata?.role || 'admin'
        });
    };

    const handleMFAVerified = async () => {
        const { data: { user } } = await authService.getUser();
        completeLogin(user);
    };

    const handleBack = async () => {
        await authService.signOut();
        setStep('credentials');
        setError('');
    };

    // â”€â”€ Step 2b: verifica TOTP â”€â”€
    if (step === 'mfa-verify') {
        return <MFAVerifyStep onVerified={handleMFAVerified} onBack={handleBack} />;
    }

    // â”€â”€ Step 2c: iscrizione TOTP (prima volta) â”€â”€
    if (step === 'mfa-enroll') {
        return (
            <MFAEnrollModal
                canSkip={false}
                onEnrolled={async () => {
                    const { data: { user } } = await authService.getUser();
                    completeLogin(user);
                }}
            />
        );
    }

    // â”€â”€ Step 1: email + password â”€â”€
    return (
        <div className="min-h-screen flex items-center justify-center bg-surface relative overflow-hidden font-inter p-4">
            {/* Background Decorative Elements */}
            <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-primary/5 rounded-full blur-[120px]" />
            <div className="absolute bottom-[-10%] right-[-10%] w-[30%] h-[30%] bg-secondary/5 rounded-full blur-[100px]" />

            <div className="w-full max-w-[420px] bg-surface-lowest rounded-xl shadow-[0_32px_64px_-16px_rgba(0,88,190,0.12)] p-10 relative z-10 border border-surface-low/30 animate-in fade-in zoom-in duration-500">
                <div className="flex flex-col items-center text-center mb-10">
                    <div className="w-20 h-20 bg-gradient-to-br from-primary to-primary-container rounded-lg flex items-center justify-center text-white mb-6 shadow-lg shadow-primary/20 ring-4 ring-primary/5">
                        <Anchor size={40} weight="bold" />
                    </div>
                    <div className="space-y-1">
                        <h1 className="font-manrope font-extrabold text-3xl tracking-tight text-on-surface">
                            GeoKanban <span className="text-primary">V3</span>
                        </h1>
                        <p className="text-on-surface/50 font-medium text-sm tracking-wide uppercase">
                            Kinetic Fleet Management
                        </p>
                    </div>
                </div>

                <form onSubmit={handleLogin} className="space-y-6">
                    <div className="space-y-2">
                        <label className="block text-[11px] font-black text-on-surface/40 uppercase tracking-widest pl-1">
                            Identification
                        </label>
                        <div className="group relative">
                            <div className="absolute left-4 top-1/2 -translate-y-1/2 text-on-surface/30 group-focus-within:text-primary transition-colors">
                                <User size={18} />
                            </div>
                            <input
                                type="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                placeholder="fleet.manager@novamarine.com"
                                className="w-full bg-surface-low/50 hover:bg-surface-low focus:bg-white border-none focus:ring-2 focus:ring-primary/20 rounded-lg py-3.5 pl-12 pr-4 text-[15px] font-medium transition-all outline-none"
                                required
                            />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="block text-[11px] font-black text-on-surface/40 uppercase tracking-widest pl-1">
                            Security Key
                        </label>
                        <div className="group relative">
                            <div className="absolute left-4 top-1/2 -translate-y-1/2 text-on-surface/30 group-focus-within:text-primary transition-colors">
                                <Lock size={18} />
                            </div>
                            <input
                                type={showPassword ? "text" : "password"}
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                placeholder="â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢"
                                className="w-full bg-surface-low/50 hover:bg-surface-low focus:bg-white border-none focus:ring-2 focus:ring-primary/20 rounded-lg py-3.5 pl-12 pr-12 text-[15px] font-medium transition-all outline-none"
                                required
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-4 top-1/2 -translate-y-1/2 text-on-surface/30 hover:text-primary transition-colors"
                            >
                                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                            </button>
                        </div>
                    </div>

                    {error && (
                        <div className="flex items-center gap-3 p-4 bg-red-50 text-red-700 rounded-lg text-sm font-semibold border border-red-100 animate-in slide-in-from-top-2">
                            <AlertCircle size={18} className="shrink-0" /> 
                            <span>{error}</span>
                        </div>
                    )}

                    <button 
                        type="submit" 
                        className="w-full bg-gradient-to-r from-primary to-primary-container hover:brightness-110 active:scale-[0.98] text-white py-4 rounded-full font-manrope font-extrabold text-[15px] shadow-lg shadow-primary/25 transition-all disabled:opacity-50 disabled:active:scale-100"
                        disabled={loading}
                    >
                        {loading ? (
                            <div className="flex items-center justify-center gap-2">
                                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                <span>Authorizing...</span>
                            </div>
                        ) : 'Enter Command Center'}
                    </button>
                </form>

                <div className="mt-10 pt-6 border-t border-surface-low/50 text-center">
                    <p className="text-[10px] text-on-surface/30 font-bold uppercase tracking-[0.2em]">
                        Precision Engineering by Giusvelt
                    </p>
                </div>
            </div>
        </div>
    );
}

﻿import React, { useState, useEffect } from 'react';
import { authService } from '../services/api/authService';
import { ShieldCheck, Check, AlertCircle, X, Loader, Smartphone } from 'lucide-react';

/**
 * MFAEnrollModal â€” Guida l'utente attraverso l'iscrizione TOTP (prima volta).
 * Mostra il QR code da scannerizzare con Google Authenticator / Authy,
 * poi richiede il codice per confermare l'iscrizione.
 */
export default function MFAEnrollModal({ onEnrolled, onSkip, canSkip = false }) {
    const [step, setStep] = useState('loading'); // loading | qr | verify | done
    const [factorId, setFactorId] = useState(null);
    const [challengeId, setChallengeId] = useState(null);
    const [qrCode, setQrCode] = useState(null);
    const [secret, setSecret] = useState(null);
    const [code, setCode] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        startEnrollment();
    }, []);

    const startEnrollment = async () => {
        setStep('loading');
        try {
            const { data, error: enrollErr } = await authService.mfa.enroll({
                factorType: 'totp',
                issuer: 'GeoKanban',
                friendlyName: 'GeoKanban Authenticator'
            });
            if (enrollErr) throw enrollErr;

            setFactorId(data.id);
            setQrCode(data.totp.qr_code);
            setSecret(data.totp.secret);
            setStep('qr');
        } catch (err) {
            setError(err.message);
            setStep('qr');
        }
    };

    const handleProceedToVerify = async () => {
        setLoading(true);
        try {
            const { data: challenge, error: challengeErr } = await authService.mfa.challenge({ factorId });
            if (challengeErr) throw challengeErr;
            setChallengeId(challenge.id);
            setStep('verify');
        } catch (err) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    const handleVerify = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);
        try {
            const { error: verifyErr } = await authService.mfa.verify({
                factorId,
                challengeId,
                code: code.trim()
            });
            if (verifyErr) throw verifyErr;
            setStep('done');
            setTimeout(() => onEnrolled?.(), 1500);
        } catch (err) {
            setError('Invalid code. Check your Authenticator app and try again.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div style={{
            position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            zIndex: 9999, padding: '20px'
        }}>
            <div style={{
                background: '#fff', borderRadius: '16px', padding: '32px',
                width: '100%', maxWidth: '440px', boxShadow: '0 25px 60px rgba(0,0,0,0.3)'
            }}>
                {/* Header */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '24px' }}>
                    <div style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
                        <div style={{
                            width: '44px', height: '44px', borderRadius: '12px',
                            background: 'linear-gradient(135deg, #10b981, #059669)',
                            display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff'
                        }}>
                            <ShieldCheck size={22} />
                        </div>
                        <div>
                            <h2 style={{ margin: 0, fontSize: '18px', color: '#1e293b' }}>Enable 2-Factor Auth</h2>
                            <p style={{ margin: 0, fontSize: '13px', color: '#64748b' }}>Secure your GeoKanban account</p>
                        </div>
                    </div>
                    {canSkip && <button onClick={onSkip} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#94a3b8' }}><X size={20} /></button>}
                </div>

                {/* Step: Loading */}
                {step === 'loading' && (
                    <div style={{ textAlign: 'center', padding: '40px 0' }}>
                        <Loader size={32} className="spin" style={{ color: '#10b981' }} />
                        <p style={{ color: '#64748b', marginTop: '16px' }}>Preparing authenticator...</p>
                    </div>
                )}

                {/* Step: QR Code */}
                {step === 'qr' && (
                    <div>
                        <div style={{
                            background: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: '10px',
                            padding: '16px', marginBottom: '20px', display: 'flex', gap: '12px', alignItems: 'flex-start'
                        }}>
                            <Smartphone size={18} style={{ color: '#10b981', flexShrink: 0, marginTop: 2 }} />
                            <p style={{ margin: 0, fontSize: '13px', color: '#166534', lineHeight: 1.5 }}>
                                <strong>Step 1:</strong> Install <strong>Google Authenticator</strong> or <strong>Authy</strong> on your phone.<br />
                                <strong>Step 2:</strong> Scan the QR code below with the app.
                            </p>
                        </div>

                        {qrCode && (
                            <div style={{ textAlign: 'center', marginBottom: '16px' }}>
                                <img
                                    src={qrCode}
                                    alt="TOTP QR Code"
                                    style={{ width: '180px', height: '180px', border: '4px solid #e2e8f0', borderRadius: '8px' }}
                                />
                            </div>
                        )}

                        {secret && (
                            <div style={{ marginBottom: '20px' }}>
                                <p style={{ fontSize: '12px', color: '#64748b', textAlign: 'center', marginBottom: '6px' }}>
                                    Or enter this code manually:
                                </p>
                                <div style={{
                                    background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '6px',
                                    padding: '8px 12px', fontFamily: 'monospace', fontSize: '14px',
                                    textAlign: 'center', letterSpacing: '0.1em', color: '#1e293b', wordBreak: 'break-all'
                                }}>
                                    {secret}
                                </div>
                            </div>
                        )}

                        {error && <div className="login-error" style={{ marginBottom: '16px' }}><AlertCircle size={14} /> {error}</div>}

                        <button
                            onClick={handleProceedToVerify}
                            disabled={loading || !factorId}
                            style={{
                                width: '100%', padding: '12px', background: '#10b981', color: '#fff',
                                border: 'none', borderRadius: '8px', fontWeight: '700',
                                fontSize: '15px', cursor: 'pointer'
                            }}
                        >
                            {loading ? 'Loading...' : "I've scanned it â€” Continue"}
                        </button>
                    </div>
                )}

                {/* Step: Verify */}
                {step === 'verify' && (
                    <form onSubmit={handleVerify}>
                        <p style={{ color: '#475569', fontSize: '14px', marginBottom: '20px', lineHeight: 1.6 }}>
                            Enter the <strong>6-digit code</strong> now shown in your Authenticator app to confirm setup.
                        </p>
                        <div className="form-field" style={{ marginBottom: '16px' }}>
                            <label style={{ fontSize: '13px', color: '#64748b', marginBottom: '6px', display: 'block' }}>Verification Code</label>
                            <input
                                type="text"
                                inputMode="numeric"
                                pattern="[0-9]*"
                                maxLength={6}
                                value={code}
                                onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
                                placeholder="000000"
                                autoFocus
                                style={{
                                    width: '100%', padding: '12px', fontSize: '26px', letterSpacing: '0.5em',
                                    textAlign: 'center', border: '2px solid #e2e8f0', borderRadius: '8px',
                                    outline: 'none', boxSizing: 'border-box'
                                }}
                            />
                        </div>

                        {error && <div className="login-error" style={{ marginBottom: '16px' }}><AlertCircle size={14} /> {error}</div>}

                        <button
                            type="submit"
                            disabled={loading || code.length !== 6}
                            style={{
                                width: '100%', padding: '12px', background: '#10b981', color: '#fff',
                                border: 'none', borderRadius: '8px', fontWeight: '700',
                                fontSize: '15px', cursor: code.length === 6 ? 'pointer' : 'not-allowed',
                                opacity: code.length === 6 ? 1 : 0.6
                            }}
                        >
                            {loading ? 'Verifying...' : 'Activate 2FA'}
                        </button>
                    </form>
                )}

                {/* Step: Done */}
                {step === 'done' && (
                    <div style={{ textAlign: 'center', padding: '20px 0' }}>
                        <div style={{
                            width: '64px', height: '64px', borderRadius: '50%',
                            background: '#dcfce7', display: 'flex', alignItems: 'center', justifyContent: 'center',
                            margin: '0 auto 16px'
                        }}>
                            <Check size={32} style={{ color: '#10b981' }} />
                        </div>
                        <h3 style={{ color: '#1e293b', marginBottom: '8px' }}>2FA Activated!</h3>
                        <p style={{ color: '#64748b', fontSize: '14px' }}>
                            Your account is now protected.<br />You'll be redirected shortly.
                        </p>
                    </div>
                )}
            </div>
        </div>
    );
}

