    if (!form.email.trim()) {
      setError('Il campo Email Ã¨ obbligatorio.');
      return;
    }
    setSaving(true);
    setError(null);

    const { error: saveError } = await updateProfile({
        displayName: form.display_name,
        phoneNumber: form.phone,
        mmsi: form.mmsi,
        vesselId: form.vessel_id || null,
      });

    setSaving(false);
    if (saveError) {
      setError('Errore nel salvataggio. Riprova.');
    } else {
      setSaved(true);
