              <Ship size={17} className="text-primary/60" />
            </div>
            <div className="flex-1">
              <p className="text-[10px] font-black text-on-surface/30 uppercase tracking-widest mb-1">Nave Assegnata</p>
              {editing ? (
                <select
                  value={form.vessel_id}
                  onChange={e => setForm({ ...form, vessel_id: e.target.value })}
                  className="w-full bg-surface-low border-none rounded-lg px-3 py-2 text-sm font-bold text-on-surface outline-none focus:ring-2 focus:ring-primary/30"
                >
                  <option value="">Seleziona nave...</option>
                  {(vessels || []).map(v => (
                    <option key={v.id} value={v.id}>{v.name}</option>
                  ))}
                </select>
              ) : (
                <p className="text-sm font-bold text-on-surface">{myVessel?.name || 'â€”'}</p>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Cancel Button */}
      {editing && (
        <button
          onClick={() => { setEditing(false); setError(null); }}
          className="w-full py-3 rounded-xl border-2 border-surface-low text-on-surface/50 font-black text-sm uppercase tracking-widest active:bg-surface-low transition-colors"
        >
          Annulla
        </button>
      )}
    </div>
  );
}

import React from 'react';
import { 
  Anchor, Activity, Target, Database, Edit3, 
  Calendar, Rewind, Users, Menu, X, LogOut, User 
} from 'lucide-react';
import { useOperations, useConfig } from '../context/DataContext';
import { can } from '../lib/permissions';

export default function MobileDashboard({ 
  onSignOut, activeTab, setActiveTab, children, navItems = [],
  aisTotal, aisSubmitted
}) {
  const { profile } = useConfig();
  const { activities } = useOperations();
  
  const totalMsgs = (activities || []).reduce((sum, a) => sum + (a.msgCount || 0), 0);

  return (
    <div className="flex flex-col min-h-screen bg-surface font-inter">
      {/* Top App Bar */}
