    // Se Ã¨ crew forza la propria nave dopo il caricamento
    React.useEffect(() => {
        if (perms.seeOwnVesselOnly && !selectedVesselId && profile?.vesselId) {
            setSelectedVesselId(profile.vesselId);
        }
    }, [profile?.vesselId, perms.seeOwnVesselOnly, selectedVesselId]);

    // Helper to get today's date in YYYY-MM-DD format (local time)
    const getTodayStr = () => {
        const d = new Date();
        return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
    };
    const toDateStr = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;

    // Modal & Sidebar state
    const [showRangeForm, setShowRangeForm] = useState(false);
    const [rangeData, setRangeData] = useState({
        startDate: getTodayStr(),
        endDate: getTodayStr(),
        allDay: true,
        startTime: '08:00',
        endTime: '17:00',
        reasonId: '',
        notes: '',
    });
    const [selectedDate, setSelectedDate] = useState(null); // per edit giorno singolo (click su giorno)
    const [modalData, setModalData] = useState({ reasonId: '', notes: '' });
    const [saving, setSaving] = useState(false);
    
    const [sidebarTab, setSidebarTab] = useState('upcoming');
    const [inspectedDateStr, setInspectedDateStr] = useState(getTodayStr());


    // Helpers for calendar
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    // Stabile: ricalcolato solo al cambio del giorno (useMemo con deps [])
     
    const todayMs = useMemo(() => {
        const d = new Date();
        d.setHours(0, 0, 0, 0);
        return d.getTime();
    }, []);
    const today = new Date(todayMs); // oggetto Date per le funzioni che lo richiedono

    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const prevMonth = () => setCurrentDate(new Date(year, month - 1, 1));
    const nextMonth = () => setCurrentDate(new Date(year, month + 1, 1));

    // For Admin: Calculate upcoming 7 days standbys for Sidebar
    const upcomingStandbys = useMemo(() => {
        if (perms.seeOwnVesselOnly) return [];
        const next7Days = new Date(todayMs + 7 * 24 * 60 * 60 * 1000);

        return (schedules || []).filter(s => {
            if (!perms.seeAllVessels && companyVesselIds && !companyVesselIds.includes(s.vessel_id)) return false;
            const d = new Date(s.standby_date);
            return d >= today && d <= next7Days;
        }).sort((a, b) => new Date(a.standby_date) - new Date(b.standby_date));
    }, [schedules, perms, todayMs, companyVesselIds]);

    // For Admin: Calculate daily standbys across fleet for selected date
    const dailyStandbys = useMemo(() => {
        if (perms.seeOwnVesselOnly || !inspectedDateStr) return [];
        return (schedules || []).filter(s => {
            if (!perms.seeAllVessels && companyVesselIds && !companyVesselIds.includes(s.vessel_id)) return false;
            return s.standby_date === inspectedDateStr;
        }).sort((a, b) => a.vessels?.name.localeCompare(b.vessels?.name));
    }, [schedules, perms, companyVesselIds, inspectedDateStr]);

    // Fleet view: per ogni giorno del mese, tutte le navi in standby
    const fleetSchedulesByDate = useMemo(() => {
        return (schedules || []).reduce((acc, s) => {
            if (!acc[s.standby_date]) acc[s.standby_date] = [];
            acc[s.standby_date].push(s);
            return acc;
        }, {});
    }, [schedules]);

    // Calcola i giorni in cui il weather standby auto era attivo
    // Usa le vere 'Weather Stand-by' activities automatiche dalla telemetria
    const weatherStandbyDates = useMemo(() => {
        const dates = new Set();
        
        // 1. Estrai le vere attivitÃ  automatiche (isFleetEvent)
        if (activities && activities.length > 0) {
            const fleetWeatherActivities = activities.filter(a => a.isFleetEvent && a.activity === 'Weather Stand-by');
            fleetWeatherActivities.forEach(a => {
                const start = new Date(a.startTime);
                const end = a.endTime ? new Date(a.endTime) : new Date(); // If still active, show up to today
                
                const curr = new Date(start);
                curr.setHours(0, 0, 0, 0);
                const endDay = new Date(end);
                endDay.setHours(0, 0, 0, 0);
                
                while (curr <= endDay) {
                    const dStr = `${curr.getFullYear()}-${String(curr.getMonth()+1).padStart(2,'0')}-${String(curr.getDate()).padStart(2,'0')}`;
                    dates.add(dStr);
                    curr.setDate(curr.getDate() + 1);
                }
            });
        }

        // 2. Legacy fallback
        // Un giorno Ã¨ "weather fleet" se TUTTE le navi visibili hanno standby WEATHER
        // Oppure se c'Ã¨ almeno 1 vessel_standby_schedule con reason WEATHER per 3+ navi
        const byDate = fleetSchedulesByDate;
        Object.entries(byDate).forEach(([date, sArr]) => {
            const weatherCount = sArr.filter(s => s.standby_reasons?.code === 'WEATHER' || s.standby_reasons?.code === 'SUD_WTHR').length;
            if (weatherCount >= Math.max(2, visibleVessels.length * 0.5)) dates.add(date);
        });
        return dates;
    }, [activities, fleetSchedulesByDate, visibleVessels.length]);

    // Pending approvals count
    const pendingSchedules = useMemo(() => {
        if (perms.seeOwnVesselOnly) return [];
        return (schedules || []).filter(s => s.is_approved === false || s.is_approved === null);
    }, [schedules, perms.seeOwnVesselOnly]);

    // Current vessel schedules (per singola nave selezionata)
    const vesselSchedules = useMemo(() => {
        if (!selectedVesselId) return {};
        return (schedules || []).filter(s => s.vessel_id === selectedVesselId).reduce((acc, s) => {
            acc[s.standby_date] = s;
            return acc;
        }, {});
    }, [schedules, selectedVesselId]);

    const handleDayClick = (day) => {
        const dateClicked = new Date(year, month, day);
        const dateStr = toDateStr(dateClicked);
        setInspectedDateStr(dateStr);
        setSidebarTab('daily');
        // Edit singolo giorno solo se una nave Ã¨ selezionata
        if (perms.editSchedule && selectedVesselId) {
            setSelectedDate(dateClicked);
            const existing = vesselSchedules[dateStr];
            setModalData({
                reasonId: existing?.standby_reason_id || '',
                notes: existing?.notes || ''
            });
        }
    };

    // Salva standby singolo giorno (legacy click su giorno)
    const handleSaveStandby = async () => {
        if (!selectedDate || !modalData.reasonId || !selectedVesselId) return;
        setSaving(true);
        try {
            const dateStr = toDateStr(selectedDate);
            const existing = vesselSchedules[dateStr];
            if (existing) {
                await scheduleService.updateSchedule(existing.id, { standbyReasonId: modalData.reasonId, notes: modalData.notes });
            } else {
                await scheduleService.insertSchedule({
                    vesselId: selectedVesselId,
                    standbyDate: dateStr,
                    standbyReasonId: modalData.reasonId,
                    notes: modalData.notes,
                    createdBy: profile.id
                });
            }
            await fetchSchedules();
            setSelectedDate(null);
        } catch (error) {
            
            alert(`Error: ${error.message}`);
        } finally {
            setSaving(false);
        }
    };

    // Salva standby da form range
    const handleSaveRange = async () => {
        if (!rangeData.reasonId || !selectedVesselId) return;
        setSaving(true);
        try {
            await scheduleService.insertScheduleRange({
                vesselId: selectedVesselId,
                startDate: rangeData.startDate,
                endDate: rangeData.endDate,
                standbyReasonId: rangeData.reasonId,
                notes: rangeData.notes,
                createdBy: profile.id,
                allDay: rangeData.allDay,
                startTime: rangeData.startTime ? rangeData.startTime + ':00' : null,
                endTime: rangeData.endTime ? rangeData.endTime + ':00' : null,
            });
            await fetchSchedules();
            setShowRangeForm(false);
            setRangeData({ startDate: getTodayStr(), endDate: getTodayStr(), allDay: true, startTime: '08:00', endTime: '17:00', reasonId: '', notes: '' });
        } catch (error) {
            
            alert(`Error: ${error.message}`);
        } finally {
            setSaving(false);
        }
    };

    const handleDeleteStandby = async () => {
        if (!selectedDate) return;
        setSaving(true);
        try {
            const dateStr = toDateStr(selectedDate);
            const existing = vesselSchedules[dateStr];
            if (existing) {
                await scheduleService.deleteSchedule(existing.id);
                await fetchSchedules();
            }
            setSelectedDate(null);
        } catch (error) {
            
            alert(`Error: ${error.message}`);
        } finally {
            setSaving(false);
        }
    };

    // Render giorni del calendario
    const renderCalendarDays = () => {
        const blks = [];
        const isFleetView = !selectedVesselId;
        for (let _i = 0; i < firstDay; i++) {
            blks.push(<div key={`empty-${i}`} className="cal-day empty"></div>);
        }
        for (let d = 1; d <= daysInMonth; d++) {
            const date = new Date(year, month, d);
            const dateStr = toDateStr(date);
            const isToday = date.getTime() === today.getTime();
            const isPast = date < today;
            const isWeatherDay = weatherStandbyDates.has(dateStr);

            const isSelected = dateStr === inspectedDateStr;

            if (isFleetView) {
                // Fleet view: mostra tutti i pallini delle navi
                const daySchedules = fleetSchedulesByDate[dateStr] || [];
                blks.push(
                    <div
                        key={d}
                        className={`cal-day ${isSelected ? 'selected' : ''} ${isToday ? 'today' : ''} ${isPast ? 'past' : ''} clickable`}
                        onClick={() => { setInspectedDateStr(dateStr); setSidebarTab('daily'); }}
                        style={{
                            position: 'relative',
                            minHeight: 64,
                            border: isSelected 
                                ? '2.5px solid #2563eb' 
                                : (isToday ? '1.5px dashed #3b82f6' : '1px solid #e2e8f0'),
                            backgroundColor: isSelected 
                                ? '#f8fafc' 
                                : (isToday ? '#eff6ff' : '#ffffff'),
                            boxShadow: isSelected ? '0 4px 6px -1px rgba(0, 0, 0, 0.05), inset 0 2px 4px 0 rgba(0, 0, 0, 0.02)' : 'none',
                            transition: 'all 0.15s'
                        }}
                    >
                        {/* Barra grigia weather fleet standby */}
                        {isWeatherDay && (
                            <div style={{
                                position: 'absolute', top: 0, left: 0, right: 0,
                                height: '4px', background: '#94a3b8', borderRadius: '2px 2px 0 0',
                                zIndex: 1
                            }} title="Weather Stand-by (All Vessels)" />
                        )}
                        <span className="day-num font-black text-[10px]">{d}</span>
                        {/* Pallini colorati per ogni nave */}
                        {daySchedules.length > 0 && (
                            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '2px', marginTop: '4px' }}>
                                {daySchedules.map(s => (
                                    <div
                                        key={s.id}
                                        title={s.vessels?.name + ' â€” ' + (s.standby_reasons?.code || '')}
                                        style={{
                                            width: 14, height: 14,
                                            borderRadius: '50%',
                                            background: vesselColorMap[s.vessel_id] || '#94a3b8',
                                            flexShrink: 0
                                        }}
                                    />
                                ))}
                            </div>
                        )}
                    </div>
                );
            } else {
                // Single-vessel view: comportamento precedente
                const data = vesselSchedules[dateStr];
                blks.push(
                    <div
                        key={d}
                        className={`cal-day ${isSelected ? 'selected' : ''} ${isToday ? 'today' : ''} ${isPast ? 'past' : ''} ${data ? 'has-event' : ''} ${perms.editSchedule ? 'clickable group relative' : ''}`}
                        onClick={() => handleDayClick(d)}
                        style={{
                            position: 'relative',
                            minHeight: 64,
                            border: isSelected 
                                ? '2.5px solid #2563eb' 
                                : (isToday ? '1.5px dashed #3b82f6' : '1px solid #e2e8f0'),
                            backgroundColor: isSelected 
                                ? '#f8fafc' 
                                : (isToday ? '#eff6ff' : '#ffffff'),
                            boxShadow: isSelected ? '0 4px 6px -1px rgba(0, 0, 0, 0.05), inset 0 2px 4px 0 rgba(0, 0, 0, 0.02)' : 'none',
                            transition: 'all 0.15s'
                        }}
                    >
                        {/* Barra grigia weather fleet (anche in singola nave) */}
                        {isWeatherDay && (
                            <div style={{
                                position: 'absolute', top: 0, left: 0, right: 0,
                                height: '4px', background: '#94a3b8', borderRadius: '2px 2px 0 0'
                            }} title="Weather Stand-by (All Vessels)" />
                        )}
                        <div className="flex justify-between items-start w-full">
                            <span className="day-num font-black text-[10px]">{d}</span>
                            {perms.editSchedule && (
                                <div className="w-6 h-6 flex items-center justify-center text-slate-300 bg-white rounded-md border border-slate-100 shadow-sm hover:text-primary hover:border-primary/30 active:scale-95 transition-all cursor-pointer z-10 opacity-0 group-hover:opacity-100">
                                    <Plus size={14} strokeWidth={2.5} />
                                </div>
                            )}
                        </div>
                        {data && (
                            <div
                                className="day-event tooltip-trigger"
                                style={{ marginTop: 'auto', width: '100%', cursor: 'pointer' }}
                                onClick={(e) => { e.stopPropagation(); setInspectedDateStr(dateStr); setSidebarTab('daily'); }}
                            >
                                <div className="event-pill" style={{ background: vesselColorMap[data.vessel_id] || '#f59e0b', color: 'white', fontSize: '10px', padding: '2px 4px', borderRadius: '4px', textAlign: 'center', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    {data.standby_reasons?.code || 'Standby'}
                                </div>
                            </div>
                        )}
                    </div>
                );
            }
        }
        return blks;
    };

    return (
        <div className="pt-tab-container">
            <SectionHeader 
                title="Schedule & Stand-by" 
                subtitle="Fleet availability and planned maintenance windows" 
                icon={Calendar}
                actions={
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                        {/* Selettore nave */}
                        <select
                            value={selectedVesselId || ''}
                            onChange={(e) => setSelectedVesselId(e.target.value || null)}
                            className="bg-white/50 backdrop-blur-md border border-white/20 rounded-full px-4 py-2 text-[10px] font-black uppercase tracking-widest text-on-surface outline-none focus:ring-2 ring-primary/20"
                        >
                            {!perms.seeOwnVesselOnly && <option value="">ðŸŒ All Vessels</option>}
                            {visibleVessels.map(v => (
                                <option key={v.id} value={v.id}>{v.name}</option>
                            ))}
                        </select>
                        {/* Bottone Aggiungi Standby (solo se nave selezionata e permesso) */}
                        {perms.editSchedule && selectedVesselId && (
                            <button
                                onClick={() => setShowRangeForm(true)}
                                className="flex items-center gap-1 bg-amber-500 hover:bg-amber-600 text-white text-[10px] font-black uppercase tracking-widest rounded-full px-4 py-2 transition-colors"
                            >
                                <Plus size={12} /> Aggiungi Standby
                            </button>
                        )}
                    </div>
                }
            />

            <div style={{ display: 'flex', gap: '16px', marginTop: '16px' }}>
                {/* Calendario */}
                <div style={{ flex: 1, background: '#fff', borderRadius: '12px', border: '1px solid #e2e8f0', display: 'flex', flexDirection: 'column' }}>
                    <div style={{ padding: '16px', flex: 1 }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
                            <button onClick={prevMonth} className="btn-icon w-8 h-8 flex items-center justify-center rounded-full hover:bg-surface-low transition-colors"><ChevronLeft size={16} /></button>
                            <h3 style={{ margin: 0, fontSize: '14px', fontWeight: '900', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                                {currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })}
                            </h3>
                            <button onClick={nextMonth} className="btn-icon w-8 h-8 flex items-center justify-center rounded-full hover:bg-surface-low transition-colors"><ChevronRight size={16} /></button>
                        </div>

                        <div className="cal-grid">
                            {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
                                <div key={day} className="cal-header-day text-[10px] uppercase font-black opacity-30 tracking-widest">{day}</div>
                            ))}
                            {renderCalendarDays()}
                        </div>
                    </div>
                </div>

                {/* Sidebar for Operations/Crew Admin */}
                {!perms.seeOwnVesselOnly && (
                    <div style={{ width: '420px', display: 'flex', flexDirection: 'column', gap: '16px', flexShrink: 0 }}>
                        {/* Box Legenda Colori Navi */}
                        {visibleVessels.length > 0 && (
                            <div style={{ background: '#fff', borderRadius: '12px', border: '1px solid #e2e8f0', padding: '16px' }}>
                                <div style={{ fontSize: '10px', fontWeight: '900', color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: '12px' }}>Legenda Navi</div>
                                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '10px' }}>
                                    {visibleVessels.map(v => (
                                        <div key={v.id} style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                            <div style={{ width: 12, height: 12, borderRadius: '50%', background: vesselColorMap[v.id], flexShrink: 0 }} />
                                            <span style={{ fontSize: '11px', fontWeight: '700', color: '#475569' }}>{v.name}</span>
                                        </div>
                                    ))}
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', gridColumn: 'span 2', marginTop: '4px', paddingTop: '8px', borderTop: '1px solid #f1f5f9' }}>
                                        <div style={{ width: 24, height: 4, borderRadius: 2, background: '#94a3b8', flexShrink: 0 }} />
                                        <span style={{ fontSize: '11px', fontWeight: '700', color: '#94a3b8' }}>Weather Stand-by Flotta (Cantiere)</span>
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* Contenitore Tabs originali */}
                        <div style={{ background: '#fff', borderRadius: '12px', border: '1px solid #e2e8f0', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
                            {/* Tab Headers */}
                            <div style={{ display: 'flex', borderBottom: '1px solid #e2e8f0', background: '#f8fafc' }}>
                                <div 
                                    onClick={() => setSidebarTab('upcoming')}
                                    style={{ flex: 1, padding: '12px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px', borderBottom: sidebarTab === 'upcoming' ? '2px solid #f59e0b' : '2px solid transparent', background: sidebarTab === 'upcoming' ? '#fff' : 'transparent', transition: 'all 0.2s' }}
                                >
                                    <Clock size={14} color={sidebarTab === 'upcoming' ? '#f59e0b' : '#94a3b8'} />
                                    <span style={{ fontSize: '10px', fontWeight: '900', textTransform: 'uppercase', color: sidebarTab === 'upcoming' ? '#0f172a' : '#94a3b8' }}>Upcoming</span>
                                </div>
                                <div 
                                    onClick={() => setSidebarTab('daily')}
                                    style={{ flex: 1, padding: '12px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px', borderBottom: sidebarTab === 'daily' ? '2px solid #3b82f6' : '2px solid transparent', background: sidebarTab === 'daily' ? '#fff' : 'transparent', transition: 'all 0.2s' }}
                                >
                                    <Calendar size={14} color={sidebarTab === 'daily' ? '#3b82f6' : '#94a3b8'} />
                                    <span style={{ fontSize: '10px', fontWeight: '900', textTransform: 'uppercase', color: sidebarTab === 'daily' ? '#0f172a' : '#94a3b8' }}>Daily Details</span>
                                </div>
                                <div 
                                    onClick={() => setSidebarTab('approvals')}
                                    style={{ flex: 1, padding: '12px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px', borderBottom: sidebarTab === 'approvals' ? '2px solid #ef4444' : '2px solid transparent', background: sidebarTab === 'approvals' ? '#fff' : 'transparent', transition: 'all 0.2s', position: 'relative' }}
                                >
                                    <AlertCircle size={14} color={sidebarTab === 'approvals' ? '#ef4444' : '#94a3b8'} />
                                    <span style={{ fontSize: '10px', fontWeight: '900', textTransform: 'uppercase', color: sidebarTab === 'approvals' ? '#0f172a' : '#94a3b8' }}>Approvals</span>
                                    {pendingSchedules.length > 0 && (
                                        <div style={{ position: 'absolute', top: '4px', right: '4px', width: '12px', height: '12px', background: '#ef4444', borderRadius: '50%', border: '2px solid white', display: 'flex', alignItems: 'center', justifyContent: 'center' }} className="animate-pulse">
                                            <div style={{ width: '4px', height: '4px', background: 'white', borderRadius: '50%' }} />
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Content */}
                            <div style={{ padding: '12px', flex: 1, overflowY: 'auto', maxHeight: '400px' }}>
                                {sidebarTab === 'upcoming' && (
                                    <>
                                        {upcomingStandbys.length === 0 ? (
                                            <div style={{ textAlign: 'center', color: '#94a3b8', fontSize: '11px', marginTop: '20px', fontStyle: 'italic' }}>
                                                No stand-bys scheduled.
                                            </div>
                                        ) : (
                                            upcomingStandbys.map(s => {
                                                const d = new Date(s.standby_date).toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric' });
                                                return (
                                                    <div key={s.id} onClick={() => { setInspectedDateStr(s.standby_date); setSidebarTab('daily'); }} style={{ marginBottom: '8px', padding: '8px', background: '#fef3c7', borderRadius: '8px', border: '1px solid #fde68a', cursor: 'pointer', transition: 'transform 0.1s' }} className="hover:scale-[1.02]">
                                                        <div style={{ fontSize: '9px', fontWeight: '900', color: '#b45309', marginBottom: '2px', textTransform: 'uppercase' }}>
                                                            {d}
                                                        </div>
                                                        <div style={{ fontSize: '12px', fontWeight: '900', color: '#0f172a' }}>
                                                            {s.vessels?.name}
                                                        </div>
                                                        <div style={{ fontSize: '10px', color: '#475569', marginTop: '1px', fontWeight: '700' }}>
                                                            {s.standby_reasons?.code}
                                                        </div>
                                                    </div>
                                                )
                                            })
                                        )}
                                    </>
                                )}
                                
                                {sidebarTab === 'daily' && (
                                    <>
                                        {!inspectedDateStr ? (
                                            <div style={{ textAlign: 'center', color: '#94a3b8', fontSize: '11px', marginTop: '40px', padding: '0 20px', fontStyle: 'italic', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                                                <Calendar size={24} color="#cbd5e1" />
                                                Click an event on the calendar to view fleet details for that day.
                                            </div>
                                        ) : (
                                            <>
                                                <div style={{ marginBottom: '12px', paddingBottom: '8px', borderBottom: '1px solid #e2e8f0' }}>
                                                    <div style={{ fontSize: '10px', fontWeight: '900', color: '#3b82f6', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                                                        {new Date(inspectedDateStr).toLocaleDateString([], { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
                                                    </div>
                                                    <div style={{ fontSize: '11px', color: '#64748b', marginTop: '2px' }}>
                                                        {dailyStandbys.length} vessel{dailyStandbys.length !== 1 && 's'} in Stand-by
                                                    </div>
                                                </div>
                                                
                                                {dailyStandbys.length === 0 ? (
                                                    <div style={{ textAlign: 'center', color: '#94a3b8', fontSize: '11px', marginTop: '20px', fontStyle: 'italic' }}>
                                                        No stand-bys found for this day.
                                                    </div>
                                                ) : (
                                                    dailyStandbys.map(s => (
                                                        <div key={s.id} style={{ marginBottom: '8px', padding: '10px', background: '#eff6ff', borderRadius: '8px', border: '1px solid #bfdbfe' }}>
                                                            <div style={{ fontSize: '12px', fontWeight: '900', color: '#1e3a8a', marginBottom: '4px' }}>
                                                                {s.vessels?.name}
                                                            </div>
                                                            <div style={{ display: 'inline-block', background: '#3b82f6', color: 'white', padding: '2px 6px', borderRadius: '4px', fontSize: '10px', fontWeight: 'bold', marginBottom: '6px' }}>
                                                                {s.standby_reasons?.code}
                                                            </div>
                                                            <div style={{ fontSize: '11px', color: '#334155' }}>
                                                                <strong>{s.standby_reasons?.name}</strong>
                                                                {s.notes && <p style={{ margin: '4px 0 0 0', paddingLeft: '8px', borderLeft: '2px solid #93c5fd' }}>{s.notes}</p>}
                                                            </div>
                                                        </div>
                                                    ))
                                                )}
                                            </>
                                        )}
                                    </>
                                )}

                                {sidebarTab === 'approvals' && (
                                    <>
                                        {pendingSchedules.length === 0 ? (
                                            <div style={{ textAlign: 'center', color: '#94a3b8', fontSize: '11px', marginTop: '40px', padding: '0 20px', fontStyle: 'italic', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                                                <AlertCircle size={24} color="#cbd5e1" />
                                                No pending standby requests.
                                            </div>
                                        ) : (
                                            <>
                                                <div style={{ marginBottom: '12px', paddingBottom: '8px', borderBottom: '1px solid #e2e8f0' }}>
                                                    <div style={{ fontSize: '10px', fontWeight: '900', color: '#ef4444', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                                                        Pending Approval
                                                    </div>
                                                    <div style={{ fontSize: '11px', color: '#64748b', marginTop: '2px' }}>
                                                        {pendingSchedules.length} request{pendingSchedules.length !== 1 && 's'} waiting
                                                    </div>
                                                </div>
                                                
                                                {pendingSchedules.map(s => (
                                                    <div key={s.id} style={{ marginBottom: '12px', padding: '12px', background: '#fff1f2', borderRadius: '12px', border: '1px solid #fecdd3' }}>
                                                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '6px' }}>
                                                            <span style={{ fontSize: '9px', fontWeight: '900', color: '#e11d48', textTransform: 'uppercase' }}>
                                                                {new Date(s.standby_date).toLocaleDateString([], { month: 'short', day: 'numeric' })}
                                                            </span>
                                                            <span style={{ fontSize: '9px', fontWeight: '900', color: '#94a3b8' }}>
                                                                {new Date(s.created_at).toLocaleDateString()}
                                                            </span>
                                                        </div>
                                                        <div style={{ fontSize: '13px', fontWeight: '900', color: '#1e293b', marginBottom: '4px' }}>
                                                            {s.vessels?.name}
                                                        </div>
                                                        <div style={{ display: 'inline-block', background: '#e11d48', color: 'white', padding: '2px 6px', borderRadius: '4px', fontSize: '10px', fontWeight: 'bold', marginBottom: '8px' }}>
                                                            {s.standby_reasons?.code}
                                                        </div>
                                                        {s.notes && (
                                                            <div style={{ fontSize: '11px', color: '#475569', marginBottom: '12px', padding: '8px', background: 'white', borderRadius: '6px', border: '1px solid #fecdd3' }}>
                                                                {s.notes}
                                                            </div>
                                                        )}
                                                        {perms.editSchedule && (
                                                            <div style={{ display: 'flex', gap: '8px' }}>
                                                                <button 
                                                                    onClick={() => approveSchedule(s.id, profile.id)}
                                                                    className="flex-1 py-2 bg-green-500 hover:bg-green-600 text-white text-[10px] font-black uppercase rounded-lg transition-colors"
                                                                >
                                                                    Approve
                                                                </button>
                                                                <button 
                                                                    onClick={() => rejectSchedule(s.id)}
                                                                    className="flex-1 py-2 bg-white border border-red-200 text-red-500 hover:bg-red-50 text-[10px] font-black uppercase rounded-lg transition-colors"
                                                                >
                                                                    Reject
                                                                </button>
                                                            </div>
                                                        )}
                                                    </div>
                                                ))}
                                            </>
                                        )}
                                    </>
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* Modal for Crew to Edit/Add */}
            {selectedDate && (
                <div className="lem-overlay">
                    <div className="lem-modal" style={{ maxWidth: '400px' }}>
                        <div className="lem-header">
                            <div>
                                <h2>Stand-by Declaration</h2>
                                <p style={{ fontSize: '12px', color: '#64748b' }}>
                                    Date: {selectedDate.toLocaleDateString([], { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
                                </p>
                            </div>
                            <button className="lem-close" onClick={() => setSelectedDate(null)}><X size={18} /></button>
                        </div>
                        <div className="lem-body" style={{ padding: '20px' }}>
                            <div style={{ marginBottom: '16px' }}>
                                <label style={{ display: 'block', fontSize: '12px', fontWeight: 'bold', marginBottom: '6px' }}>Stand-by Reason</label>
                                <select
                                    className="edit-select"
                                    style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #cbd5e1' }}
                                    value={modalData.reasonId}
                                    onChange={e => setModalData({ ...modalData, reasonId: e.target.value })}
                                >
                                    <option value="">-- Select Reason --</option>
                                    {standbyReasons.map(r => (
                                        <option key={r.id} value={r.id}>{r.name} ({r.code})</option>
                                    ))}
                                </select>
                            </div>
                            <div style={{ marginBottom: '16px' }}>
                                <label style={{ display: 'block', fontSize: '12px', fontWeight: 'bold', marginBottom: '6px' }}>Notes (Optional)</label>
                                <textarea
                                    className="lem-narrative"
                                    style={{ width: '100%', minHeight: '80px', padding: '8px' }}
                                    placeholder="Enter additional details..."
                                    value={modalData.notes}
                                    onChange={e => setModalData({ ...modalData, notes: e.target.value })}
                                />
                            </div>
                        </div>
                        <div className="lem-footer" style={{ display: 'flex', justifyContent: 'space-between', padding: '16px 20px', borderTop: '1px solid #e2e8f0' }}>
                            {vesselSchedules[`${selectedDate.getFullYear()}-${String(selectedDate.getMonth() + 1).padStart(2, '0')}-${String(selectedDate.getDate()).padStart(2, '0')}`] ? (
                                <button
                                    className="lem-btn-cancel"
                                    onClick={handleDeleteStandby}
                                    disabled={saving}
                                    style={{ color: '#ef4444', borderColor: '#ef4444' }}
                                >
                                    Remove
                                </button>
                            ) : (
                                <div />
                            )}
                            <div style={{ display: 'flex', gap: '8px' }}>
                                <button className="lem-btn-cancel" onClick={() => setSelectedDate(null)} disabled={saving}>Cancel</button>
                                <button className="lem-btn-submit" onClick={handleSaveStandby} disabled={saving || !modalData.reasonId}>
                                    {saving ? 'Saving...' : 'Save'}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal for Range Stand-by */}
            {showRangeForm && (
                <div className="lem-overlay">
                    <div className="lem-modal" style={{ maxWidth: '450px' }}>
                        <div className="lem-header">
                            <div>
                                <h2>Aggiungi Stand-by Multi-giorno</h2>
                                <p style={{ fontSize: '12px', color: '#64748b' }}>
                                    Imposta un periodo di standby per la nave selezionata
                                </p>
                            </div>
                            <button className="lem-close" onClick={() => setShowRangeForm(false)}><X size={18} /></button>
                        </div>
                        <div className="lem-body" style={{ padding: '20px' }}>
                            <div style={{ marginBottom: '16px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                                <input
                                    type="checkbox"
                                    id="allDayCheckbox"
                                    checked={rangeData.allDay}
                                    onChange={e => setRangeData({ ...rangeData, allDay: e.target.checked })}
                                    style={{ width: '16px', height: '16px', cursor: 'pointer' }}
                                />
                                <label htmlFor="allDayCheckbox" style={{ fontSize: '12px', fontWeight: 'bold', cursor: 'pointer' }}>
                                    Giornata intera (All Day)
                                </label>
                            </div>

                            <div style={{ display: 'flex', gap: '12px', marginBottom: '16px' }}>
                                <div style={{ flex: 1 }}>
                                    <label style={{ display: 'block', fontSize: '11px', fontWeight: 'bold', marginBottom: '6px', textTransform: 'uppercase', color: '#64748b' }}>Data Inizio</label>
                                    <input
                                        type="date"
                                        style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #cbd5e1' }}
                                        value={rangeData.startDate}
                                        onChange={e => setRangeData({ ...rangeData, startDate: e.target.value })}
                                    />
                                </div>
                                <div style={{ flex: 1 }}>
                                    <label style={{ display: 'block', fontSize: '11px', fontWeight: 'bold', marginBottom: '6px', textTransform: 'uppercase', color: '#64748b' }}>Data Fine</label>
                                    <input
                                        type="date"
                                        style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #cbd5e1' }}
                                        value={rangeData.endDate}
                                        onChange={e => setRangeData({ ...rangeData, endDate: e.target.value })}
                                    />
                                </div>
                            </div>

                            {!rangeData.allDay && (
                                <div style={{ display: 'flex', gap: '12px', marginBottom: '16px' }}>
                                    <div style={{ flex: 1 }}>
                                        <label style={{ display: 'block', fontSize: '11px', fontWeight: 'bold', marginBottom: '6px', textTransform: 'uppercase', color: '#64748b' }}>Ora Inizio</label>
                                        <input
                                            type="time"
                                            style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #cbd5e1' }}
                                            value={rangeData.startTime}
                                            onChange={e => setRangeData({ ...rangeData, startTime: e.target.value })}
                                        />
                                    </div>
                                    <div style={{ flex: 1 }}>
                                        <label style={{ display: 'block', fontSize: '11px', fontWeight: 'bold', marginBottom: '6px', textTransform: 'uppercase', color: '#64748b' }}>Ora Fine</label>
                                        <input
                                            type="time"
                                            style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #cbd5e1' }}
                                            value={rangeData.endTime}
                                            onChange={e => setRangeData({ ...rangeData, endTime: e.target.value })}
                                        />
                                    </div>
                                </div>
                            )}

                            <div style={{ marginBottom: '16px' }}>
                                <label style={{ display: 'block', fontSize: '12px', fontWeight: 'bold', marginBottom: '6px' }}>Motivazione Stand-by</label>
                                <select
                                    style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #cbd5e1' }}
                                    value={rangeData.reasonId}
                                    onChange={e => setRangeData({ ...rangeData, reasonId: e.target.value })}
                                >
                                    <option value="">-- Seleziona Motivazione --</option>
                                    {standbyReasons.map(r => (
                                        <option key={r.id} value={r.id}>{r.name} ({r.code})</option>
                                    ))}
                                </select>
                            </div>

                            <div style={{ marginBottom: '16px' }}>
                                <label style={{ display: 'block', fontSize: '12px', fontWeight: 'bold', marginBottom: '6px' }}>Note (Opzionale)</label>
                                <textarea
                                    className="lem-narrative"
                                    style={{ width: '100%', minHeight: '80px', padding: '8px' }}
                                    placeholder="Inserisci dettagli aggiuntivi..."
                                    value={rangeData.notes}
                                    onChange={e => setRangeData({ ...rangeData, notes: e.target.value })}
                                />
                            </div>
                        </div>
                        <div className="lem-footer" style={{ display: 'flex', justifyContent: 'flex-end', gap: '8px', padding: '16px 20px', borderTop: '1px solid #e2e8f0' }}>
                            <button className="lem-btn-cancel" onClick={() => setShowRangeForm(false)} disabled={saving}>Annulla</button>
                            <button className="lem-btn-submit" onClick={handleSaveRange} disabled={saving || !rangeData.reasonId}>
                                {saving ? 'Salvataggio...' : 'Salva'}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { AlertTriangle, CheckCircle, Clock, X, ShieldAlert, ShieldCheck } from 'lucide-react';
import { useFleet, useConfig } from '../context/DataContext';

export default function TelemetryStatusIndicator() {
    const { vesselPositions, crewVesselId, companyVesselIds, vessels } = useFleet();
    const { profile } = useConfig();
    const [isOpen, setIsOpen] = useState(false);

    // 1. Filter positions according to tenant role permissions (SOLID)
    const activeGaps = useMemo(() => {
        if (!vesselPositions || !profile || !vessels) return [];
        
        // Mappa delle navi attive per filtering
        const activeVesselIds = new Set(vessels.filter(v => v.tracking_active).map(v => v.id));

        let scopedPositions = vesselPositions.filter(p => activeVesselIds.has(p.vesselId));
        
        if (profile.role === 'crew' && crewVesselId) {
            scopedPositions = scopedPositions.filter(p => p.vesselId === crewVesselId);
        } else if (profile.role === 'crew_admin' && companyVesselIds) {
            scopedPositions = scopedPositions.filter(p => companyVesselIds.includes(p.vesselId));
        }

        const now = new Date();
        const gaps = [];

        scopedPositions.forEach(pos => {
            if (!pos.lastUpdate) {
                gaps.push({
                    vessel: pos.vessel,
                    vesselId: pos.vesselId,
                    hours: null,
                    lastSeen: 'never'
                });
                return;
            }

            const diffMs = now - new Date(pos.lastUpdate);
            const diffHours = diffMs / (1000 * 60 * 60);

            if (diffHours >= 24) {
                gaps.push({
                    vessel: pos.vessel,
                    vesselId: pos.vesselId,
                    hours: Math.round(diffHours),
                    lastSeen: new Date(pos.lastUpdate).toLocaleString('en-GB')
                });
            }
        });

        return gaps;
    }, [vesselPositions, profile, crewVesselId, companyVesselIds, vessels]);

    const isHealthy = activeGaps.length === 0;

    return (
        <div className="relative">
            {/* LED Status Button */}
            <button 
                onClick={() => setIsOpen(!isOpen)}
                title={isHealthy ? "Telemetry Status: Operational" : `Telemetry Alert: ${activeGaps.length} Vessels Incommunicado`}
                className={`w-10 h-10 rounded-full bg-white border flex items-center justify-center shadow-sm active:scale-95 transition-all relative cursor-pointer ${
                    isOpen ? 'border-primary/30 ring-2 ring-primary/10' : 'border-slate-100 hover:bg-slate-50 hover:shadow'
                }`}
            >
                {/* Glowing animation rings based on status */}
                <div className="w-3 h-3 rounded-full relative flex items-center justify-center">
                    {!isHealthy && (
                        <span className="absolute inline-flex h-full w-full rounded-full bg-rose-500 animate-ping opacity-75" />
                    )}
                    <span className={`relative inline-flex rounded-full h-2.5 w-2.5 ${
                        isHealthy ? 'bg-emerald-500' : 'bg-rose-500'
                    }`} />
                </div>
            </button>

            {/* Dropdown Popover Panel */}
            <AnimatePresence>
                {isOpen && (
                    <>
                        {/* Invisible overlay to capture click outside and close, without blocking screen/header */}
                        <div 
                            className="fixed inset-0 z-[998]" 
                            onClick={() => setIsOpen(false)}
                        />

                        {/* Floating Popover Container */}
                        <motion.div 
                            initial={{ opacity: 0, y: 15, scale: 0.95 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            exit={{ opacity: 0, y: 15, scale: 0.95 }}
                            transition={{ duration: 0.15, ease: 'easeOut' }}
                            className="absolute right-0 top-12 z-[999] w-[380px] sm:w-[420px] bg-white rounded-3xl border border-slate-100 shadow-2xl overflow-hidden flex flex-col font-manrope origin-top-right"
                        >
                            {/* Small Arrow indicator on top of the popover */}
                            <div className="absolute right-4 -top-1.5 w-3 h-3 bg-white rotate-45 border-t border-l border-slate-100" />

                            {/* Header */}
                            <div className={`p-4 text-white flex items-center justify-between relative z-10 ${
                                isHealthy 
                                    ? 'bg-gradient-to-r from-emerald-600 to-teal-600' 
                                    : 'bg-gradient-to-r from-rose-600 to-orange-600'
                            }`}>
                                <div className="flex items-center gap-2.5">
                                    {isHealthy ? (
                                        <ShieldCheck size={20} className="text-white/90" />
                                    ) : (
                                        <ShieldAlert size={20} className="text-white/90 animate-pulse" />
                                    )}
                                    <div>
                                        <h3 className="font-extrabold text-xs tracking-tight text-white leading-none mb-0.5">
                                            Telemetry Status
                                        </h3>
                                        <p className="text-[8px] text-white/70 font-black uppercase tracking-widest leading-none">
                                            {isHealthy ? 'All Systems Online' : 'Telemetry Blackout Detected'}
                                        </p>
                                    </div>
                                </div>
                                <button 
                                    onClick={() => setIsOpen(false)}
                                    className="p-1 rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors cursor-pointer"
                                >
                                    <X size={12} />
                                </button>
                            </div>

                            {/* Body (Scrollable if there are many vessels) */}
                            <div className="p-4 overflow-y-auto max-h-[350px] flex flex-col gap-3">
                                {isHealthy ? (
                                    /* Healthy State */
                                    <div className="flex flex-col items-center justify-center py-6 px-2 text-center">
                                        <div className="w-12 h-12 rounded-full bg-emerald-50 border border-emerald-100 flex items-center justify-center text-emerald-500 mb-3 shadow-inner">
                                            <CheckCircle size={24} />
                                        </div>
                                        <h4 className="font-bold text-slate-800 text-xs mb-1">Fleet Telemetry Operational</h4>
                                        <p className="text-[10px] text-slate-500 max-w-xs leading-normal">
                                            All active fleet vessels are currently broadcasting stable AIS signals. Geofencing status is fully accurate.
                                        </p>
                                    </div>
                                ) : (
                                    /* Alert State */
                                    <div className="flex flex-col gap-2.5">
                                        <div className="bg-rose-50 border border-rose-100/50 rounded-2xl p-3 text-rose-800 flex gap-2.5 items-start">
                                            <AlertTriangle size={16} className="text-rose-600 shrink-0 mt-0.5" />
                                            <div>
                                                <h4 className="font-extrabold text-[10px] tracking-tight text-rose-900 leading-none mb-0.5 uppercase">
                                                    Manual Logbook Override
                                                </h4>
                                                <p className="text-[10px] text-rose-700/80 leading-normal font-semibold">
                                                    {activeGaps.length} vessel{activeGaps.length > 1 ? 's are' : ' is'} currently incommunicado. Declare cycles manually in the tabs below or check tracking periods in the Vessel Master Data.
                                                </p>
                                            </div>
                                        </div>

                                        <div className="flex flex-col gap-2">
                                            <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest leading-none mb-1">
                                                Incommunicado Vessels:
                                            </p>
                                            
                                            {activeGaps.map((gap) => (
                                                <div 
                                                    key={gap.vesselId} 
                                                    className="flex items-center justify-between p-3 bg-slate-50 hover:bg-slate-100/70 border border-slate-100 rounded-2xl transition-colors gap-2"
                                                >
                                                    <div className="flex flex-col gap-1">
                                                        <div className="flex items-center gap-1.5">
                                                            <span className="bg-rose-600 text-white text-[8px] font-black px-1.5 py-0.5 rounded tracking-wider uppercase">
                                                                {gap.vessel}
                                                            </span>
                                                        </div>
                                                        <div className="flex items-center gap-1 text-[10px] text-slate-600 font-semibold mt-0.5">
                                                            <Clock size={10} className="text-slate-400" />
                                                            {gap.hours === null ? (
                                                                <span>No AIS signal loaded</span>
                                                            ) : (
                                                                <span>Offline for <b className="text-rose-600 font-extrabold">{gap.hours}h</b></span>
                                                            )}
                                                        </div>
                                                    </div>

                                                    {gap.hours !== null && (
                                                        <div className="text-right">
                                                            <p className="text-[8px] text-slate-400 font-black uppercase tracking-widest leading-none mb-0.5">Last Seen</p>
                                                            <p className="text-[9px] text-slate-700 font-bold leading-none">{gap.lastSeen.split(',')[0]}</p>
                                                            <p className="text-[8px] text-slate-400 font-semibold leading-none mt-0.5">{gap.lastSeen.split(',')[1]?.trim()}</p>
                                                        </div>
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Footer */}
                            <div className="p-3 bg-slate-50 border-t border-slate-100 flex items-center justify-between gap-4">
                                <span className="text-[8px] text-slate-400 font-black uppercase tracking-wider">
                                    GeoKanban v3.25
                                </span>
                                <button 
                                    onClick={() => setIsOpen(false)}
                                    className="px-4 py-1.5 bg-slate-900 hover:bg-slate-800 text-white text-[10px] font-black uppercase tracking-wider rounded-xl transition-all shadow active:scale-95 cursor-pointer"
                                >
                                    Dismiss
                                </button>
                            </div>
                        </motion.div>
                    </>
                )}
            </AnimatePresence>
        </div>
    );
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import {
    Users, Search, Shield, ShieldOff, Edit2, Check, X,
    Building, Anchor, Wifi, WifiOff, RefreshCw, UserPlus,
    ChevronDown, AlertTriangle, Clock, Map as MapIcon, BookOpen, Globe, Lock, Unlock, Layers,
    Eye, EyeOff, Calendar, Rewind, Target, Cloud, Box, Database, Bot
} from 'lucide-react';
import { userService } from '../services/api/userService';
import { useFleet } from '../context/DataContext';
import { can, getRoleLabel, getRoleColor, ALL_ROLES_ORDERED } from '../lib/permissions';
import AddUserModal from './AddUserModal';

// ── Helpers ────────────────────────────────────────────────────────────────────
const isOnline = (lastSeen) => {
    if (!lastSeen) return false;
    return (Date.now() - new Date(lastSeen).getTime()) < 2 * 60 * 1000;
};

const fmtDate = (ts) => {
    if (!ts) return '—';
    try {
        return new Date(ts).toLocaleString('it-IT', {
            day: '2-digit', month: '2-digit', year: '2-digit',
            hour: '2-digit', minute: '2-digit'
        });
    } catch { return '—'; }
};

function RoleBadge({ role }) {
    const { bg, text } = getRoleColor(role);
    return (
        <span className="px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest inline-block" style={{ backgroundColor: `${bg}20`, color: text }}>
            {getRoleLabel(role)}
        </span>
    );
}

/** Converte lastSeen in etichetta leggibile. Funzione pura — non usa Date.now() nel render. */
const fmtLastSeen = (lastSeen) => {
    if (!lastSeen) return 'NEVER';
    return `${Math.round((Date.now() - new Date(lastSeen)) / 60000)}m ago`;
};

function OnlineStatus({ lastSeen }) {
    const online = isOnline(lastSeen);
    return (
        <div className="flex items-center gap-2">
            <div className={`w-2 h-2 rounded-full ${online ? 'bg-green-500 animate-pulse' : 'bg-slate-300'}`} />
            <span className={`text-[11px] font-bold ${online ? 'text-green-600' : 'text-slate-400'}`}>
                {online ? 'ONLINE' : fmtLastSeen(lastSeen)}
            </span>
        </div>
    );
}

export default function UserManagementTab() {
    const { vessels } = useFleet();
    const [users, setUsers] = useState([]);
    const [companies, setCompanies] = useState([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [filterRole, setFilterRole] = useState('all');
    const [filterStatus, setFilterStatus] = useState('all');
    const [editingId, setEditingId] = useState(null);
    const [actionLoading, setActionLoading] = useState(null);
    const [error, setError] = useState('');
    const [showAddModal, setShowAddModal] = useState(false);

    const loadData = useCallback(async () => {
        setLoading(true);
        setError('');
        try {
            const { data: usersData, error: uErr } = await userService.fetchUsersWithRelations();
            const companiesData = await userService.fetchCompanies();
            
            if (uErr) {
                console.error("User Load Detail:", uErr);
                if (uErr.message.includes('custom_overrides')) {
                    setError('⚠️ Schema Database non sincronizzato. I permessi speciali non saranno visibili finché lo schema non viene ricaricato in Supabase.');
                    const { data: fallbackData } = await userService.fetchUsersFallback();
                    setUsers(fallbackData || []);
                } else {
                    throw uErr;
                }
            } else {
                setUsers(usersData || []);
            }
            
            setCompanies(companiesData);
        } catch (err) {
            setError('Failed to load users: ' + err.message);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    const filteredUsers = useMemo(() => {
        return users.filter(u => {
            const matchSearch = !search || [u.email, u.display_name, u.mmsi, u.vessels?.name].some(f => f?.toLowerCase().includes(search.toLowerCase()));
            const matchRole = filterRole === 'all' || u.role === filterRole;
            const matchStatus = filterStatus === 'all' || (filterStatus === 'online' && isOnline(u.last_seen_at)) || (filterStatus === 'blocked' && u.is_blocked);
            return matchSearch && matchRole && matchStatus;
        });
    }, [users, search, filterRole, filterStatus]);

    // FIX TOGGLE BLOCK: Forza il valore opposto correttamente
    const toggleBlock = async (user) => {
        if (user.id === 'master-id' || user.role === 'operation_admin') return alert('Cannot block Operation Admin account');
        const nextStatus = !user.is_blocked;
        setActionLoading(user.id);
        try {
            await userService.toggleBlock(user.id, nextStatus);
            await loadData();
        } catch (err) { 
            setError(err.message); 
        } finally { 
            setActionLoading(null); 
        }
    };

    const saveUser = async (userId, form) => {
        setActionLoading(userId);
        setError('');
        try {
            await userService.updateUser(userId, form);
            setEditingId(null);
            await loadData();
        } catch (err) { 
            setError(err.message); 
        } finally { 
            setActionLoading(null); 
        }
    };

    const stats = useMemo(() => ({
        total: users.length,
        online: users.filter(u => isOnline(u.last_seen_at)).length,
        blocked: users.filter(u => u.is_blocked).length,
        crew: users.filter(u => u.role === 'crew').length,
    }), [users]);

    // ── Edit Row Component (Inline Form) ───────────────────────────────────────
    const EditRow = ({ user, companies, vessels, onSave, onCancel }) => {
        const [form, setForm] = useState({
            display_name: user.display_name || '',
            email: user.email || '',
            password: user.password_plain || '',
            role: user.role || 'crew',
            company_id: user.company_id || '',
            vessel_id: user.vessel_id || '',
            mmsi: user.mmsi || '',
            custom_overrides: user.custom_overrides || {}
        });

        const [showPassword, setShowPassword] = useState(false);

        const toggleOverride = (key) => setForm(p => ({
            ...p,
            custom_overrides: { ...p.custom_overrides, [key]: !p.custom_overrides?.[key] }
        }));

        return (
            <tr className="bg-primary/5">
                <td className="px-6 py-6 rounded-l-[2rem]">
                    <div className="space-y-2">
                        <input className="w-full bg-white border border-primary/20 rounded-full px-5 py-3 text-sm font-bold shadow-xl shadow-primary/5 outline-none focus:ring-2 focus:ring-primary/20" value={form.display_name} onChange={e => setForm({...form, display_name: e.target.value})} placeholder="Full Name" />
                        <div className="grid grid-cols-2 gap-2">
                            <input className="bg-white border border-primary/10 rounded-full px-4 py-2 text-[10px] font-bold outline-none" value={form.email} onChange={e => setForm({...form, email: e.target.value})} placeholder="New Email" />
                            <div className="relative">
                                <input 
                                    className="w-full bg-white border border-primary/10 rounded-full px-4 py-2 pr-10 text-[10px] font-bold outline-none font-mono" 
                                    type={showPassword ? "text" : "password"} 
                                    value={form.password} 
                                    onChange={e => setForm({...form, password: e.target.value})} 
                                    placeholder="Password" 
                                />
                                <button 
                                    type="button"
                                    onClick={() => setShowPassword(!showPassword)}
                                    className="absolute right-3 top-1/2 -translate-y-1/2 text-primary/30 hover:text-primary transition-colors"
                                >
                                    {showPassword ? <EyeOff size={14} /> : <Eye size={14} />}
                                </button>
                            </div>
                        </div>
                    </div>
                </td>
                <td className="px-6 py-6">
                    <div className="space-y-2">
                        <select className="w-full bg-white border border-primary/20 rounded-full px-5 py-2 text-xs font-black uppercase outline-none" value={form.role} onChange={e => setForm({...form, role: e.target.value})}>
                            {ALL_ROLES_ORDERED.map(r => <option key={r.value} value={r.value}>{r.label}</option>)}
                        </select>
                        <select className="w-full bg-white border border-primary/20 rounded-full px-5 py-2 text-[10px] font-black uppercase text-on-surface/40 outline-none" value={form.company_id} onChange={e => setForm({...form, company_id: e.target.value})}>
                            <option value="">No Company</option>
                            {companies.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                        </select>
                    </div>
                </td>
                <td className="px-6 py-6" colSpan={2}>
                    <div className="flex flex-col gap-2">
                        <div className="flex items-center gap-2">
                           <select 
                                className="grow bg-white border border-primary/20 rounded-full px-5 py-3 text-xs font-bold outline-none" 
                                value={form.vessel_id} 
                                onChange={e => {
                                    const vId = e.target.value;
                                    const v = vessels.find(x => x.id === vId);
                                    setForm({ ...form, vessel_id: vId, mmsi: v?.mmsi || '' });
                                }}
                           >
                                <option value="">Select Assigned Vessel</option>
                                {vessels.map(v => <option key={v.id} value={v.id}>{v.name} ({v.mmsi})</option>)}
                           </select>
                           <input className="w-32 bg-white border border-primary/20 rounded-full px-5 py-3 text-xs font-mono font-bold outline-none" placeholder="Custom MMSI" value={form.mmsi} onChange={e => setForm({...form, mmsi: e.target.value})} />
                        </div>
                        <div className="flex flex-wrap items-center gap-1.5 mt-2 max-w-lg">
                                {[
                                    { id: 'show_map', icon: MapIcon, title: 'Mappa Flotta Live' },
                                    { id: 'access_logbook', icon: BookOpen, title: 'Logbook & Sottomissione' },
                                    { id: 'see_all_vessels', icon: Globe, title: 'Visibilità Tutta la Flotta' },
                                    { id: 'admin_dashboard', icon: Shield, title: 'Accesso Dashboard Admin' },
                                    { id: 'see_logbook_submitted', icon: Edit2, title: 'Visibilità Tab Submitted Logbooks' },
                                    { id: 'see_schedule', icon: Calendar, title: 'Visibilità Tab Schedule' },
                                    { id: 'edit_schedule', icon: Unlock, title: 'Abilita Modifica Schedule' },
                                    { id: 'see_rewind', icon: Rewind, title: 'Visibilità Tab Rewind' },
                                    { id: 'see_copilot', icon: Bot, title: 'Visibilità Copilot IA' },
                                    { id: 'see_production', icon: Target, title: 'Visibilità Tab Production Targets' },
                                    { id: 'see_weather', icon: Cloud, title: 'Visibilità Tab Weather Analytics' },
                                    { id: 'see_3d', icon: Box, title: 'Visibilità Tab 3D Viewer' },
                                    { id: 'see_dbmanager', icon: Database, title: 'Visibilità Tab DB Manager' }
                                ].map(p => (
                                    <button key={p.id} title={p.title} type="button" onClick={() => toggleOverride(p.id)} className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${form.custom_overrides?.[p.id] ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'bg-white border border-surface-low text-on-surface/10 hover:text-on-surface/30'}`}>
                                        <p.icon size={14} />
                                    </button>
                                ))}
                        </div>
                    </div>
                </td>
                <td className="px-6 py-6 rounded-r-[2rem] text-right">
                    <div className="flex items-center justify-end gap-3">
                        <button onClick={() => onSave(user.id, form)} className="bg-primary text-white h-12 px-8 rounded-full text-xs font-black uppercase tracking-widest shadow-xl shadow-primary/20 hover:scale-105 active:scale-95 transition-all">Save Profile</button>
                        <button onClick={onCancel} className="bg-surface-low/30 text-on-surface/40 h-12 px-8 rounded-full text-xs font-black uppercase tracking-widest hover:bg-red-50 hover:text-red-500 transition-all">Cancel</button>
                    </div>
                </td>
            </tr>
        );
    };

    return (
        <div className="space-y-6 lg:space-y-8 animate-in fade-in duration-1000 pb-20">
            {/* Header Kinetic */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                <div>
                   <h2 className="font-manrope font-extrabold text-2xl text-on-surface tracking-tight leading-none uppercase">User Management</h2>
                   <p className="text-[10px] font-black text-on-surface/40 uppercase tracking-widest mt-2">Gestione accessi flotta e permessi granulari</p>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={loadData} className="w-12 h-12 rounded-full bg-white border border-surface-low/30 flex items-center justify-center text-on-surface/40 hover:text-primary transition-all shadow-sm">
                        <RefreshCw size={20} className={loading ? 'animate-spin' : ''} />
                    </button>
                    <button 
                        onClick={() => setShowAddModal(true)}
                        className="flex items-center gap-3 bg-primary hover:bg-primary-dark text-white h-12 px-8 rounded-full text-[10px] font-black uppercase tracking-widest transition-all shadow-xl shadow-primary/10 hover:-translate-y-0.5"
                    >
                        <UserPlus size={18} /> Add New User
                    </button>
                </div>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                {[
                    { label: 'Total Users', value: stats.total, color: 'text-blue-500', bg: 'bg-blue-50', icon: Users },
                    { label: 'Online Now', value: stats.online, color: 'text-green-500', bg: 'bg-green-50', icon: Wifi },
                    { label: 'Blocked', value: stats.blocked, color: 'text-red-500', bg: 'bg-red-50', icon: Lock },
                    { label: 'Crew Members', value: stats.crew, color: 'text-amber-500', bg: 'bg-amber-50', icon: Anchor },
                ].map((s, i) => (
                    <div key={i} className="bg-white rounded-[2rem] p-6 border border-white shadow-sm flex items-center gap-5">
                        <div className={`w-12 h-12 rounded-2xl ${s.bg} flex items-center justify-center`}>
                            <s.icon size={22} className={s.color} />
                        </div>
                        <div>
                            <p className="text-[10px] font-black text-on-surface/40 uppercase tracking-widest leading-none mb-1">{s.label}</p>
                            <h3 className="text-2xl font-manrope font-extrabold text-on-surface tracking-tight leading-none">{s.value}</h3>
                        </div>
                    </div>
                ))}
            </div>

            {/* Toolbar Filtri Kinetic */}
            <div className="flex flex-col lg:flex-row lg:items-center gap-4 bg-white/50 backdrop-blur-md rounded-[3rem] p-2 lg:p-3 border border-white shadow-sm">
                <div className="flex items-center gap-3 px-8 py-3 bg-white rounded-full flex-1 border border-surface-low/30 shadow-inner max-w-sm ml-1">
                    <Search size={16} className="text-on-surface/20" />
                    <input 
                        type="text" 
                        placeholder="Search users..." 
                        className="bg-transparent border-none outline-none text-[11px] font-bold text-on-surface w-full placeholder:text-on-surface/20"
                        value={search}
                        onChange={e => setSearch(e.target.value)}
                    />
                </div>
                <div className="flex flex-wrap items-center gap-2 pr-1 ml-auto">
                    <select value={filterRole} onChange={e => setFilterRole(e.target.value)} className="bg-white border border-surface-low/30 px-6 py-3 rounded-full text-[9px] font-black uppercase text-on-surface outline-none">
                        <option value="all">Ruoli: Tutti</option>
                        {ALL_ROLES_ORDERED.map(r => <option key={r.value} value={r.value}>{r.label}</option>)}
                    </select>
                    <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="bg-white border border-surface-low/30 px-6 py-3 rounded-full text-[9px] font-black uppercase text-on-surface outline-none">
                        <option value="all">Status: Tutti</option>
                        <option value="online">Online</option>
                        <option value="blocked">Bloccati</option>
                    </select>
                </div>
            </div>

            {error && (
                <div className="bg-red-50 border border-red-100 rounded-2xl p-6 flex items-center gap-4 text-red-600 animate-in slide-in-from-top">
                    <AlertTriangle size={20} />
                    <span className="text-xs font-black uppercase tracking-widest">{error}</span>
                    <button onClick={() => setError('')} className="ml-auto text-red-300 hover:text-red-500"><X size={18} /></button>
                </div>
            )}

            {/* Table Kinetic */}
            <div className="bg-white/50 backdrop-blur-md rounded-[3rem] p-4 lg:p-10 border border-white shadow-sm overflow-x-auto mt-4">
                <table className="w-full text-left border-separate border-spacing-y-2">
                    <thead>
                        <tr className="text-[10px] font-black text-on-surface/20 uppercase tracking-[0.2em]">
                            <th className="px-8 py-4">Dati Utente</th>
                            <th className="px-8 py-4">Ruolo & Compagnia</th>
                            <th className="px-8 py-4">Status</th>
                            <th className="px-8 py-4">Permessi</th>
                            <th className="px-8 py-4 text-right">Azioni</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredUsers.length === 0 ? (
                            <tr><td colSpan={5} className="py-20 text-center text-on-surface/30 font-bold italic">{loading ? 'Loading...' : 'Nessun utente trovato'}</td></tr>
                        ) : filteredUsers.map(user => (
                            editingId === user.id ? (
                                <EditRow key={user.id} user={user} companies={companies} vessels={vessels} onSave={saveUser} onCancel={() => setEditingId(null)} />
                            ) : (
                                <tr key={user.id} className={`group ${user.is_blocked ? 'opacity-40 grayscale' : ''}`}>
                                    <td className="px-8 py-5 bg-white rounded-l-[2rem]">
                                        <div className="flex items-center gap-5">
                                            <div className="w-12 h-12 rounded-full bg-gradient-to-br from-primary to-secondary text-white flex items-center justify-center font-black text-sm border-4 border-white shadow-sm relative">
                                                {(user.display_name || user.email || '?')[0].toUpperCase()}
                                                {user.is_blocked && <div className="absolute -top-1 -right-1 bg-red-500 rounded-full p-1 text-white shadow-lg"><Lock size={10} /></div>}
                                            </div>
                                            <div>
                                                <div className="font-extrabold text-sm text-on-surface leading-none mb-1.5 uppercase tracking-tight">{user.display_name || 'Not Set'}</div>
                                                <div className="text-[10px] font-bold text-on-surface/40 leading-none">{user.email}</div>
                                                <div className="text-[10px] font-extrabold text-primary mt-2 flex items-center gap-1.5 uppercase tracking-wider font-mono bg-primary/10 px-2.5 py-1 rounded-full w-fit border border-primary/20 shadow-sm">
                                                    <Lock size={10} /> PWD: {user.password_plain || 'GeoKanban2026!'}
                                                </div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-8 py-5 bg-white">
                                         <div className="flex flex-col gap-2">
                                             <RoleBadge role={user.role} />
                                             <div className="flex items-center gap-1.5 opacity-30 text-[9px] font-black uppercase tracking-widest">
                                                 <Building size={10} /> {user.companies?.name || 'GeoKanban Fleet'}
                                             </div>
                                             {user.role === 'crew' && (
                                                 <div className="flex items-center gap-1.5 text-primary text-[9px] font-black uppercase tracking-widest bg-primary/5 px-2 py-1 rounded-md w-fit">
                                                     <Anchor size={10} /> {user.vessels?.name || 'No Vessel'} ({user.mmsi || user.vessels?.mmsi || 'N/A'})
                                                 </div>
                                             )}
                                         </div>
                                     </td>
                                    <td className="px-8 py-5 bg-white">
                                        <OnlineStatus lastSeen={user.last_seen_at} />
                                        {user.last_seen_at && <div className="text-[9px] font-black text-on-surface/20 mt-1.5 uppercase tracking-widest">{fmtDate(user.last_seen_at)}</div>}
                                    </td>
                                    <td className="px-8 py-5 bg-white">
                                        <div className="flex flex-wrap items-center gap-1 max-w-[200px]">
                                            {[
                                                { id: 'show_map', icon: MapIcon, title: 'Mappa Flotta Live' },
                                                { id: 'access_logbook', icon: BookOpen, title: 'Logbook & Sottomissione' },
                                                { id: 'see_all_vessels', icon: Globe, title: 'Visibilità Tutta la Flotta' },
                                                { id: 'admin_dashboard', icon: Shield, title: 'Accesso Dashboard Admin' },
                                                { id: 'see_logbook_submitted', icon: Edit2, title: 'Visibilità Tab Submitted Logbooks' },
                                                { id: 'see_schedule', icon: Calendar, title: 'Visibilità Tab Schedule' },
                                                { id: 'edit_schedule', icon: Unlock, title: 'Abilita Modifica Schedule' },
                                                { id: 'see_rewind', icon: Rewind, title: 'Visibilità Tab Rewind' },
                                                { id: 'see_copilot', icon: Bot, title: 'Visibilità Copilot IA' },
                                                { id: 'see_production', icon: Target, title: 'Visibilità Tab Production Targets' },
                                                { id: 'see_weather', icon: Cloud, title: 'Visibilità Tab Weather Analytics' },
                                                { id: 'see_3d', icon: Box, title: 'Visibilità Tab 3D Viewer' },
                                                { id: 'see_dbmanager', icon: Database, title: 'Visibilità Tab DB Manager' }
                                            ].map(p => {
                                                // Calcola il permesso effettivo (Base + Override)
                                                const effectivePerms = can(user.role, user.custom_overrides || {});
                                                // Mappa gli ID delle icone ai nomi dei permessi in permissions.js
                                                const mapping = {
                                                    'show_map': effectivePerms.showMap,
                                                    'access_logbook': effectivePerms.submitLogbook,
                                                    'see_all_vessels': effectivePerms.seeAllVessels,
                                                    'admin_dashboard': effectivePerms.adminDashboard,
                                                    'see_logbook_submitted': effectivePerms.seeSubmittedLogbooks,
                                                    'see_schedule': effectivePerms.seeSchedule,
                                                    'edit_schedule': effectivePerms.editSchedule,
                                                    'see_rewind': effectivePerms.seeRewindMap,
                                                    'see_copilot': effectivePerms.seeCopilot,
                                                    'see_production': effectivePerms.seeProductionTargets,
                                                    'see_weather': effectivePerms.seeWeatherAnalytics,
                                                    'see_3d': effectivePerms.seePointCloud,
                                                    'see_dbmanager': effectivePerms.accessDBManager
                                                };
                                                const isActive = mapping[p.id];

                                                return (
                                                    <div 
                                                        key={p.id} 
                                                        title={`${p.title} (${isActive ? 'ATTIVO' : 'DISATTIVO'})`}
                                                        className={`w-6 h-6 rounded flex items-center justify-center transition-all ${isActive ? 'bg-primary/10 text-primary shadow-sm ring-1 ring-primary/20' : 'bg-surface-low/10 text-on-surface/5'}`}
                                                    >
                                                        <p.icon size={11} />
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </td>
                                    <td className="px-8 py-5 bg-white rounded-r-[2rem] text-right">
                                        <div className="flex items-center justify-end gap-2 pr-2">
                                            {/* BLINDATURA: Nascondi controlli per Operation Admin Profilo Master */}
                                            {user.role !== 'operation_admin' && (
                                                <>
                                                    <button 
                                                        title="Modifica Profilo"
                                                        onClick={() => setEditingId(user.id)}
                                                        className="w-10 h-10 rounded-full bg-surface-low/20 flex items-center justify-center text-on-surface/20 hover:bg-primary/10 hover:text-primary transition-all"
                                                    >
                                                        <Edit2 size={16} />
                                                    </button>
                                                    <button 
                                                        title={user.is_blocked ? "Sblocca Utente" : "Blocca Accesso Utente"}
                                                        onClick={() => toggleBlock(user)}
                                                        className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${user.is_blocked ? 'bg-green-500 text-white shadow-lg' : 'bg-surface-low/20 text-red-400 hover:bg-red-50 hover:text-red-500'}`}
                                                    >
                                                        {user.is_blocked ? <Unlock size={16} /> : <Lock size={16} />}
                                                    </button>
                                                </>
                                            )}
                                            {user.role === 'operation_admin' && (
                                                <div className="w-10 h-10 flex items-center justify-center text-primary/20" title="Super Admin Account - Inviolabile">
                                                    <Shield size={20} />
                                                </div>
                                            )}
                                        </div>
                                    </td>
                                </tr>
                            )
                        ))}
                    </tbody>
                </table>
            </div>

            {showAddModal && <AddUserModal onClose={() => setShowAddModal(false)} onUserAdded={loadData} companies={companies} vessels={vessels} />}
        </div>
    );
}

﻿import React, { useState, useMemo } from 'react';
import { useFleet, useOperations, useConfig } from '../context/DataContext';
import { messagesService } from '../services/api/messagesService';
import { activityService } from '../services/api/activityService';
import { formatTime, calcDuration } from '../utils/timeFormatters';
import { activityColor, getVesselActivities, countActivitiesByType } from '../utils/activityUtils';
import { exportActivitiesToExcel } from '../utils/excelExporter';
import {
    Ship, MapPin, Clock, Filter, RefreshCw, Anchor, Navigation,
    ArrowDownRight, ArrowUpRight, Search, Edit3, Check, X, Trash2, Plus,
    BookOpen, ShieldCheck, Wind, BarChart2, CalendarDays, MessageSquare, ChevronRight, FileText, CheckCircle, Eye,
    Target, TrendingUp, Package, AlertTriangle
} from 'lucide-react';
import LogbookEntryModal from './LogbookEntryModal';
import ActivityChatModal from './ActivityChatModal';
import ManualActivityModal from './ManualActivityModal';
import EditActivityModal from './EditActivityModal';
import { can } from '../lib/permissions';
import ActivityKPIArchive from './vesselactivity/ActivityKPIArchive';


export default function VesselActivityTab({ 
    view = 'all',
    vesselFilter, setVesselFilter
}) {
    const { vessels, crewVesselId, companyVesselIds } = useFleet();
    const { activities, loading, fetchActivities, productionPlans, selectedMonth, setSelectedMonth, selectedYear, setSelectedYear } = useOperations();
    const { profile: userProfile } = useConfig();
    const perms = userProfile?.permissions || can(userProfile?.role);

    const [search, setSearch] = useState('');
    const [logbookActivity, setLogbookActivity] = useState(null);
    const [chatActivity, setChatActivity] = useState(null);
    const [isChatReadOnly, setIsChatReadOnly] = useState(false);
    const [hoverData, setHoverData] = useState({ id: null, messages: [], loading: false });
    const [showManualModal, setShowManualModal] = useState(false);
    const [editAdminActivity, setEditAdminActivity] = useState(null);

    const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June',
        'July', 'August', 'September', 'October', 'November', 'December'];

    const { aisStats, activitiesInPeriod } = useMemo(() => {
        if (!activities) return { aisStats: { total: 0, submitted: 0 }, activitiesInPeriod: [] };
        
        let total = 0;
        let submittedCount = 0;

        const filtered = activities.filter(a => {
            // Filtro Permission (Check di base)
            let isVisible = true;
            if (a.vesselId !== null) {
                if (perms.seeCompanyVessels && companyVesselIds) isVisible = companyVesselIds.includes(a.vesselId);
                if (perms.seeOwnVesselOnly && crewVesselId) isVisible = a.vesselId === crewVesselId;
            }
            
            if (!isVisible) return false;

            // Logica Contatori (su base visibile/permessa)
            total++;
            const isSubmitted = ['submitted', 'approved'].includes(a.logbookStatus);
            if (isSubmitted) submittedCount++;

            // Filtro Vista
            if (view === 'submitted' && !isSubmitted) return false;
            // ADMIN PERSISTENCE: Se admin (Operations/Admin), vede tutto nel tab Vessel Activity (view === 'to-submit')
            if (view === 'to-submit' && isSubmitted && !perms.adminDashboard) return false;

            return true;
        });

        return {
            aisStats: { total, submitted: submittedCount },
            activitiesInPeriod: filtered
        };
    }, [activities, perms, crewVesselId, companyVesselIds, view, userProfile]);

    const { filtered, weatherStandbys } = useMemo(() => {
        let base = activitiesInPeriod || [];
        
        const globalStandbys = base.filter(a => a.vesselId === null && a.activity === 'Weather Stand-by');
        // Do not filter out global standbys, we want them to show in the table
        
        const q = search.toLowerCase().trim();
        if (vesselFilter === 'IN_PROGRESS') {
            base = base.filter(a => !a.endTime || a.status === 'in-progress');
        } else if (vesselFilter !== 'All') {
            base = base.filter(a => a.vessel === vesselFilter);
        }
        if (q) base = base.filter(a => 
            a.vessel?.toLowerCase().includes(q) || 
            a.activity?.toLowerCase().includes(q) || 
            (a.geofence || '').toLowerCase().includes(q)
        );

        base = base.map(a => {
            const aStart = new Date(a.startTime).getTime();
            const aEnd = a.endTime ? new Date(a.endTime).getTime() : new Date().getTime();
            
            const overlaps = globalStandbys.filter(ws => {
                if (a.vesselId === null) return false;
                const wsStart = new Date(ws.startTime).getTime();
                const wsEnd = ws.endTime ? new Date(ws.endTime).getTime() : new Date().getTime();
                return aStart < wsEnd && aEnd > wsStart;
            });
            
            return { ...a, overlappingStandbys: overlaps };
        });

        return { filtered: base };
    }, [activitiesInPeriod, vesselFilter, search]);


    const handleCloseMonth = async () => {
        if (!confirm('Close current month and generate Certified SAL?')) return;
        try {
            const hash = await activityService.certifyMonthlySal(selectedMonth + 1, selectedYear);
            alert('Certification successful! Hash: ' + hash);
            fetchActivities();
        } catch (error) {
            alert(error.message);
        }
    };

    const handleDeleteActivity = async (activity) => {
        const isSubmitted = ['submitted', 'approved'].includes(activity.logbookStatus);
        const warningMsg = isSubmitted 
            ? `âš ï¸ WARNING: This activity is already SUBMITTED or APPROVED.\nDeleting it will affect Certified SAL totals.\n\nAre you sure you want to delete this activity?`
            : `Are you sure you want to delete this activity? This will also delete any associated chat messages or logbook entries.`;

        if (!confirm(warningMsg)) return;

        try {
            await activityService.deleteActivity(activity.id);
            let targetId = null;
            if (userProfile?.role === 'crew') targetId = crewVesselId;
            else if (userProfile?.role === 'crew_admin') targetId = companyVesselIds;
            fetchActivities(targetId, userProfile?.role);
        } catch (error) {
            alert('Error deleting activity: ' + error.message);
        }
    };

    const handleExportExcel = () => {
        exportActivitiesToExcel(filtered, selectedYear, selectedMonth);
    };

    const handleMessageHover = async (activityId) => {
        if (hoverData.id === activityId) return;
        setHoverData({ id: activityId, messages: [], loading: true });
        try {
            const data = await messagesService.fetchRecentMessages(activityId, 2);
            setHoverData({ id: activityId, messages: data.reverse(), loading: false });
        } catch (err) {
            console.error('Error fetching hover messages:', err);
            setHoverData({ id: null, messages: [], loading: false });
        }
    };

    return (
        <div className="space-y-6 lg:space-y-8 animate-in fade-in duration-1000 pb-20">
            {/* KPI STATS & ARCHIVE visibili solo agli admin nel tab principale o 'all' */}
            {perms.adminDashboard && (view === 'all' || view === 'to-submit') && (
                <>
                    {/* PRODUCTION KPI ROW */}
                    <ActivityKPIArchive productionPlans={productionPlans} selectedMonth={selectedMonth} selectedYear={selectedYear} aisStats={aisStats} vessels={vessels} activities={activities} />

                </>
            )}

            {/* TOOLBAR COMPACT - OPTIMIZED */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-3 bg-white/50 backdrop-blur-md rounded-[1.5rem] p-1.5 border border-white shadow-sm">
                        <div className="flex items-center gap-3 px-4 py-2 bg-white rounded-[1.25rem] border border-surface-low/30 shadow-inner max-w-xs flex-1 ml-0.5">
                            <Search size={14} className="text-on-surface/20" />
                            <input type="text" placeholder="Search activities..." className="bg-transparent border-none outline-none text-[11px] font-bold text-on-surface w-full placeholder:text-on-surface/20 uppercase tracking-tight" value={search} onChange={e => setSearch(e.target.value)} />
                        </div>
                        
                            <div className="flex flex-wrap items-center gap-1.5 pr-0.5">
                                <div className="flex items-center bg-white border border-surface-low/30 rounded-xl overflow-hidden shadow-sm">
                                    <select value={selectedMonth} onChange={e => setSelectedMonth(parseInt(e.target.value))} className="bg-transparent pl-4 pr-2 py-2 text-[9px] font-black uppercase text-on-surface outline-none cursor-pointer hover:bg-surface-low/10 transition-colors">
                                        {MONTHS.map((m, i) => <option key={i} value={i}>{m}</option>)}
                                    </select>
                                    <div className="w-px h-4 bg-surface-low/30" />
                                    <select value={selectedYear} onChange={e => setSelectedYear(parseInt(e.target.value))} className="bg-transparent px-2 py-2 text-[9px] font-black uppercase text-on-surface outline-none cursor-pointer hover:bg-surface-low/10 transition-colors">
                                        {[2023, 2024, 2025, 2026].map(y => <option key={y} value={y}>{y}</option>)}
                                    </select>
                                    <div className="w-px h-4 bg-surface-low/30" />
                                    <select value={vesselFilter} onChange={e => setVesselFilter(e.target.value)} className="bg-transparent pl-2 pr-4 py-2 text-[9px] font-black uppercase text-on-surface outline-none cursor-pointer hover:bg-surface-low/10 transition-colors">
                                        <option value="All">All Vessels</option>
                                        <option value="IN_PROGRESS" style={{ fontWeight: 'bold', color: '#0284c7' }}>âš¡ IN PROGRESS ACTIVITIES ONLY</option>
                                        {perms.adminDashboard ? (
                                            (vessels || [])
                                                .filter(v => v.tracking_active)
                                                .map(v => <option key={v.id} value={v.name}>{v.name}</option>)
                                        ) : (
                                            <option value={userProfile?.vesselName || 'Crew'}>{userProfile?.vesselName || 'My Vessel'}</option>
                                        )}
                                    </select>
                                </div>
                            
                            {(perms.adminDashboard || view === 'submitted') && (
                                <>
                                    <button onClick={handleExportExcel} className="flex items-center gap-2 bg-white hover:bg-slate-50 border border-surface-low/30 px-4 py-2 rounded-xl text-[9px] font-black text-on-surface/50 uppercase tracking-widest transition-all shadow-sm">
                                        <FileText size={12} className="text-primary/60" /> Export Certified
                                    </button>
                                </>
                            )}
                            
                            {(perms.submitLogbook || perms.approveLogbook) && (
                                <button
                                    onClick={() => setShowManualModal(true)}
                                    className="flex items-center gap-2 bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-600 hover:to-amber-700 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all shadow-sm shadow-amber-500/10 border-none cursor-pointer"
                                >
                                    <Plus size={12} /> Add Activity
                                </button>
                            )}
                            
                            <button onClick={fetchActivities} className={`w-9 h-9 bg-white border border-surface-low/30 text-on-surface/20 rounded-full flex items-center justify-center transition-all hover:text-primary hover:border-primary/30 shadow-sm cursor-pointer ${loading ? 'animate-spin border-primary' : ''}`}>
                                <RefreshCw size={14} />
                            </button>
                        </div>
                    </div>

                    {/* TABLE COMPACT */}
                    <div className="bg-white/50 backdrop-blur-md rounded-2xl p-2 lg:p-4 border border-white shadow-sm overflow-x-auto mt-2">
                        <table className="w-full text-left border-separate border-spacing-y-1">
                            <thead>
                                <tr className="text-[9px] font-black text-on-surface/20 uppercase tracking-[0.1em]">
                                    <th className="px-4 py-3 w-[4%] min-w-[50px] whitespace-nowrap">Ref</th>
                                    {view === 'submitted' ? (
                                        <>
                                            <th className="px-4 py-3 w-[12%] min-w-[110px] whitespace-nowrap">Vessel</th>
                                            <th className="px-4 py-3 w-[15%] min-w-[130px] whitespace-nowrap text-left">Activity</th>
                                            <th className="px-4 py-3 w-[10%] min-w-[110px] whitespace-nowrap">ATA / ATD</th>
                                            <th className="px-4 py-3 w-[8%] min-w-[80px] whitespace-nowrap">Pilots (In/Out)</th>
                                            <th className="px-4 py-3 w-[8%] min-w-[80px] whitespace-nowrap">Moor (In/Out)</th>
                                            <th className="px-4 py-3 w-[10%] min-w-[100px] whitespace-nowrap">Tugs (U / S {'>'} E)</th>
                                            <th className="px-4 py-3 text-left w-[22%] min-w-[180px]">NARRATIVE / NOTES</th>
                                            <th className="px-4 py-3 text-left w-[10%] min-w-[110px] whitespace-nowrap">RESPONSIBLE</th>
                                            <th className="px-4 py-3 text-left w-[8%] min-w-[90px] whitespace-nowrap">HASH</th>
                                            <th className="px-4 py-3 text-center w-[4%] min-w-[60px] whitespace-nowrap">Status</th>
                                        </>
                                    ) : (
                                        <>
                                            <th className="px-4 py-3 w-[15%] min-w-[130px] whitespace-nowrap text-left">Activity</th>
                                            <th className="px-4 py-3 w-[12%] min-w-[110px] whitespace-nowrap">Vessel</th>
                                            <th className="px-4 py-3 text-left w-[25%] min-w-[180px] whitespace-nowrap">Geofence / Hub</th>
                                            <th className="px-4 py-3 w-[12%] min-w-[110px] whitespace-nowrap">Arrived (ATA)</th>
                                            <th className="px-4 py-3 w-[12%] min-w-[110px] whitespace-nowrap">Departed (ATD)</th>
                                            <th className="px-4 py-3 w-[10%] min-w-[100px] whitespace-nowrap text-sky-700">AIS Draft (In/Out)</th>
                                            <th className="px-4 py-3 w-[8%] min-w-[80px] whitespace-nowrap">Duration</th>
                                            <th className="px-4 py-3 w-[8%] min-w-[90px] whitespace-nowrap">Weather</th>
                                            <th className="px-4 py-3 text-center w-[4%] min-w-[60px] whitespace-nowrap">Status</th>
                                        </>
                                    )}
                                    <th className="px-4 py-3 text-right w-[4%] min-w-[60px] whitespace-nowrap">MSG</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filtered.map((a, i) => {
                                    const isSubmitted = ['submitted', 'approved'].includes(a.logbookStatus);
                                    const entry = a.logbookEntry || {};
                                    const sf = entry.structured_fields || {};
                                    
                                    const vesselCell = (
                                        <td className="px-4 py-3 bg-white font-manrope font-extrabold text-xs text-on-surface uppercase tracking-tight">
                                            <div className="flex items-center gap-1.5">
                                                {a.isFleetEvent ? (
                                                    <span className="text-purple-600 bg-purple-50 px-2 py-1 rounded-lg border border-purple-100 flex items-center gap-1.5 shadow-sm">
                                                        {a.vessel}
                                                    </span>
                                                ) : (
                                                    a.vessel
                                                )}
                                                {a.source === 'manual' && (
                                                    <span className="bg-amber-500 text-white text-[8px] font-black uppercase tracking-wider px-1.5 py-0.5 rounded flex items-center gap-0.5" title="Manually Entered Activity">
                                                        <AlertTriangle size={8} /> MANUAL
                                                    </span>
                                                )}
                                            </div>
                                        </td>
                                    );

                                    const activityCell = (
                                        <td className="px-4 py-3 bg-white">
                                            <div className="flex items-center gap-2">
                                                <span 
                                                    className={`text-[9px] font-black uppercase tracking-tight px-2 py-0.5 rounded-lg border border-current/10 ${a.isFleetEvent ? 'shadow-sm border-purple-200' : ''}`} 
                                                    style={{ 
                                                        backgroundColor: a.isFleetEvent ? '#f3e8ff' : `${activityColor(a.activity)}10`, 
                                                        color: a.isFleetEvent ? '#a855f7' : activityColor(a.activity) 
                                                    }}
                                                >
                                                    {a.activity}
                                                </span>
                                                {a.overlappingStandbys && a.overlappingStandbys.length > 0 && (
                                                    <div className="flex items-center gap-1" title={`${a.overlappingStandbys.length} Stand-by meteo in cantiere durante questa attivitÃ `}>
                                                        {a.overlappingStandbys.map((_, idx) => (
                                                            <div key={idx} className="w-2.5 h-2.5 rounded-full bg-purple-500 shadow-sm border border-purple-200" />
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        </td>
                                    );

                                    return (
                                        <tr key={a.id} className={`group ${a.isFleetEvent ? 'bg-purple-50/50' : ''}`}>
                                            <td className="px-4 py-3 bg-white rounded-l-xl text-[10px] font-black text-on-surface/10">{i + 1}</td>
                                            
                                            {view === 'submitted' ? (
                                                <>
                                                    {vesselCell}
                                                    {activityCell}
                                                    <td className="px-4 py-3 bg-white text-[10px] font-bold text-on-surface/60">
                                                        {formatTime(a.startTime)} <br/> {a.endTime ? formatTime(a.endTime) : '...'}
                                                    </td>
                                                    <td className="px-4 py-3 bg-white text-[10px] font-bold text-on-surface/80">
                                                        {sf.arrival_pilot_in ? formatTime(sf.arrival_pilot_in).split(' ')[1] : 'â€”'} <br/>
                                                        {sf.arrival_pilot_out ? formatTime(sf.arrival_pilot_out).split(' ')[1] : 'â€”'}
                                                    </td>
                                                    <td className="px-4 py-3 bg-white text-[10px] font-bold text-on-surface/80">
                                                        {sf.arrival_mooring_in ? formatTime(sf.arrival_mooring_in).split(' ')[1] : 'â€”'} <br/>
                                                        {sf.arrival_mooring_out ? formatTime(sf.arrival_mooring_out).split(' ')[1] : 'â€”'}
                                                    </td>
                                                    <td className="px-4 py-3 bg-white text-[10px] font-bold text-on-surface/80">
                                                        {sf.arrival_tug_count || 0} U {sf.arrival_tug_in ? formatTime(sf.arrival_tug_in).split(' ')[1] : 'â€”'} {'>'} {sf.arrival_tug_out ? formatTime(sf.arrival_tug_out).split(' ')[1] : 'â€”'}
                                                    </td>
                                                    <td className="px-4 py-3 bg-white text-[10px] font-medium text-on-surface/50 italic truncate max-w-[130px]" title={entry.narrative_text || ''}>
                                                        {entry.narrative_text || 'â€”'}
                                                    </td>
                                                    <td className="px-4 py-3 bg-white text-[10px] font-black text-primary whitespace-nowrap">
                                                        {entry.submitted_by_name?.includes('GeoKanban AI') || entry.submitted_by_name?.includes('AI Auto-Pilot') 
                                                            ? 'ðŸ¤– GeoKanban AI' 
                                                            : (entry.submitted_by_name || 'â€”')}
                                                    </td>
                                                    <td className="px-4 py-3 bg-white text-[10px] font-black text-primary/60 font-mono tracking-tight">
                                                        {entry.document_hash ? entry.document_hash.substring(0, 16).toUpperCase() + '...' : 'PENDING'}
                                                    </td>
                                                    <td className="px-4 py-3 bg-white text-center">
                                                        <div className="flex justify-center items-center gap-2">
                                                            <div className={`${isSubmitted ? 'text-green-500' : 'text-on-surface/20'} transition-transform`} title={isSubmitted ? "Submitted" : "Draft"}>
                                                                <CheckCircle size={18} />
                                                            </div>
                                                            {perms.editActivities && !isSubmitted && (
                                                                <button 
                                                                    onClick={() => setLogbookActivity(a)}
                                                                    disabled={!a.endTime}
                                                                    title={!a.endTime ? "Cannot edit an activity in progress" : ""}
                                                                    className={`flex items-center gap-1 px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all group ${
                                                                        !a.endTime 
                                                                        ? 'bg-surface-low/50 text-on-surface/30 cursor-not-allowed'
                                                                        : 'bg-primary/10 text-primary hover:bg-primary hover:text-white'
                                                                    }`}
                                                                >
                                                                    <Edit3 size={12} className={!a.endTime ? "" : "group-hover:scale-110 transition-transform"} />
                                                                    Edit
                                                                </button>
                                                            )}
                                                            {userProfile?.role === 'operation_admin' && (
                                                                <button 
                                                                    onClick={() => setEditAdminActivity(a)}
                                                                    className="w-8 h-8 rounded-full inline-flex items-center justify-center text-slate-400 hover:text-blue-600 hover:bg-blue-50 transition-all shadow-sm cursor-pointer"
                                                                    title="Admin Full Edit Override"
                                                                >
                                                                    <Edit3 size={13} className="hover:scale-110 transition-transform" />
                                                                </button>
                                                            )}
                                                            {perms.deleteActivities && (
                                                                <button 
                                                                    onClick={() => handleDeleteActivity(a)}
                                                                    className="w-8 h-8 rounded-full inline-flex items-center justify-center text-slate-400 hover:text-red-600 hover:bg-red-50 transition-all shadow-sm cursor-pointer"
                                                                    title="Delete Activity"
                                                                >
                                                                    <Trash2 size={13} className="hover:scale-110 transition-transform" />
                                                                </button>
                                                            )}
                                                        </div>
                                                    </td>
                                                </>
                                            ) : (
                                                <>
                                                    {activityCell}
                                                    {vesselCell}
                                                    <td className="px-4 py-3 bg-white text-[11px] font-bold text-on-surface/40 italic whitespace-nowrap">
                                                        <div className="flex items-center gap-1.5">
                                                            <MapPin size={10} className="opacity-20 flex-shrink-0" />
                                                            {a.geofence || 'Navigation'}
                                                        </div>
                                                    </td>
                                                    <td className="px-4 py-3 bg-white text-[10px] font-bold text-on-surface/60 whitespace-nowrap">{formatTime(a.startTime)}</td>
                                                    <td className="px-4 py-3 bg-white text-[10px] font-bold text-on-surface/60 whitespace-nowrap">
                                                        {a.endTime ? formatTime(a.endTime) : <span className="text-primary italic animate-pulse">In Progress...</span>}
                                                    </td>
                                                    <td className="px-4 py-3 bg-white text-[10px] font-extrabold text-sky-700 bg-sky-50/50 whitespace-nowrap text-center">
                                                        {a.aisStartDraught || 'â€”'} / {a.aisEndDraught || 'â€”'}
                                                    </td>
                                                    <td className="px-4 py-3 bg-white text-[9px] font-black text-on-surface/20 uppercase whitespace-nowrap">{calcDuration(a.startTime, a.endTime) || 'â€”'}</td>
                                                    <td className="px-4 py-3 bg-white whitespace-nowrap">
                                                        <div className={`flex flex-col gap-0.5 text-[9px] uppercase ${a.probable_weather_standby ? 'font-extrabold text-red-500' : 'font-black text-on-surface/40'}`}>
                                                            <div className="flex items-center gap-1">
                                                                <Wind size={10} className={a.probable_weather_standby ? 'text-red-500' : 'text-blue-400'} /> {a.weatherWind || 'â€”'}
                                                            </div>
                                                            <div className="flex items-center gap-1">
                                                                <TrendingUp size={10} className={a.probable_weather_standby ? 'text-red-500' : 'text-cyan-400'} /> {a.weatherWave || 'â€”'}
                                                                {a.probable_weather_standby && <AlertTriangle size={10} className="ml-1 animate-pulse text-red-500" title="Possibile Weather Stand-by (Onde > 1m)" />}
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td className="px-4 py-3 bg-white text-center whitespace-nowrap">
                                                        <div className="flex justify-center items-center gap-2">
                                                            <div className={`${isSubmitted ? 'text-green-500' : 'text-on-surface/20'} transition-transform cursor-pointer`} title={isSubmitted ? "Submitted Entry" : "Draft / Missing"}>
                                                                <CheckCircle size={18} />
                                                            </div>
                                                            {perms.editActivities && !isSubmitted && (
                                                                <button 
                                                                    onClick={() => setLogbookActivity(a)}
                                                                    disabled={!a.endTime}
                                                                    title={!a.endTime ? "Cannot edit an activity in progress" : ""}
                                                                    className={`flex items-center gap-1 px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all group ${
                                                                        !a.endTime 
                                                                        ? 'bg-surface-low/50 text-on-surface/30 cursor-not-allowed'
                                                                        : 'bg-primary/10 text-primary hover:bg-primary hover:text-white'
                                                                    }`}
                                                                >
                                                                    <Edit3 size={12} className={!a.endTime ? "" : "group-hover:scale-110 transition-transform"} />
                                                                    Edit
                                                                </button>
                                                            )}
                                                            {userProfile?.role === 'operation_admin' && (
                                                                <button 
                                                                    onClick={() => setEditAdminActivity(a)}
                                                                    className="w-8 h-8 rounded-full inline-flex items-center justify-center text-slate-400 hover:text-blue-600 hover:bg-blue-50 transition-all shadow-sm cursor-pointer"
                                                                    title="Admin Full Edit Override"
                                                                >
                                                                    <Edit3 size={13} className="hover:scale-110 transition-transform" />
                                                                </button>
                                                            )}
                                                            {perms.deleteActivities && (
                                                                <button 
                                                                    onClick={() => handleDeleteActivity(a)}
                                                                    className="w-8 h-8 rounded-full inline-flex items-center justify-center text-slate-400 hover:text-red-600 hover:bg-red-50 transition-all shadow-sm cursor-pointer"
                                                                    title="Delete Activity"
                                                                >
                                                                    <Trash2 size={13} className="hover:scale-110 transition-transform" />
                                                                </button>
                                                            )}
                                                        </div>
                                                    </td>
                                                </>
                                            )}

                                            <td className="px-4 py-3 bg-white rounded-r-xl text-right relative">
                                                <button 
                                                    onClick={() => {
                                                        setIsChatReadOnly(['submitted', 'approved'].includes(a.logbookStatus));
                                                        setChatActivity(a);
                                                    }} 
                                                    onMouseEnter={() => handleMessageHover(a.id)}
                                                    onMouseLeave={() => setHoverData({ id: null, messages: [], loading: false })}
                                                    className={`w-8 h-8 rounded-full inline-flex items-center justify-center transition-all shadow-sm ${
                                                        (a.totalMsgCount > 0)
                                                        ? 'bg-blue-900 text-white hover:bg-blue-800' 
                                                        : 'bg-surface-low text-on-surface/20 hover:bg-secondary hover:text-white'
                                                    }`}
                                                >
                                                    <MessageSquare size={13} />
                                                    {a.unreadMsgCount > 0 && (
