                                                        <div className="space-y-2">
                                                            {hoverData.messages.map((m, idx) => (
                                                                <div key={idx} className="flex items-start gap-2 text-[10px] font-bold leading-tight">
                                                                    <span className="flex-shrink-0 opacity-50 mt-0.5">
                                                                        {m.sender_role === 'crew' ? 'ðŸ“¤' : 'ðŸ“¥'}
                                                                    </span>
