                    onClose={() => setEditAdminActivity(null)}
                    onSaved={() => fetchActivities(userProfile?.role === 'crew' ? crewVesselId : null, userProfile?.role)}
                />
            )}
            {chatActivity && (
                <ActivityChatModal 
