﻿import { useState, useEffect } from 'react';
import { activityService } from '../services/api/activityService';

export function useActivities() {
    const [activityTypes, setActivityTypes] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchActivityTypes = async () => {
        setLoading(true);
        const { data, error } = await activityService.fetchActivityTypes()
            .order('code');
        if (!error && data) setActivityTypes(data);
        setLoading(false);
    };

    const addActivityType = async (item) => {
        const { data, error } = await activityService.insertActivityType(item);
        if (error) return { success: false, error: error.message };
        setActivityTypes(prev => [...prev, data]);
        return { success: true, data };
    };

    const updateActivityType = async (id, updates) => {
        const { data, error } = await activityService.updateActivityType(id, updates);
        if (error) return { success: false, error: error.message };
        setActivityTypes(prev => prev.map(a => a.id === id ? data : a));
        return { success: true, data };
    };

    const deleteActivityType = async (id) => {
        const { error } = await activityService.deleteActivityType(id);
        if (error) return { success: false, error: error.message };
        setActivityTypes(prev => prev.filter(a => a.id !== id));
        return { success: true };
    };

    useEffect(() => { fetchActivityTypes(); }, []);

    return { activityTypes, loading, fetchActivityTypes, addActivityType, updateActivityType, deleteActivityType };
}

﻿import { useState, useEffect, useCallback } from 'react';
import { activityService } from '../services/api/activityService';
import { useConfig } from '../context/DataContext';
import { weatherService } from '../services/api/weatherService';

/**
 * useActivityLog V3.2 â€” Reads from vessel_activity (materialized)
 * instead of recalculating from geofence_events.
 *
 * @param {string|null} vesselId â€” If provided, filters for a single vessel (crew mode)
 */
export function useActivityLog(vesselId = null) {
    const { profile } = useConfig();
    const [activities, setActivities] = useState([]);
    const [loading, setLoading] = useState(true);
    const [lastUpdate, setLastUpdate] = useState(null);

    const fetchActivities = useCallback(async () => {
        setLoading(true);

        try {
            const { data, error } = await activityService.fetchActivityLog(vesselId);

            

            if (error) throw error;

            // Fetch latest Genoa reference weather (Scanno Diga) from SOLID weatherService
            const genoaWeatherRaw = await weatherService.fetchLatestGenoaWeather();
            const genoaWeather = genoaWeatherRaw ? {
                wind_speed: Math.round((genoaWeatherRaw.wind_speed || 0) / 1.852), // Convert km/h to knots (Open-Meteo unit is km/h usually or kn depending on api unit, but here we keep the conversion to knots intact)
                wind_direction: genoaWeatherRaw.wind_direction,
                wave_height: genoaWeatherRaw.wave_height,
                temp: genoaWeatherRaw.temperature
            } : null;

            // Map to format expected by VesselActivityTab
            const mapped = (data || []).map((row, idx, arr) => {
                let geofenceName = row.geofences?.name || 'â€”';

                if (row.activity_type === 'Navigation') {
                    // Cerca la destinazione (l'attivitÃ  cronologicamente successiva, ovvero quella prima di noi nell'array DESC)
                    let destGeo = null;
                    for (let i = idx - 1; i >= 0; i--) {
                        if (arr[i].vessel_id === row.vessel_id && arr[i].geofences?.name) {
                            destGeo = arr[i].geofences.name;
                            break;
                        }
                    }

                    // Cerca la partenza (l'attivitÃ  cronologicamente precedente, ovvero quella dopo di noi nell'array DESC)
                    let origGeo = null;
                    for (let i = idx + 1; i < arr.length; i++) {
                        if (arr[i].vessel_id === row.vessel_id && arr[i].geofences?.name) {
                            origGeo = arr[i].geofences.name;
                            break;
                        }
                    }

                    if (origGeo && destGeo) {
                        geofenceName = `${origGeo} âž” ${destGeo}`;
                    } else if (destGeo) {
                        geofenceName = `âž” ${destGeo}`;
                    } else if (origGeo) {
                        geofenceName = `${origGeo} âž” â€”`;
                    } else {
                        geofenceName = 'Navigation';
                    }
                }

                return {
                    id: row.id,
                    vessel: row.vessel_id === null ? 'ALL VESSELS' : (row.vessels?.name || 'Unknown'),
                    vesselId: row.vessel_id,
                    mmsi: row.vessels?.mmsi,
                    activity: row.activity_type,
                    geofence: geofenceName,
                    geofenceId: row.geofence_id,
                    startTime: row.start_time,
                    endTime: row.end_time,
                    durationMinutes: row.duration_minutes,
                    source: row.source,
                    status: row.status === 'active' ? 'in-progress' : 'completed',
                    exportFlag: row.export_flag,
                    logbookStatus: row.logbook_entries?.[0]?.status || 'none',
                    deliveredQty: row.logbook_entries?.[0]?.structured_fields?.actual_cargo_tonnes || null,
                    msgCount: row.activity_messages?.length || 0,
                    unreadMsgCount: row.activity_messages?.filter(m => !m.is_read && m.sender_role !== profile?.role).length || 0,
                    weather: genoaWeather
                };
            });

            setActivities(mapped);
            setLastUpdate(new Date());
        } catch (err) {
            console.error('Failed to load vessel_activity:', err.message);
        } finally {
            setLoading(false);
        }
    }, [vesselId, profile?.role]);

    useEffect(() => {
        fetchActivities();
        const interval = setInterval(fetchActivities, 60 * 1000);
        return () => clearInterval(interval);
    }, [fetchActivities]);

    return { activities, loading, lastUpdate, fetchActivities };
}

﻿import { useState, useCallback } from 'react';
import { healthService } from '../services/api/healthService';

/**
 * useHealthCheck â€” Permanent system integrity verifier.
 * Runs inside the app (admin only). No throwaway scripts.
 * 
 * Validates the full pipeline:
 * vessels â†’ geofence_events â†’ vessel_activity â†’ logbook_entries
 */
export function useHealthCheck() {
    const [results, setResults] = useState(null);
    const [running, setRunning] = useState(false);

    const runCheck = useCallback(async () => {
        setRunning(true);
        const checks = [];

        const ok = (name, detail) => checks.push({ name, status: 'ok', detail });
        const fail = (name, detail) => checks.push({ name, status: 'fail', detail });
        const warn = (name, detail) => checks.push({ name, status: 'warn', detail });

        try {
            // 0. Database Connection & KPI Engine
            // Usiamo parametri dummy per testare solo l'esistenza della funzione
            const { error: kpiErr } = await healthService.checkKPIEngine();

            if (kpiErr && kpiErr.message.includes('not found')) {
                fail('Motore KPI', 'MANCANTE: La procedura di sincronizzazione automatica non Ã¨ installata nel database.');
            } else {
                // Se l'errore non Ã¨ "not found", la funzione esiste (anche se fallisce il cast dell'UUID dummy)
                ok('Motore KPI', 'OPERATIVO: Il sistema ricalcola i piani di produzione in tempo reale correttamente.');
            }

            // 1. AIS Pulse (Latency)
            const { data: lastPos } = await healthService.fetchLastPosition();
            if (lastPos?.[0]) {
                const lastDate = new Date(lastPos[0].created_at);
                const timeStr = lastDate.toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
                const delay = (Date.now() - lastDate.getTime()) / 60000;
                
                if (delay < 48 * 60) ok('Telemetria AIS', `FUNZIONANTE: Ultimo segnale ricevuto alle ${timeStr} (${Math.round(delay)} min fa).`);
                else warn('Telemetria AIS', `RITARDO: Ricezione ferma dalle ${timeStr}. Verifica se il tracker delle navi Ã¨ attivo.`);
            } else {
                warn('Telemetria AIS', 'NESSUN DATO: Non ci sono posizioni recenti. Il sistema sta aspettando il primo segnale AIS.');
            }

            // 2. Operational Load (24h)
            const dayAgo = new Date(Date.now() - 24*60*60*1000).toISOString();
            const [ {count: p24}, {count: e24} ] = await healthService.fetchLoad24h(dayAgo);
            ok('Carico Operativo (24h)', `ATTIVITÃ€: Processate ${p24 || 0} posizioni e ${e24 || 0} eventi di ingresso/uscita nelle ultime 24 ore.`);

            // 3. Vessels & Fleet
            const { data: vessels, error: vErr } = await healthService.fetchVesselsHealth();
            if (vErr) fail('Stato Flotta', `ERRORE: Impossibile leggere la lista navi: ${vErr.message}`);
            else ok('Stato Flotta', `CONFIGURATA: ${vessels.length} navi registrate e monitorate dal sistema.`);

            // 4. Vessel Activity Integrity
            const { data: activities } = await healthService.fetchActivitiesHealth();
            if (activities) {
                const active = activities.filter(a => a.status === 'active').length;
                const orphanAuto = activities.filter(a => a.source === 'geofence' && !a.start_event_id).length;
                if (orphanAuto > 0) warn('IntegritÃ  Dati', `DATI VECCHI: Trovate ${orphanAuto} attivitÃ  storiche senza collegamento all'evento. Non influisce sui nuovi calcoli.`);
                else ok('IntegritÃ  Dati', `${active} attivitÃ  live in corso e correttamente collegate al Geofencing.`);
            }

            // 5. User Security
            const { data: profiles } = await healthService.fetchProfilesHealth();
            if (profiles) {
                const blocked = profiles.filter(p => p.is_blocked).length;
                ok('Sicurezza e Accessi', `GESTITI: ${profiles.length} utenti totali (${blocked} bloccati per sicurezza).`);
            }

        } catch (err) {
            fail('System Error', err.message);
        }

        setResults(checks);
        setRunning(false);
    }, []);

    return { results, running, runCheck };
}

