﻿import { useState, useEffect } from 'react';
import { logbookService } from '../services/api/logbookService';

export function useServices() {
    const [services, setServices] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchServices = async () => {
        setLoading(true);
        const { data, error } = await logbookService.fetchServicesCatalog()
            .order('code');
        if (!error && data) setServices(data);
        setLoading(false);
    };

    const addService = async (item) => {
        const { data, error } = await logbookService.insertServiceCatalogItem(item);
        if (error) return { success: false, error: error.message };
        setServices(prev => [...prev, data]);
        return { success: true, data };
    };

    const updateService = async (id, updates) => {
        const { data, error } = await logbookService.updateServiceCatalogItem(id, updates);
        if (error) return { success: false, error: error.message };
        setServices(prev => prev.map(s => s.id === id ? data : s));
        return { success: true, data };
    };

    const deleteService = async (id) => {
        const { error } = await logbookService.deleteServiceCatalogItem(id);
        if (error) return { success: false, error: error.message };
        setServices(prev => prev.filter(s => s.id !== id));
        return { success: true };
    };

    useEffect(() => { fetchServices(); }, []);

    return { services, loading, fetchServices, addService, updateService, deleteService };
}

/**
 * useSessionLock — Hook per limitare l'app ad una sola sessione attiva per utente.
 *
 * ⚠️  STATO ATTUALE: DISABILITATO (ENABLED = false)
 *
 * Per abilitare il Session Lock:
 * 1. Eseguire la migration SQL: supabase/session_lock_prep.sql
 * 2. Cambiare ENABLED = false → ENABLED = true qui sotto
 * 3. Testare il comportamento in development prima del deploy
 *
 * COME FUNZIONA (quando abilitato):
 * - Al login, viene generato un UUID univoco (session_token) e un device_id basato sul browser.
 * - Questi vengono scritti nella colonna `session_token` e `session_device_id` di `user_profiles`.
 * - Ad ogni accesso successivo, il token salvato viene confrontato con quello in memoria.
 * - Se non coincidono → significa che un altro dispositivo ha effettuato il login → l'utente corrente viene disconnesso.
 *
 * GESTIONE CASI LIMITE:
 * - Cambio PC legittimo: l'utente deve semplicemente fare logout da tutti i dispositivi e rientrare.
 * - Admin override: un admin può resettare il `session_token` di un utente dalla tabella user_profiles.
 */

import { useEffect, useRef, useCallback } from 'react';
import { userService } from '../services/api/userService';

// ─────────────────────────────────────────────
// 🔒 IMPOSTARE A TRUE PER ATTIVARE IL SESSION LOCK
const ENABLED = false;
// ─────────────────────────────────────────────

const CHECK_INTERVAL_MS = 30 * 1000; // Controlla ogni 30 secondi

/**
 * Genera un ID dispositivo stabile basato sul fingerprint del browser.
 * Non è infallibile ma copre il 90% dei casi reali.
 */
function getDeviceId() {
    let id = localStorage.getItem('gk_device_id');
    if (!id) {
        id = crypto.randomUUID();
        localStorage.setItem('gk_device_id', id);
    }
    return id;
}

/**
 * Hook principale. Da usare in ActivityDashboard o App root.
 * @param {string|null} userId - L'ID Supabase dell'utente corrente
 * @param {Function} onKicked - Callback chiamata se la sessione viene invalidata da un altro dispositivo
 */
export function useSessionLock(userId, onKicked) {
    const sessionTokenRef = useRef(null);
    const intervalRef = useRef(null);

    // Registra la sessione corrente nel DB
    const registerSession = useCallback(async () => {
        if (!ENABLED || !userId) return;

        const token = crypto.randomUUID();
        const deviceId = getDeviceId();
        sessionTokenRef.current = token;

        const { error } = await supabase
            .from('user_profiles')
            .update({
                session_token: token,
                session_device_id: deviceId,
                session_registered_at: new Date().toISOString()
            })
            .eq('user_id', userId);

        if (error) {
            console.warn('[SessionLock] Failed to register session:', error.message);
        } else {
            console.info('[SessionLock] Session registered for device:', deviceId);
        }
    }, [userId]);

    // Controlla periodicamente se la sessione è ancora valida
    const checkSession = useCallback(async () => {
        if (!ENABLED || !userId || !sessionTokenRef.current) return;

        const { data, error } = await supabase
            .from('user_profiles')
            .select('session_token')
            .eq('user_id', userId)
            .single();

        if (error) return;

        if (data?.session_token !== sessionTokenRef.current) {
            console.warn('[SessionLock] Session invalidated — another device logged in.');
            clearInterval(intervalRef.current);
            onKicked?.('Your account was accessed from another device. You have been signed out for security.');
        }
    }, [userId, onKicked]);

    useEffect(() => {
        if (!ENABLED || !userId) return;

        registerSession();

        intervalRef.current = setInterval(checkSession, CHECK_INTERVAL_MS);

        return () => clearInterval(intervalRef.current);
    }, [userId, registerSession, checkSession]);

    // Pulizia al logout: resetta il token nel DB
    const clearSession = useCallback(async () => {
        if (!ENABLED || !userId) return;
        await supabase
            .from('user_profiles')
            .update({ session_token: null, session_device_id: null })
            .eq('user_id', userId);
    }, [userId]);

    return { clearSession };
}

import { useState, useEffect, useCallback } from 'react';
import { authService } from '../services/api/authService';
import { userService } from '../services/api/userService';
import { can } from '../lib/permissions';

export function useUserProfile() {
    const [profile, setProfile] = useState(null);
    const [loading, setLoading] = useState(true);

    const loadProfile = useCallback(async () => {
        setLoading(true);
        const { data: { user } } = await authService.getUser();
        if (!user) {
            setProfile(null);
            setLoading(false);
            return;
        }

        try {
            const { data, error } = await supabase
                .from('user_profiles')
                .select('*, vessels(name, mmsi), companies(name, code)')
                .eq('id', user.id)
                .maybeSingle();

            if (data && !error) {
                const role = data.role || 'crew';
                setProfile({
                    id:           data.id,
                    email:        data.email,
                    displayName:  data.display_name,
                    role,
                    permissions:  can(role, data.custom_overrides || {}),
                    custom_overrides: data.custom_overrides || {},
                    vesselId:     data.vessel_id,
                    vesselName:   data.vessels?.name || null,
                    mmsi:         data.mmsi || data.vessels?.mmsi || null,
                    companyId:    data.company_id,
                    companyName:  data.companies?.name || null,
                    phoneNumber:  data.phone_number,
                    signatureTitle: data.signature_title,
                    isActive:     data.is_active,
                    isBlocked:    data.is_blocked || false,
                });
            } else {
                // Default Fallback
                setProfile({
                    id: user.id,
                    email: user.email,
                    displayName: user.email.split('@')[0],
                    role: 'crew',
                    permissions: can('crew'),
                    isActive: true,
                    isBlocked: false
                });
            }
        } catch (err) {
            console.error("Profile Load Error:", err);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        if (!profile?.id) return;
        const updateHeartbeat = async () => {
            await userService.updateLastSeen(profile.id);
        };
        updateHeartbeat();
        const interval = setInterval(updateHeartbeat, 60_000);
        return () => clearInterval(interval);
    }, [profile?.id]);

    useEffect(() => {
        loadProfile();
    }, [loadProfile]);

    return { 
        profile, 
        loading, 
        updateProfile: async (updates) => {
            const mapped = {};
            if (updates.displayName !== undefined) mapped.display_name = updates.displayName;
            if (updates.phoneNumber !== undefined) mapped.phone_number = updates.phoneNumber;
            if (updates.signatureTitle !== undefined) mapped.signature_title = updates.signatureTitle;
            if (updates.vesselId !== undefined) mapped.vessel_id = updates.vesselId;
            if (updates.companyId !== undefined) mapped.company_id = updates.companyId;
            if (updates.mmsi !== undefined) mapped.mmsi = updates.mmsi;
            if (updates.isActive !== undefined) mapped.is_active = updates.isActive;
            if (updates.isBlocked !== undefined) mapped.is_blocked = updates.isBlocked;
            if (updates.custom_overrides !== undefined) mapped.custom_overrides = updates.custom_overrides;

            const { error } = await userService.updateUserProfile(profile.id, mapped);
            if (!error) await loadProfile();
            return { error };
        }, 
        reloadProfile: loadProfile 
    };
}

﻿import { supabase } from '../../lib/supabase';

export const activityService = {
    async certifyMonthlySal(month, year) {
        const { data, error } = await supabase.rpc('certify_monthly_sal', { p_month: month, p_year: year });
        if (error) throw error;
        return data;
    },

    async createManualActivity(payload) {
        const newStart = new Date(payload.startTime);
        const newEnd = payload.endTime ? new Date(payload.endTime) : null;

        // 1. Fetch overlapping activities for this vessel
        let query = supabase
            .from('vessel_activity')
            .select('*')
            .eq('vessel_id', payload.vesselId);

        if (newEnd) {
            query = query.lt('start_time', newEnd.toISOString())
                         .or(`end_time.gt.${newStart.toISOString()},end_time.is.null`);
        } else {
            // Se la nuova attivitÃ  non ha una fine, si sovrappone a tutto ciÃ² che inizia dopo
            // o che la contiene.
            query = query.or(`start_time.gte.${newStart.toISOString()},and(start_time.lt.${newStart.toISOString()},or(end_time.gt.${newStart.toISOString()},end_time.is.null))`);
        }

        const { data: overlapping, error: fetchErr } = await query;
        if (fetchErr) throw new Error("Errore nel controllo overlap: " + fetchErr.message);

        const newGeo = payload.geofenceId || payload.geofenceFromId;

        if (overlapping && overlapping.length > 0) {
            for (let act of overlapping) {
                const actStart = new Date(act.start_time);
                const actEnd = act.end_time ? new Date(act.end_time) : null;

                const startsBefore = actStart < newStart;
                const endsAfter = newEnd && actEnd ? (actEnd > newEnd) : (!actEnd && newEnd !== null);

                // Caso C: Completamente inglobata (inizia >= newStart e finisce <= newEnd)
                const startsInside = actStart >= newStart;
                const endsInside = newEnd ? (actEnd && actEnd <= newEnd) : true;

                if (startsInside && endsInside) {
                    await supabase.from('vessel_activity').delete().eq('id', act.id);
                    continue;
                }

                // Caso D: Contiene completamente la nuova (Split Implicito)
                if (startsBefore && endsAfter) {
                    const firstLegGeoTo = (act.activity_type && act.activity_type.includes('Navigation')) ? newGeo : act.geofence_to_id;
                    const secondLegGeoFrom = (act.activity_type && act.activity_type.includes('Navigation')) ? (payload.geofenceId || payload.geofenceToId) : act.geofence_from_id;

                    await supabase.from('vessel_activity')
                        .update({ end_time: newStart.toISOString(), status: 'completed', geofence_to_id: firstLegGeoTo })
                        .eq('id', act.id);
                        
                    delete act.id; // prepare for insert
                    await supabase.from('vessel_activity')
                        .insert({
                            ...act,
                            geofence_from_id: secondLegGeoFrom,
                            start_time: newEnd.toISOString(),
                            status: act.end_time ? 'completed' : 'active',
                            source: 'manual'
                        });
                    continue;
                }

                // Caso A: Inizia prima, ma finisce "dentro" la nuova
                if (startsBefore && !endsAfter) {
                    const firstLegGeoTo = (act.activity_type && act.activity_type.includes('Navigation')) ? newGeo : act.geofence_to_id;
                    await supabase.from('vessel_activity')
                        .update({ end_time: newStart.toISOString(), status: 'completed', geofence_to_id: firstLegGeoTo })
                        .eq('id', act.id);
                }

                // Caso B: Inizia "dentro" la nuova, ma finisce dopo
                if (!startsBefore && endsAfter && newEnd) {
                    const secondLegGeoFrom = (act.activity_type && act.activity_type.includes('Navigation')) ? (payload.geofenceId || payload.geofenceToId) : act.geofence_from_id;
                    await supabase.from('vessel_activity')
                        .update({ start_time: newEnd.toISOString(), geofence_from_id: secondLegGeoFrom })
                        .eq('id', act.id);
                }
            }
        }

        // Finalmente, inseriamo la nuova attivitÃ  pulita
        const { data, error } = await supabase
            .from('vessel_activity')
            .insert({
                vessel_id: payload.vesselId,
                activity_type: payload.activityType,
                geofence_id: payload.geofenceId || null,
                geofence_from_id: payload.geofenceFromId || null,
                geofence_to_id: payload.geofenceToId || null,
                start_time: payload.startTime,
                end_time: payload.endTime || null,
                source: 'manual',
                status: payload.endTime ? 'completed' : 'active'
            })
            .select()
            .single();
            
        if (error) throw error;
        return data;
    },

    async createManualActivityAndSplit(payload, originalActivityId) {
        // 1. Fetch full details of the original activity to be split
        const { data: original, error: fetchErr } = await supabase
            .from('vessel_activity')
            .select('*')
            .eq('id', originalActivityId)
            .single();
        if (fetchErr) throw new Error("Could not find the overlapping activity to split: " + fetchErr.message);

        // 2. Step A: Update the first segment (original activity) to end at the new start time
        // If the original activity is a Navigation, update its destination to be the new geofence
        const firstLegGeoTo = (original.activity_type && original.activity_type.includes('Navigation'))
            ? (payload.geofenceId || payload.geofenceFromId)
            : original.geofence_to_id;

        const { error: updateErr } = await supabase
            .from('vessel_activity')
            .update({
                end_time: payload.startTime,
                status: 'completed',
                geofence_to_id: firstLegGeoTo
            })
            .eq('id', original.id);
        if (updateErr) throw new Error("Failed to update first segment: " + updateErr.message);

        // 3. Step B: Insert the new manual activity
        const { data: insertedNew, error: insertNewErr } = await supabase
            .from('vessel_activity')
            .insert({
                vessel_id: payload.vesselId,
                activity_type: payload.activityType,
                geofence_id: payload.geofenceId || null,
                geofence_from_id: payload.geofenceFromId || null,
                geofence_to_id: payload.geofenceToId || null,
                start_time: payload.startTime,
                end_time: payload.endTime || null,
                source: 'manual',
                status: 'completed'
            })
            .select()
            .single();
        if (insertNewErr) {
            // Attempt to restore first segment
            await supabase
                .from('vessel_activity')
                .update({ 
                    end_time: original.end_time, 
                    status: original.status,
                    geofence_to_id: original.geofence_to_id
                })
                .eq('id', original.id);
            throw new Error("Failed to insert new activity: " + insertNewErr.message);
        }

        // 4. Step C: Insert the second segment (starts at new ATD, ends at original ATD)
        // If the original activity is a Navigation, update its origin to be the new geofence
        const secondLegGeoFrom = (original.activity_type && original.activity_type.includes('Navigation'))
            ? (payload.geofenceId || payload.geofenceToId)
            : original.geofence_from_id;

        const { error: insertSecondErr } = await supabase
            .from('vessel_activity')
            .insert({
                vessel_id: original.vessel_id,
                activity_type: original.activity_type,
                geofence_id: original.geofence_id,
                geofence_from_id: secondLegGeoFrom,
                geofence_to_id: original.geofence_to_id,
                start_time: payload.endTime, // Starts where the new one ends
                end_time: original.end_time, // Could be null (in progress)
                source: original.source,
                status: original.end_time ? 'completed' : 'active',
                weather_wind: original.weather_wind,
                weather_wave: original.weather_wave,
                probable_weather_standby: original.probable_weather_standby
            });
        if (insertSecondErr) {
            // Rollback first segment and delete the inserted new activity
            await supabase
                .from('vessel_activity')
                .update({ 
                    end_time: original.end_time, 
                    status: original.status,
                    geofence_to_id: original.geofence_to_id
                })
                .eq('id', original.id);
            await supabase
                .from('vessel_activity')
                .delete()
                .eq('id', insertedNew.id);
            throw new Error("Failed to insert split segment: " + insertSecondErr.message);
        }

        return insertedNew;
    },

    async deleteActivity(activityId) {
        // First delete any logbook entries associated with this activity (since they don't cascade automatically)
        const { error: logbookErr } = await supabase
            .from('logbook_entries')
            .delete()
            .eq('vessel_activity_id', activityId);
        if (logbookErr) throw logbookErr;

        // Now delete the activity itself
        const { data, error } = await supabase
            .from('vessel_activity')
            .delete()
            .eq('id', activityId)
            .select();
        if (error) throw error;
        return data;
    },

    async updateActivity(id, updates) {
        const { data, error } = await supabase
            .from('vessel_activity')
            .update(updates)
            .eq('id', id)
            .select()
            .single();
        if (error) throw error;
        return data;
    },

        async fetchActivityLog(vesselId) {
        let query = supabase
            .from('vessel_activity')
            .select(`n                id, vessel_id, activity_type, geofence_id, start_time, end_time, duration_minutes, source, status, export_flag,
                vessels ( name, mmsi ),
                geofences!vessel_activity_geofence_id_fkey ( name, nature ),
                logbook_entries ( status, structured_fields ),
                activity_messages ( id, is_read, sender_role )
            `)
            .order('start_time', { ascending: false });
        if (vesselId) { query = query.eq('vessel_id', vesselId); }
        return await query;
    },
    async fetchActivitiesRange(vesselId, startDate, endDate) {
        let query = supabase
            .from('vessel_activity')
            .select(`
                id, vessel_id, start_time, end_time, activity_type,
                geofence_from_id, geofence_to_id,
                geofence_from:geofences!vessel_activity_geofence_from_id_fkey(name),
                geofence_to:geofences!vessel_activity_geofence_to_id_fkey(name)
            `)
            .or(`vessel_id.eq.${vesselId},vessel_id.is.null`)
            .gte('start_time', `${startDate}T00:00:00Z`)
            .lte('start_time', `${endDate}T23:59:59Z`)
            .order('start_time', { ascending: true });

        const { data, error } = await query;
        if (error) throw error;
        return data;
    },
    async fetchActivityTypes() {
        return await supabase.from('activities').select('*');
    },
    async insertActivityType(item) {
        return await supabase.from('activities').insert(item).select().single();
    },
    async updateActivityType(id, updates) {
        return await supabase.from('activities').update(updates).eq('id', id).select().single();
    },
    async deleteActivityType(id) {
        return await supabase.from('activities').delete().eq('id', id);
    }
};

import { supabase } from '../../lib/supabase.js';

const GEMINI_API_KEY = import.meta.env.VITE_GEMINI_API_KEY;

/**
 * Genera il vettore semantico 768d omogeneo (all-mpnet-base-v2) tramite VPS Contabo
 * garantendo la massima similitudine con i messaggi vettorializzati su Supabase.
