async function generateQueryEmbedding(text, retries = 3, delay = 1500) {
  const vpsUrl = 'https://169-58-101-199.sslip.io/embed';
  
  try {
    const res = await fetch(vpsUrl, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        'x-api-key': 'geokanban-secret-key-2026'
      },
      body: JSON.stringify({ text })
    });

    if (res.ok) {
      const data = await res.json();
      if (data?.embedding) {
        return data.embedding;
      }
    }
  } catch (err) {
    console.warn("⚠️ VPS Embedding microservice offline/booting, fallback su Gemini:", err.message);
  }

  // Fallback temporaneo Gemini se il microservizio VPS non è ancora avviato
  const apiKey = GEMINI_API_KEY || import.meta.env.VITE_GEMINI_API_KEY;
  if (!apiKey) return null;
  
  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-embedding-001:embedContent?key=${apiKey}`;
  
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          content: { parts: [{ text }] },
          outputDimensionality: 768
        })
      });
      if (res.ok) {
        const data = await res.json();
        return data?.embedding?.values || null;
      }
    } catch (e) {
      console.error("Errore fallback Gemini embedding:", e);
    }
  }
  return null;
}

/**
 * BARRIERA DI PRIVACY LIVESTELLAR 1: Sanitizer Deterministico
 * Elimina mittenti, contatti e nomi propri prima che qualsiasi messaggio entri nel contesto dell'IA.
 */
function sanitizeMessageForPrivacy(messageText) {
  if (!messageText) return "";
  return messageText
    .replace(/(?:\+39\s?)?3\d{2}[\s.-]?\d{6,7}/g, "[NUMERO OMESSO]")
    .replace(/Il tuo codice di sicurezza con .* è cambiato\./g, "")
    .trim();
}

/**
 * Estrae una data o un intervallo di date dalla domanda dell'utente (es. "dal 2 luglio duemila ventisei", "02/07", "25 luglio")
 */
function extractDateFilterFromQuestion(question) {
  const monthsMap = {
    'gennaio': 1, 'febbraio': 2, 'marzo': 3, 'aprile': 4, 'maggio': 5, 'giugno': 6,
    'luglio': 7, 'agosto': 8, 'settembre': 9, 'ottobre': 10, 'novembre': 11, 'dicembre': 12
  };
  
  let lower = question.toLowerCase();
  
  // Normalizza anni espressi a parole (es. speech-to-text "duemila ventisei")
  lower = lower
    .replace(/duemila\s*ventisei/gi, "2026")
    .replace(/duemila\s*venticinque/gi, "2025")
    .replace(/duemila\s*ventiquattro/gi, "2024")
    .replace(/duemila\s*ventitre/gi, "2023");

  // Rileva se si tratta di un intervallo che parte da una data (es. "dal 2 luglio...")
  const isFromRange = lower.includes("dal ") || lower.includes("da ");

  // Match "2 luglio", "02 luglio", "25 luglio 2026", ecc.
  const regexNamed = /(\d{1,2})\s+(gennaio|febbraio|marzo|aprile|maggio|giugno|luglio|agosto|settembre|ottobre|novembre|dicembre)(?:\s+(\d{4}))?/i;
  const matchNamed = lower.match(regexNamed);
  
  if (matchNamed) {
    const day = parseInt(matchNamed[1], 10);
    const month = monthsMap[matchNamed[2]];
    const year = matchNamed[3] ? parseInt(matchNamed[3], 10) : 2026;
    
    const startDate = new Date(Date.UTC(year, month - 1, day, 0, 0, 0)).toISOString();
    // Se la domanda dice "DAL 2 LUGLIO...", l'intervallo copre dal 2 Luglio fino ad OGGI!
    const endDate = isFromRange 
      ? new Date().toISOString() 
      : new Date(Date.UTC(year, month - 1, day, 23, 59, 59)).toISOString();

    return { startDate, endDate, dateText: `${day} ${matchNamed[2]} ${year}` };
  }

  // Match "02/07", "2/7", "02/07/2026", ecc.
  const regexNum = /(\d{1,2})[/-](\d{1,2})(?:[/-](\d{4}))?/;
  const matchNum = lower.match(regexNum);
  if (matchNum) {
    const day = parseInt(matchNum[1], 10);
    const month = parseInt(matchNum[2], 10);
    const year = matchNum[3] ? parseInt(matchNum[3], 10) : 2026;

    const startDate = new Date(Date.UTC(year, month - 1, day, 0, 0, 0)).toISOString();
    const endDate = isFromRange 
      ? new Date().toISOString() 
      : new Date(Date.UTC(year, month - 1, day, 23, 59, 59)).toISOString();

    return { startDate, endDate, dateText: `${day}/${month}/${year}` };
  }

  return null;
}

/**
 * Esegue la ricerca semantica RAG + Live DB per alimentare il Copilot
 */
export async function askDigitalTwinCopilot(question, selectedVesselFilter = 'All') {
  try {
    const dateFilter = extractDateFilterFromQuestion(question);

    // 1. Embedding della domanda
    const queryVector = await generateQueryEmbedding(question);

    // 2. Retrieval Semantico IBRIDO Vettoriale + FTS su whatsapp_messages
    let waMessages = [];
    if (queryVector) {
      const { data: rpcData, error: rpcErr } = await supabase.rpc('match_whatsapp_messages_hybrid', {
        query_embedding: queryVector,
        search_query: question,
        match_threshold: 0.2,
        match_count: 20
      });
      if (!rpcErr && rpcData) {
        waMessages = rpcData;
      }
    }

    // Se l'utente ha chiesto una data specifica, recupera anche i messaggi WhatsApp di quella data
    if (dateFilter) {
      const { data: dateWa } = await supabase
        .from('whatsapp_messages')
        .select('group_name, message_text, timestamp')
        .gte('timestamp', dateFilter.startDate)
        .lte('timestamp', dateFilter.endDate)
        .limit(20);

      if (dateWa && dateWa.length > 0) {
        const existingIds = new Set(waMessages.map(m => m.id));
        for (const dw of dateWa) {
          if (!existingIds.has(dw.id)) waMessages.push(dw);
        }
      }
    }

    // Fallback SQL standard se nessun messaggio estratto
    if (!waMessages || waMessages.length === 0) {
      const { data: fallbackData } = await supabase
        .from('whatsapp_messages')
        .select('group_name, message_text, timestamp')
        .order('timestamp', { ascending: false })
        .limit(15);
      waMessages = fallbackData || [];
    }

    // Anonimizzazione assoluta
    const waContext = waMessages.map(m => {
      const cleanText = sanitizeMessageForPrivacy(m.message_text);
      return `[Comunicazione Operativa - ${m.timestamp?.substring(0, 10)}] ${cleanText}`;
    }).join('\n');

    // 3. Retrieval Dati Live DB (Attività & Logbook)
    let actQuery = supabase
      .from('vessel_activity')
      .select(`
        id, activity_type, start_time, end_time, status, ais_start_draught, ais_end_draught,
        vessels ( name ),
        geofences!vessel_activity_geofence_id_fkey ( name ),
        logbook_entries ( narrative_text, structured_fields )
      `);

    // Se la domanda menziona una data esplicita, filtra per quella data!
    if (dateFilter) {
      actQuery = actQuery
        .gte('start_time', dateFilter.startDate)
        .lte('start_time', dateFilter.endDate)
        .order('start_time', { ascending: true })
        .limit(50);
    } else {
      actQuery = actQuery
        .order('start_time', { ascending: false })
        .limit(30);
    }

    const { data: recentActivities } = await actQuery;

    // Riorganizza per mettere PRIMA tutte le attività In Progress
    const sortedActivities = (recentActivities || []).sort((a, b) => {
      if (!a.end_time && b.end_time) return -1;
      if (a.end_time && !b.end_time) return 1;
      return new Date(b.start_time) - new Date(a.start_time);
    });

    const liveContext = sortedActivities.map(a => {
      const log = a.logbook_entries?.[0];
      const sf = log?.structured_fields || {};
      const statusText = !a.end_time ? 'IN PROGRESS (In corso)' : 'CONCLUSA';
      return `[Attività NAVE: ${a.vessels?.name || 'N/A'} | Stato Operazione: ${statusText} | Tipo: ${a.activity_type} @ ${a.geofences?.name || '—'}]
  - Orario: ATA ${a.start_time ? new Date(a.start_time).toLocaleString('it-IT') : '—'} | ATD ${a.end_time ? new Date(a.end_time).toLocaleString('it-IT') : 'In corso'}
  - Pescaggio AIS: In ${a.ais_start_draught || '—'}m / Out ${a.ais_end_draught || '—'}m
  - Tonnellaggio Carico Logbook: ${sf.actual_cargo_tonnes || 0} t | Bunker: ${sf.actual_bunker_tonnes || 0} t
  - Note Operative: ${log?.narrative_text || 'Nessuna nota'}`;
    }).join('\n\n');

    // 4. BARRIERA DI PRIVACY & PERSONA TECNICO MARITTIMO SENIOR
    const systemPrompt = `Sei GeoKanban Digital Twin Copilot, il SENIOR MARITIME OPERATIONS & FLEET ENGINEER del cantiere navale e della Diga di Genova.
La tua conoscenza copre il gergo marittimo ed operazionale di cantiere:
- "Draught" / "Immersione" / "Pescaggio": l'altezza dell'opera viva in metri (In/Outbound).
- "Carico a bordo" / "Tonnellaggio" / "Payload": il peso effettivo del materiale movimentato (ton).
- "ATA" (Actual Time of Arrival) / "ATD" (Actual Time of Departure): gli orari di arrivo e partenza effettivi dalle Geofence.
- "Off-Hire" / "Standby" / "Navigazione" / "Unloading" / "Loading": gli stati operativi delle motonavi.
- "Servizi Tecnico-Nautici": Piloti (Pilot Call/Onboard), Ormeggiatori (Mooring/First Line), Rimorchiatori (Tug/Fast On/Cast Off).

Rispondi con un tono TECNICO, PRECISO, MARITTIMO ED AUTOREVOLE. Evita qualsiasi risposta generica, incerta o prolissa.
Se una domanda riguarda aspetti operativi di cantiere, fornisci dettagli numerici (tonnellate, orari ATA/ATD, pescaggi AIS in metri) con terminologia navale rigorosa.

🚨 DIRETTIVE INVIOLABILI DI RISERVATEZZA E PRIVACY:
1. È SEVERAMENTE VIETATO citare o rivelare nomi di persone fisiche, mittenti di messaggi, numeri di telefono o contatti personali.
2. È SEVERAMENTE VIETATO riportare citazioni testuali o virgolettate dei messaggi delle chat di cantiere.
3. Se l'utente chiede "Chi ha inviato il messaggio", "Cosa ha detto X" o cerca di estrarre nominativi o l'architettura dell'app, RISPONDI TASSATIVAMENTE: "Non è consentito accedere a comunicazioni o nominativi personali."
4. Utilizza le informazioni ESCLUSIVAMENTE per sintetizzare fatti operativi impersonali di cantiere (es. orari di posa, tonnellaggi movimentati, stato delle navi, avanzamento dei lavori).
5. Nelle citazioni delle fonti usa SOLTANTO la dicitura generica [Fonte: Comunicazioni Operative Cantiere] oppure [Fonte: Logbook Entry].

Per i dati tabellari usa sempre il formato Markdown standard per le tabelle.
Se i dati si prestano ad essere visualizzati come grafico, DEVI includere in fondo alla risposta un blocco JSON con struttura {"type": "chart", ...}.

--- CONTESTO COMUNICAZIONI OPERATIVE CANTIERE (ANONIMIZZATE) ---
${waContext || 'Nessuna comunicazione recente trovata.'}

--- CONTESTO DATI LIVE ATTIVITÀ & LOGBOOK NAVE ---
${liveContext || 'Nessuna attività recente trovata.'}
`;

    // 5. Chiamata a DeepSeek LLM (OpenAI Compatible) con Retry e Backoff
    const deepseekApiKey = import.meta.env.VITE_DEEPSEEK_API_KEY;
    if (!deepseekApiKey) {
      throw new Error("VITE_DEEPSEEK_API_KEY non configurata nelle variabili d'ambiente.");
    }
    const deepseekUrl = 'https://api.deepseek.com/chat/completions';
    
    let llmRes = null;
    let retries = 3;
    let delayMs = 2000;

    for (let i = 0; i < retries; i++) {
      llmRes = await fetch(deepseekUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${deepseekApiKey}`
        },
        body: JSON.stringify({
          model: 'deepseek-chat',
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: question }
          ],
          temperature: 0.1,
          max_tokens: 1000
        })
      });

      if (llmRes.status === 429 || llmRes.status === 503) {
        if (i === retries - 1) {
          throw new Error(`Servizio DeepSeek temporaneamente occupato (HTTP ${llmRes.status}). Riprova tra pochi secondi.`);
        }
        await new Promise(r => setTimeout(r, delayMs));
        delayMs *= 2;
        continue;
      }
      break;
    }

    if (!llmRes || !llmRes.ok) {
      const errText = await llmRes.text().catch(() => '');
      throw new Error(`Errore DeepSeek LLM: ${llmRes?.status || 'Unknown'} - ${errText}`);
    }

    const llmData = await llmRes.json();
    let answerText = llmData?.choices?.[0]?.message?.content || "Impossibile elaborare una risposta.";

    // 6. BARRIERA DI PRIVACY LIVESTELLAR 3: Post-Processing Output Guard
    answerText = answerText
      .replace(/WhatsApp/gi, "Comunicazioni Operative")
      .replace(/Messaggio da parte di [^:\n]+/gi, "Comunicazione Operativa");

    const sources = [];
    if (waMessages && waMessages.length > 0) sources.push(`Comunicazioni Operative Cantiere (${waMessages.length} record)`);
    if (recentActivities && recentActivities.length > 0) sources.push(`Live Activities (${recentActivities.length} record)`);

    return {
      answer: answerText,
      sources: [...new Set(sources)]
    };

  } catch (err) {
    console.error("❌ Errore copilotService:", err);
    return {
      answer: `Si è verificato un errore durante l'elaborazione della domanda: ${err.message}. Verifica la connessione o riprova.`,
      sources: []
    };
  }
}

/**
 * Carica la cronologia salvata per l'utente corrente isolata da DB o LocalStorage fallback
 */
export async function fetchCopilotChatHistory(username = 'guest', tenantId = 'default') {
  try {
    const { data, error } = await supabase
      .from('copilot_chat_history')
      .select('id, role, content, sources, created_at')
      .eq('username', username)
      .eq('tenant_id', tenantId)
      .order('created_at', { ascending: true })
      .limit(50);

    if (error) {
      console.warn("📌 Database copilot_chat_history non ancora migrato, uso LocalStorage fallback:", error.message);
      const localKey = `copilot_chat_history_${tenantId}_${username}`;
      const saved = localStorage.getItem(localKey);
      return saved ? JSON.parse(saved) : [];
    }

    return (data || []).map(item => ({
      id: item.id,
      text: item.content,
      sender: item.role === 'user' ? 'user' : 'bot',
      timestamp: new Date(item.created_at).toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' }),
      sources: item.sources || []
    }));
  } catch (err) {
    console.warn("Fallback LocalStorage per fetchCopilotChatHistory:", err);
    const localKey = `copilot_chat_history_${tenantId}_${username}`;
    const saved = localStorage.getItem(localKey);
    return saved ? JSON.parse(saved) : [];
  }
}

/**
 * Salva un messaggio (utente o assistant) nella cronologia isolata
 */
export async function saveCopilotChatMessage(username = 'guest', tenantId = 'default', role = 'user', content = '', sources = []) {
  try {
    const { error } = await supabase
      .from('copilot_chat_history')
      .insert({
        username,
        tenant_id: tenantId,
        role,
        content,
        sources
      });

    // Salva sempre anche nel LocalStorage per garanzia di sincronia istantanea UI
    const localKey = `copilot_chat_history_${tenantId}_${username}`;
    const currentLocal = JSON.parse(localStorage.getItem(localKey) || '[]');
    currentLocal.push({
      id: Date.now().toString(),
      text: content,
      sender: role === 'user' ? 'user' : 'bot',
      timestamp: new Date().toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' }),
      sources
    });
    localStorage.setItem(localKey, JSON.stringify(currentLocal.slice(-50)));

    if (error) console.warn("Supabase insert error copilot_chat_history (uso LocalStorage):", error.message);
  } catch (err) {
    console.warn("Save Copilot msg LocalStorage fallback:", err);
  }
}

/**
 * Pulisce la cronologia dell'utente (Pulsante "Nuova Chat")
 */
export async function clearCopilotChatHistory(username = 'guest', tenantId = 'default') {
  try {
    await supabase
      .from('copilot_chat_history')
      .delete()
      .eq('username', username)
      .eq('tenant_id', tenantId);

    const localKey = `copilot_chat_history_${tenantId}_${username}`;
    localStorage.removeItem(localKey);
  } catch (err) {
    console.warn("Clear Copilot chat error:", err);
  }
}

import { create } from 'zustand';
import { supabase } from '../lib/supabase';
import { weatherService } from '../services/api/weatherService';
import { useGeofenceStore } from './useGeofenceStore';

export const useActivityStore = create((set, get) => ({
    activities: [],
    productionPlans: [],
    selectedMonth: new Date().getMonth(),
    selectedYear: new Date().getFullYear(),
    loading: false,
    error: null,
    lastUpdate: null,
    
    setSelectedMonth: (month) => set({ selectedMonth: month }),
    setSelectedYear: (year) => set({ selectedYear: year }),

    fetchActivities: async (vesselId = null, userRole = null, month = null, year = null) => {
        set({ loading: true });
        const targetMonth = month !== null ? month : get().selectedMonth;
        const targetYear = year !== null ? year : get().selectedYear;

        try {
            // Fetch all weather logs for the selected month to map in memory
            let weatherLogsInMemory = [];
            try {
                const startDate = new Date(targetYear, targetMonth, 1).toISOString();
                const endDate = new Date(targetYear, targetMonth + 1, 0, 23, 59, 59, 999).toISOString();
                const { data, error } = await supabase
                    .from('weather_logs')
                    .select('location_name, timestamp, wind_speed, wave_height')
                    .gte('timestamp', startDate)
                    .lte('timestamp', endDate);
                if (!error && data) weatherLogsInMemory = data;
            } catch (err) {
                console.error("Error fetching historical weather logs:", err);
            }
            let query = supabase
                .from('vessel_activity')
                .select(`
                    id, vessel_id, activity_type, geofence_id, geofence_from_id, geofence_to_id, start_time, end_time,
                    duration_minutes, source, status, export_flag, ais_start_draught, ais_end_draught,
                    weather_wave, weather_wind,
                    vessels ( name, mmsi ),
                    geofences!vessel_activity_geofence_id_fkey ( name, nature ),
                    logbook_entries ( * ),
                    activity_messages ( id, is_read, sender_role, message_text, created_at, sender_id )
                `)
                .order('start_time', { ascending: false });
            
            if (vesselId) {
                if (Array.isArray(vesselId)) {
                    query = query.or(`vessel_id.in.(${vesselId.join(',')}),vessel_id.is.null`);
                } else {
                    query = query.or(`vessel_id.eq.${vesselId},vessel_id.is.null`);
                }
            }

            if (targetMonth !== null && targetYear !== null) {
                const startDate = new Date(targetYear, targetMonth, 1).toISOString();
                // Get last day of month correctly
                const endDate = new Date(targetYear, targetMonth + 1, 0, 23, 59, 59, 999).toISOString();
                query = query.gte('start_time', startDate).lte('start_time', endDate);
            } else {
                query = query.limit(500);
            }

            let { data, error } = await query;
            
            if (error) throw error;

            // Batch enrichment: Fetch tracking coordinates for Anchorage activities without a geofence
            const anchorageRows = (data || []).filter(r => r.activity_type === 'Anchorage' && !r.geofence_id);
            const anchorageCoordsMap = new Map();
            if (anchorageRows.length > 0) {
                const vesselIds = [...new Set(anchorageRows.map(r => r.vessel_id).filter(Boolean))];
                const timestamps = anchorageRows.map(r => new Date(r.start_time).getTime());
                const minStart = new Date(Math.min(...timestamps) - 30 * 60 * 1000).toISOString();
                const maxEnd = new Date(Math.max(...timestamps) + 30 * 60 * 1000).toISOString();
                
                try {
                    const { data: trackPoints } = await supabase
                        .from('vessel_tracking')
                        .select('vessel_id, lat, lon, timestamp')
                        .in('vessel_id', vesselIds)
                        .gte('timestamp', minStart)
                        .lte('timestamp', maxEnd)
                        .order('timestamp', { ascending: true });
                        
                    if (trackPoints && trackPoints.length > 0) {
                        anchorageRows.forEach(act => {
                            const actStart = new Date(act.start_time).getTime();
                            let closest = null;
                            let minDiff = Infinity;
                            trackPoints.forEach(tp => {
                                if (tp.vessel_id === act.vessel_id) {
                                    const diff = Math.abs(new Date(tp.timestamp).getTime() - actStart);
                                    if (diff < minDiff) {
                                        minDiff = diff;
                                        closest = tp;
                                    }
                                }
                            });
                            if (closest && minDiff <= 2 * 60 * 60 * 1000) {
                                anchorageCoordsMap.set(act.id, { lat: closest.lat, lon: closest.lon });
                            }
                        });
                    }
                } catch (tErr) {
                    console.error("Error fetching tracking points for Anchorage:", tErr);
                }
            }

            const geoStore = useGeofenceStore.getState().geofences || [];

            function formatWGS84(lat, lon) {
                if (lat == null || lon == null) return null;
                const latCard = lat >= 0 ? 'N' : 'S';
                const lonCard = lon >= 0 ? 'E' : 'W';
                const absLat = Math.abs(lat);
                const latDeg = Math.floor(absLat);
                const latMin = Math.floor((absLat - latDeg) * 60);
                const latSec = ((absLat - latDeg - latMin / 60) * 3600).toFixed(1);
                const absLon = Math.abs(lon);
                const lonDeg = Math.floor(absLon);
                const lonMin = Math.floor((absLon - lonDeg) * 60);
                const lonSec = ((absLon - lonDeg - lonMin / 60) * 3600).toFixed(1);
                return `${latDeg}°${latMin.toString().padStart(2, '0')}'${latSec.padStart(4, '0')}"${latCard}, ${lonDeg}°${lonMin.toString().padStart(2, '0')}'${lonSec.padStart(4, '0')}"${lonCard}`;
            }

            const getAnchorageLabel = (r) => {
                const coords = anchorageCoordsMap.get(r.id);
                const wgs = coords ? formatWGS84(coords.lat, coords.lon) : null;
                return wgs ? `Anchorage (${wgs})` : 'Anchorage (Rada)';
            };

            // Filter out 0-minute ghost activities and map to flat format
            const validData = (data || []).filter(row => !(row.status === 'completed' && row.duration_minutes === 0));
            const mapped = validData.map((row, idx, arr) => {
                const showWeather = row.activity_type === 'Navigation';
                let geofenceName = row.geofences?.name || (row.activity_type === 'Anchorage' ? getAnchorageLabel(row) : '—');

                if (row.activity_type === 'Navigation') {
                    let destGeo = row.geofence_to_id ? geoStore.find(g => g.id === row.geofence_to_id)?.name : null;
                    let origGeo = row.geofence_from_id ? geoStore.find(g => g.id === row.geofence_from_id)?.name : null;

                    // Fallback legacy (scansione array) se i nuovi ID non sono usati/disponibili
                    if (!destGeo) {
                        for (let i = idx - 1; i >= 0; i--) {
                            if (arr[i].vessel_id === row.vessel_id) {
                                if (arr[i].geofences?.name) {
                                    destGeo = arr[i].geofences.name;
                                } else if (arr[i].activity_type === 'Anchorage') {
                                    destGeo = `Anchorage (#${i + 1})`;
                                }
                                if (destGeo) break;
                            }
                        }
                    }
                    if (!origGeo) {
                        for (let i = idx + 1; i < arr.length; i++) {
                            if (arr[i].vessel_id === row.vessel_id) {
                                if (arr[i].geofences?.name) {
                                    origGeo = arr[i].geofences.name;
                                } else if (arr[i].activity_type === 'Anchorage') {
                                    origGeo = `Anchorage (#${i + 1})`;
                                }
                                if (origGeo) break;
                            }
                        }
                    }

                    if (origGeo && destGeo) {
                        geofenceName = `${origGeo} ➔ ${destGeo}`;
                    } else if (destGeo) {
                        geofenceName = `➔ ${destGeo}`;
                    } else if (origGeo) {
                        geofenceName = `${origGeo} ➔ —`;
                    } else {
                        geofenceName = row.activity_type;
                    }
                }

                // Calcola il timestamp target in base alla logica dell'utente:
                // - Se finita: momento mediano tra inizio e fine (ingresso e uscita).
                // - Se in corso (in-progress): orario di inizio attività (ingresso).
                const tStart = new Date(row.start_time).getTime();
                const tEnd = row.end_time ? new Date(row.end_time).getTime() : null;
                const targetTime = tEnd ? (tStart + tEnd) / 2 : tStart;
                const isFleetEvent = !row.vessel_id;
                const vesselName = isFleetEvent ? '⚠️ All Vessels' : (row.vessels?.name || '');

                let activityWeather = null;
                if (row.activity_type === 'Navigation' && weatherLogsInMemory && weatherLogsInMemory.length > 0) {
                    let minDiff = Infinity;
                    weatherLogsInMemory.forEach(log => {
                        // Cerca rilevazioni specifiche per questa nave
                        if (log.location_name && log.location_name.includes(vesselName)) {
                            const diff = Math.abs(new Date(log.timestamp).getTime() - targetTime);
                            if (diff < minDiff) {
                                minDiff = diff;
                                activityWeather = log;
                            }
                        }
                    });
                }


                // Visualizziamo il meteo solo per attività di Navigation


                return {
                    id: row.id,
                    vessel: isFleetEvent ? '⚠️ All Vessels' : (row.vessels?.name || 'Unknown'),
                    vesselId: row.vessel_id,
                    mmsi: row.vessels?.mmsi,
                    isFleetEvent,
                    activity: row.activity_type,
                    geofence: geofenceName,
                    geofenceId: row.geofence_id,
                    geofenceFromId: row.geofence_from_id,
                    geofenceToId: row.geofence_to_id,
                    startTime: row.start_time,
                    endTime: row.end_time,
                    durationMinutes: row.duration_minutes,
                    source: row.source || 'ais',
                    status: row.status === 'active' ? 'in-progress' : 'completed',
                    aisStartDraught: row.ais_start_draught ? `${row.ais_start_draught} m` : '—',
                    aisEndDraught: row.ais_end_draught ? `${row.ais_end_draught} m` : '—',
                    logbookStatus: row.logbook_entries?.[0]?.status || 'none',
                    logbookEntry: row.logbook_entries?.[0] || null,
                    weatherWave: showWeather
                        ? (row.weather_wave && row.weather_wave !== '—' 
                            ? (row.weather_wave.includes('m') ? row.weather_wave : `${row.weather_wave} m`) 
                            : (activityWeather ? `${activityWeather.wave_height} m` : '—'))
                        : '—',
                    weatherWind: showWeather
                        ? (row.weather_wind && row.weather_wind !== '—' 
                            ? (row.weather_wind.includes('kn') ? row.weather_wind : `${row.weather_wind} kn`) 
                            : (activityWeather ? `${activityWeather.wind_speed} kn` : '—'))
                        : '—',
                    submittedAt: row.logbook_entries?.[0]?.created_at || null,
                    deliveredQty: row.logbook_entries?.[0]?.structured_fields?.actual_cargo_tonnes || null,
                    msgCount: row.activity_messages?.filter(m => !m.is_read && m.sender_role !== userRole).length || 0,
                    unreadMsgCount: row.activity_messages?.filter(m => !m.is_read && m.sender_role !== userRole).length || 0,
                    totalMsgCount: row.activity_messages?.length || 0,
                    messages: row.activity_messages || [],
                    allMessagesText: (row.activity_messages || [])
                        .sort((a, b) => new Date(a.created_at) - new Date(b.created_at))
                        .map(m => {
                            const date = new Date(m.created_at).toISOString().replace('T', ' ').substring(0, 16);
                            return `[${date}] [${(m.sender_role || 'System').toUpperCase()}] ${m.message_text || ''}`;
                        })
                        .join(' | ') || '—'
                };
            });

            set({ 
                activities: mapped, 
                lastUpdate: new Date() 
            });
        } catch (err) {
            set({ error: err.message });
        } finally {
            set({ loading: false });
        }
    },



    fetchPlans: async () => {
        try {
            const { data, error } = await supabase.from('production_plans').select('*');
            if (error) throw error;
            set({ productionPlans: data || [] });
        } catch (err) {
            console.error(err);
        }
    },

    upsertPlan: async (plan) => {
        try {
            const { error } = await supabase.from('production_plans').upsert(plan);
            if (error) throw error;
            get().fetchPlans();
            return { success: true };
        } catch (err) {
            return { success: false, error: err.message };
        }
    },

    deletePlan: async (id) => {
        try {
            const { error } = await supabase.from('production_plans').delete().eq('id', id);
            if (error) throw error;
            get().fetchPlans();
            return { success: true };
        } catch (err) {
            return { success: false, error: err.message };
        }
    }
}));

import { create } from 'zustand';
import { supabase } from '../lib/supabase';

export const useProjectStore = create((set, get) => ({
    projects: [],
    currentProject: null,
    loading: false,
    error: null,

    fetchProjects: async (userId, role) => {
        set({ loading: true });
        try {
            const { data, error } = await supabase
                .from('projects')
                .select('id, name, location, customer_name, color_hex, is_active')
                .eq('is_active', true);

            if (error) throw error;

            // --- SINGLE PROJECT ENFORCEMENT ---
            // Forziamo Genova come unico cantiere operativo
            const genovaDefault = {
                id: 'diga-genova-default',
                name: 'DIGA FORANEA GENOVA',
                location: 'GENOVA, IT',
                color_hex: '#10b981',
                is_active: true
            };

            const projects = data?.length > 0 ? data : [genovaDefault];
            const currentProject = projects.find(p => p.name.includes('GENOVA')) || projects[0];

            set({ projects, currentProject });
            return projects;
        } catch (err) {
            set({ error: err.message });
        } finally {
            set({ loading: false });
        }
    },

    setCurrentProject: async (project) => {
        set({ currentProject: project });
    },

    initCurrentProject: (projectId, projectsList) => {
        const list = projectsList || get().projects;
        const found = list.find(p => p.id === projectId);
        if (found) {
            set({ currentProject: found });
        } else if (list.length > 0) {
            set({ currentProject: list[0] });
        }
    },

    createProject: async (projectData) => {
        set({ loading: true, error: null });
        try {
            const { data, error } = await supabase
                .from('projects')
                .insert([projectData])
                .select();

            if (error) throw error;
            set(state => ({ projects: [...state.projects, data[0]] }));
            return { success: true, data: data[0] };
        } catch (err) {
            set({ error: err.message });
            return { success: false, error: err.message };
        } finally {
            set({ loading: false });
        }
    },

    updateProject: async (projectId, updates) => {
        set({ loading: true, error: null });
        try {
            const { data, error } = await supabase
                .from('projects')
                .update(updates)
                .eq('id', projectId)
                .select();

            if (error) throw error;
            set(state => ({
                projects: state.projects.map(p => p.id === projectId ? data[0] : p),
                currentProject: state.currentProject?.id === projectId ? data[0] : state.currentProject
            }));
            return { success: true, data: data[0] };
        } catch (err) {
            set({ error: err.message });
            return { success: false, error: err.message };
        } finally {
            set({ loading: false });
        }
    },

    deleteProject: async (projectId) => {
        set({ loading: true, error: null });
        try {
            const { error } = await supabase
                .from('projects')
                .update({ is_active: false })
                .eq('id', projectId);

            if (error) throw error;
            set(state => ({
                projects: state.projects.filter(p => p.id !== projectId),
                currentProject: state.currentProject?.id === projectId ? (state.projects.find(p => p.id !== projectId) || null) : state.currentProject
            }));
            return { success: true };
        } catch (err) {
            set({ error: err.message });
            return { success: false, error: err.message };
        } finally {
            set({ loading: false });
        }
    }
}));

import { create } from 'zustand';
import { supabase } from '../lib/supabase';

/**
 * Vessel Store
 * Manages the fleet list, historical tracking, and real-time positions.
 */
export const useVesselStore = create((set, get) => ({
    vessels: [],
    vesselPositions: [],
    loading: false,
    error: null,
    
    // Core Actions
    setVessels: (vessels) => set({ vessels }),
    
    fetchVessels: async () => {
        set({ loading: true });
        try {
            const { data: vesselsData, error: vesselsError } = await supabase
                .from('vessels')
                .select('*')
                .order('name');
            if (vesselsError) throw vesselsError;

            // Fetch active tracking status from the view
            const { data: activeData } = await supabase
                .from('active_vessels')
                .select('id');
            
            const activeIds = new Set(activeData?.map(v => v.id) || []);

            const enrichedVessels = (vesselsData || []).map(v => ({
                ...v,
                tracking_active: activeIds.has(v.id)
            }));

            set({ vessels: enrichedVessels });
        } catch (err) {
            set({ error: err.message });
        } finally {
            set({ loading: false });
        }
    },

    addVessel: async (vessel) => {
        try {
            const { data, error } = await supabase.from('vessels').insert(vessel).select().single();
            if (error) throw error;
            set(state => ({ vessels: [...state.vessels, data] }));
            return { success: true, data };
        } catch (err) {
            return { success: false, error: err.message };
        }
    },

    updateVessel: async (id, updates) => {
        try {
            // Strip out virtual/in-memory properties to avoid PostgREST schema errors
            const { tracking_active, ...cleanUpdates } = updates;
            const { error } = await supabase.from('vessels').update(cleanUpdates).eq('id', id);
            if (error) throw error;
            set(state => ({
                vessels: state.vessels.map(v => v.id === id ? { ...v, ...updates } : v)
            }));
            return { success: true };
        } catch (err) {
            return { success: false, error: err.message };
        }
    },

    deleteVessel: async (id) => {
        try {
            const { error } = await supabase.from('vessels').delete().eq('id', id);
            if (error) throw error;
            set(state => ({ vessels: state.vessels.filter(v => v.id !== id) }));
            return { success: true };
        } catch (err) {
            return { success: false, error: err.message };
        }
    },

    /**
     * Load historical positions from Supabase tracking table.
     * Optimized to fetch only the most recent points if needed.
     */
    loadHistoricalPositions: async (visibleVessels = []) => {
        if (!visibleVessels.length) return;
        
        const visibleIds = visibleVessels.map(v => v.id);
        
        // Calculate yesterday 23:59:59 UTC cutoff for T+1 Certified Historical Mode
        const yesterday = new Date();
        yesterday.setDate(yesterday.getDate() - 1);
        const yesterdayEndIso = `${yesterday.toISOString().split('T')[0]}T23:59:59Z`;

        // Fetch latest point for EACH vessel individually up to yesterday end (T-1)
        const latestPromises = visibleVessels.map(v => 
            supabase
                .from('vessel_tracking')
                .select('vessel_id, mmsi, lat, lon, speed, heading, course, status, timestamp')
                .eq('vessel_id', v.id)
                .lte('timestamp', yesterdayEndIso)
                .order('timestamp', { ascending: false })
                .limit(1)
        );

        const results = await Promise.all(latestPromises);
        
        const latestMap = new Map();
        results.forEach(({ data, error }) => {
            if (!error && data && data.length > 0) {
                latestMap.set(data[0].vessel_id, data[0]);
            }
        });

        const positions = visibleVessels.map(v => {
            const track = latestMap.get(v.id);
            return {
                vessel: v.name,
                vesselId: v.id,
                lat: track?.lat || 0,
                lon: track?.lon || 0,
                speed: track?.speed || 0,
                heading: track?.heading || 0,
                course: track?.course || 0,
                status: track?.status || 'unknown',
                lastUpdate: track?.timestamp || null
            };
        });
        
        set({ vesselPositions: positions });
    },

    /**
     * Subscribe to real-time tracking updates from Supabase.
     */
    subscribeToTracking: (visibleVessels = []) => {
        if (!visibleVessels.length) return null;
        
        const channel = supabase
            .channel('vessel-tracking-realtime')
            .on('postgres_changes', { 
                event: 'INSERT', 
                schema: 'public', 
                table: 'vessel_tracking' 
            }, (payload) => {
                const newPoint = payload.new;
                const { vessels, vesselPositions } = get();
                
                const vessel = vessels.find(v => v.id === newPoint.vessel_id || String(v.mmsi) === String(newPoint.mmsi));
                if (!vessel) return;

                const updatedPositions = vesselPositions.map(pos => {
                    if (pos.vesselId === vessel.id) {
                        return {
                            ...pos,
                            lat: newPoint.lat,
                            lon: newPoint.lon,
                            speed: newPoint.speed,
                            heading: newPoint.heading,
                            status: newPoint.status,
                            lastUpdate: newPoint.timestamp
                        };
                    }
                    return pos;
                });

                set({ vesselPositions: updatedPositions });
            })
            .subscribe();

        return channel;
    },

    /**
     * Overlay Datalastic live data onto the current positions.
     * @deprecated Use subscribeToTracking for DB-driven real-time instead.
     */
    updateLivePositions: (livePositions) => {
        // Keeping this for backward compatibility if needed, 
        // but the goal is to move fully to DB-driven tracking.
        const { vessels, vesselPositions } = get();
        if (!livePositions || !vessels.length || !vesselPositions.length) return;

        const vesselsByName = new Map();
        vessels.forEach(v => { if (v.name) vesselsByName.set(v.name, v); });

        let hasChanges = false;
        const newPositions = vesselPositions.map(pos => {
            const v = vesselsByName.get(pos.vessel);
            if (!v?.mmsi) return pos;
            
            const live = livePositions[v.mmsi];
            if (!live) return pos;

            if (pos.lat === live.lat && pos.lon === live.lon && pos.speed === live.speed && pos.heading === live.course) {
                return pos;
            }
            
            hasChanges = true;
            return {
                ...pos,
                lat: live.lat || pos.lat,
                lon: live.lon || pos.lon,
                speed: live.speed ?? pos.speed,
                heading: live.course ?? pos.heading,
                status: live.status || pos.status,
                lastUpdate: new Date().toISOString()
            };
        });

        if (hasChanges) set({ vesselPositions: newPositions });
    }
}));

import * as XLSX from 'xlsx';

/**
 * Parses an Excel file containing Geofence definitions.
 * Expected columns: Name, Latitude (lat), Longitude (lon), Nature, Family, Color, Vertex.
 * 
 * @param {File} file - The Excel file from the input event
 * @returns {Promise<Array>} - Resolves to an array of parsed Geofence objects ready for insertion
 */
export const parseGeofencesFromExcel = (file) => {
    return new Promise((resolve, reject) => {
        if (!file) return reject(new Error("Nessun file fornito"));

        const reader = new FileReader();
        reader.onload = (evt) => {
            try {
                const bstr = evt.target.result;
                const wb = XLSX.read(bstr, { type: 'binary' });
                const wsname = wb.SheetNames[0];
                const ws = wb.Sheets[wsname];
                const rawData = XLSX.utils.sheet_to_json(ws);

                if (rawData.length === 0) throw new Error("Il file Excel è vuoto.");

                // Normalizza le chiavi di ogni riga in minuscolo per supportare qualsiasi maiuscola/minuscola nelle colonne
                const data = rawData.map(row => {
                    const normalizedRow = {};
                    for (const key in row) {
                        normalizedRow[key.toLowerCase().trim()] = row[key];
                    }
                    return normalizedRow;
                });

                // Group by Geofence Name
                const groups = {};
                data.forEach((row, rowIndex) => {
                    const name = row.name || row.nome || row.geofence;
                    if (!name) {
                        console.warn(`Riga ${rowIndex + 2} saltata: colonna 'Name' non trovata o vuota.`);
                        return;
                    }
                    const nameKey = String(name).trim();
                    if (!groups[nameKey]) groups[nameKey] = [];
                    groups[nameKey].push(row);
                });

                const groupNames = Object.keys(groups);
                if (groupNames.length === 0) {
                    throw new Error("Nessuna colonna 'Name' (o 'name') trovata nel file Excel.");
                }

                const parsedGeofences = [];

                for (const name of groupNames) {
                    const rows = groups[name].sort((a, b) => (parseFloat(a.vertex) || 0) - (parseFloat(b.vertex) || 0));
                    
                    const coords = rows.map((r, idx) => {
                        let latVal = r.latitude !== undefined ? r.latitude : (r.lat !== undefined ? r.lat : r.latitudine);
                        let lonVal = r.longitude !== undefined ? r.longitude : (r.lon !== undefined ? r.lon : r.longitudine);
                        
                        if (typeof latVal === 'string') latVal = latVal.replace(',', '.');
                        if (typeof lonVal === 'string') lonVal = lonVal.replace(',', '.');

                        const lat = parseFloat(latVal);
                        const lon = parseFloat(lonVal);
                        
                        return [lat, lon];
                    }).filter(c => !isNaN(c[0]) && !isNaN(c[1]));

                    if (coords.length < 3) {
                        console.warn(`Geofence "${name}" ignorata: trovati solo ${coords.length} vertici validi (minimo richiesto: 3).`);
                        continue;
                    }

                    // Calculate center (approximate centroid)
                    const lat = coords.reduce((sum, c) => sum + c[0], 0) / coords.length;
                    const lon = coords.reduce((sum, c) => sum + c[1], 0) / coords.length;

                    const nature = rows[0].nature || rows[0].natura || 'general';
                    const family = rows[0].family || rows[0].famiglia || '';
                    const color = rows[0].color || rows[0].colore || '#3b82f6';

                    let natureStr = String(nature).toLowerCase().trim();
                    
                    // Intelligent automatic mapping to match database check constraints
                    if (natureStr === 'quarry' || natureStr === 'cava' || natureStr === 'loading' || natureStr === 'loading site' || natureStr === 'loading_site') {
                        natureStr = 'loading_site';
                    } else if (natureStr === 'unloading' || natureStr === 'unloading site' || natureStr === 'unloading_site' || natureStr === 'diga' || natureStr === 'scarico') {
                        natureStr = 'unloading_site';
                    } else if (natureStr === 'base port' || natureStr === 'base_port' || natureStr === 'porto' || natureStr === 'rada' || natureStr === 'roadstead') {
                        natureStr = 'base_port';
                    } else {
                        natureStr = natureStr.replace(/\s+/g, '_');
                    }

                    parsedGeofences.push({
                        name,
                        nature: natureStr,
                        family: String(family).trim(),
                        color: String(color).trim(),
                        lat,
                        lon,
                        polygon_coords: JSON.stringify(coords)
                    });
                }

                if (parsedGeofences.length === 0) {
                    throw new Error("Il file è stato letto, ma nessun poligono contiene almeno 3 vertici validi. Verifica che le colonne si chiamino 'Name', 'Latitude' (o 'Lat'), 'Longitude' (o 'Lon') e 'Vertex'.");
                }

                resolve(parsedGeofences);
            } catch (err) {
                reject(err);
            }
        };
        reader.onerror = () => reject(new Error("Errore durante la lettura del file."));
        reader.readAsBinaryString(file);
    });
};

/**
 * geoUtils.js — Utility geografiche per il parsing e formatting di coordinate.
 * Estrae da DBManager.jsx le funzioni di conversione DD/DDM.
 * Usato da: DBManager, e potenzialmente da import Excel e form geofence.
 */

/**
 * Parsa una stringa rappresentante una singola coordinata (lat o lon).
 * Supporta formato DD (gradi decimali) e DDM (gradi minuti decimali).
 * @param {string} str
 * @param {boolean} isLat
 * @returns {number} valore decimale, NaN se non parsabile
 */
export const parsePart = (str, isLat) => {
    if (!str) return NaN;
    const cleanStr = str.trim();

    // DDM: es. 44° 07.407' N oppure 44 07.407 N
    const ddmRegex = /(\d+)\s*°?\s*(\d+(?:[.,]\d+)?)\s*'?\s*([NnSsEeWwOo])/i;
    const match = cleanStr.match(ddmRegex);
    if (match) {
        const deg = parseFloat(match[1]);
        const min = parseFloat(match[2].replace(',', '.'));
        const hemi = match[3].toUpperCase();
        let val = deg + (min / 60);
        if (hemi === 'S' || hemi === 'W' || hemi === 'O') val = -val;
        return val;
    }

    // Gradi decimali semplici
    return parseFloat(cleanStr.replace(',', '.'));
};

/**
 * Parsa una riga di testo contenente lat e lon separati da tab, punto e virgola,
 * virgola, spazio o pattern DDM riconoscibili.
 * @param {string} line
 * @returns {[number, number] | null} [lat, lon] oppure null
 */
export const parseCoordinateLine = (line) => {
    let clean = line.trim();
    if (!clean) return null;

    let parts = [];
    if (clean.includes('\t')) {
        parts = clean.split('\t');
    } else if (clean.includes(';')) {
        parts = clean.split(';');
    } else if (clean.includes(',') && (clean.match(/,/g) || []).length === 1) {
        parts = clean.split(',');
    } else {
        const ddmPattern = /\d+\s*°?\s*\d+(?:[.,]\d+)?\s*'?\s*[NnSsEeWwOo]/gi;
        const ddmMatches = clean.match(ddmPattern);
        if (ddmMatches && ddmMatches.length === 2) {
            parts = ddmMatches;
        } else {
            const spaceParts = clean.split(/\s+/).filter(Boolean);
            if (spaceParts.length === 2) {
                parts = spaceParts;
            } else if (clean.includes(',') && (clean.match(/,/g) || []).length === 3) {
                const commaSpaceParts = clean.split(/,\s+/);
                if (commaSpaceParts.length === 2) {
                    parts = commaSpaceParts;
                } else {
                    const commaParts = clean.split(',');
                    if (commaParts.length === 4) {
                        parts = [
                            commaParts[0].trim() + '.' + commaParts[1].trim(),
                            commaParts[2].trim() + '.' + commaParts[3].trim(),
                        ];
                    }
                }
            }
        }
    }

    if (parts.length < 2) return null;

    const lat = parsePart(parts[0], true);
    const lon = parsePart(parts[1], false);
    if (isNaN(lat) || isNaN(lon)) return null;
    return [lat, lon];
};

/**
 * Converte un valore decimale in formato DDM (Gradi Minuti Decimali).
 * Es. 44.1234 → "44° 7.4040' N"
 * @param {number} val
 * @param {boolean} isLat
 * @returns {string}
 */
export const toDDM = (val, isLat) => {
    if (val === undefined || val === null || isNaN(val)) return '';
    const absVal = Math.abs(val);
    const deg = Math.floor(absVal);
    const min = ((absVal - deg) * 60).toFixed(4);
    const hemi = isLat ? (val >= 0 ? 'N' : 'S') : (val >= 0 ? 'E' : 'W');
    return `${deg}° ${min}' ${hemi}`;
};

/**
 * Formatta un array di coordinate [[lat,lon], ...] in stringa leggibile.
 * @param {Array<[number,number]>} coordsArray
 * @param {'DDM'|'DD'} format
 * @returns {string}
 */
export const formatCoords = (coordsArray, format) => {
    if (!Array.isArray(coordsArray)) return '';
    return coordsArray.map(([lat, lon]) => {
        if (format === 'DDM') {
            return `${toDDM(lat, true)}, ${toDDM(lon, false)}`;
        }
        return `${lat.toFixed(8)}, ${lon.toFixed(8)}`;
    }).join('\n');
};
